INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1221, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', '•ಮಡಿಯಲ್ಲಿ ಸಸಿ ಸಾಯುವ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕರ‍್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್  50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು, ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು
•ಸಸಿ ಕತ್ತರಿಸುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೊಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ  2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಬೆರೆಸಿ ಗಿಡದ ಸುತ್ತಲೂ ತೋಯಿಸುವುದು', '• Planting seedlings at 4x2 feet spacing along one side of the bed, keeping in mind the rainfall forecast
• After planting, applying 50% of the recommended nitrogen and full dose of phosphorus and potash fertilizers based on LRI', '•If symptoms of seedling death are seen in the field, spray 2 g Mancozeb 75 WP or 0.5 g Carbendazim 50 WP or 2.5 g Copper Oxychloride 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days. •If seedling cutworm is seen, spray 2 ml Chlorpyrifos 20 EC or 2 ml Quinalphos 25 EC per liter of water and water around the plant', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
