• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', NULL, '• Drain excess water from the land and plant the seedlings at a distance of 4x2 feet on one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potassium fertilizers based on LRI.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1190, 'TOMATO', 69, N'-2', N'-2', 'Preparation', 0, 'NORMAL', 'YES', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, ಬೋದುಗಳನ್ನು ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕ ಹಾಗೂ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್‌ ಯುಕ್ತ ರಸಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Prepardeness: Plough the land and add 25 tonnes of FYM. Apply recommended dose of 75 per cent nitrogen based fertilisers. Uasge of drip pipes and mulching.', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
