INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1197, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'BELOW NORMAL', 'NO', '• ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು', NULL, 'Provide fertilsers through drip', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1198, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Drain out the ABOVE NORMAL water', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1199, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Drain out the ABOVE NORMAL water', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1200, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 2 ಗ್ರಾಂ ಮ್ಯಾಕೋಜೆಬ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿಗೆ ಶೇ.4 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.8 ಮಿ. ಲೀ. ಫ್ಲುಬೆಂಡಿಯಮೈಡ್ 10 EC, 0.25 ಮಿ. ಲೀ. ‌ ಸ್ಪೈನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ. ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'No action needs to be taken.', 'For leaf spot disease spray 2 g Mancozeb 75 WP for one litre of water. If Powdery mildew disease was found spray 3 g wettable sulphur in litre of water. For fruit borer spray 4 per cent neem oil or 0.8 ml or 0.8 ml  Flubendamide 10 EC or 0.25 ml Spinosad 45 SC or 0.5 ml Chlorantriniprole 18.5 SC for litre of water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1201, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 2 ಗ್ರಾಂ ಮ್ಯಾಕೋಜೆಬ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿಗೆ ಶೇ.4 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.8 ಮಿ. ಲೀ. ಫ್ಲುಬೆಂಡಿಯಮೈಡ್ 10 EC, 0.25 ಮಿ. ಲೀ. ‌ ಸ್ಪೈನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ. ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'No action needs to be taken.', 'For leaf spot disease spray 2 g Mancozeb 75 WP for one litre of water. If Powdery mildew disease was found spray 3 g wettable sulphur in litre of water. For fruit borer spray 4 per cent neem oil or 0.8 ml or 0.8 ml  Flubendamide 10 EC or 0.25 ml Spinosad 45 SC or 0.5 ml Chlorantriniprole 18.5 SC for litre of water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1202, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'No action needs to be taken.', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1203, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಆರಂಭದಲ್ಲಿ ಬರುವ ಅಂಗಮಾರಿ ರೋಗ ಹಾಗೂ ಎಲೆ ಸುಡುವ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Provide fertilsers through drip', 'If eraly blight and leaf scald were found apply 2 g Mancozeb for litre of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1204, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Drain out the ABOVE NORMAL water', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
