INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1243, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1244, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'NORMAL', 'YES', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬ್ಲೈಟ್ ಮತ್ತು ಹಣ್ಣು ಕೊಳೆರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು', 'Harvesting eggplants', 'If symptoms of blight and fruit rot are seen, spray with 2 grams of Mancozeb 75 WP or 0.5 grams of Carbendazim 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1245, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'NORMAL', 'NO', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬ್ಲೈಟ್ ಮತ್ತು ಹಣ್ಣು ಕೊಳೆರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು', 'Harvesting eggplants', 'If symptoms of blight and fruit rot are seen, spray with 2 grams of Mancozeb 75 WP or 0.5 grams of Carbendazim 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1246, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'BELOW NORMAL', 'YES', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting eggplants', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1247, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Conservation irrigation using water available from agricultural wells and other sources
• Harvesting brinjals', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1248, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'ABOVE NORMAL', 'YES', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1249, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1250, 'BRINJAL', 12, N'>28 Weeks', N'>28 Weeks', 'Post Harvest', 6, 'NIL', 'NIL', '• ಕೊನೆಯ ಕೊಯ್ಲಿನ ತಕ್ಷಣವೇ ಎಲ್ಲಾ ಗಿಡಗಳನ್ನು ಬೇರುಸಮೇತ ತೆಗೆಯಿಸಿ ನಾಶಪಡಿಸಬೇಕು, ಇದರಿಂದ ಶೂಟ್‌ ಮತ್ತು ಹಣ್ಣು ತಿನ್ನುವ ಹುಳದ ಮುಂದುವರಿದ ಸೋಂಕು ನಿಯಂತ್ರಿಸಬಹುದು
• ಬೇಸಿಗೆ ಕಾಲದಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡುವುದು, ಇದರಿಂದ ಕೀಟಗಳ ಅವಶೇಷಗಳು (ಲಾರ್ವಾ ಮತ್ತು ಪುಪಾಗಳು) ಹೊರಬಂದು ನಾಶವಾಗುತ್ತವೆ
• ಕನಿಷ್ಠ ಒಂದು ಋತುವಿನವರೆಗೆ ಅದೇ ಹೊಲದಲ್ಲಿ ಮತ್ತೆ ಬದನೆಕಾಯಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸುವುದು ಉತ್ತಮ
• ಮಣ್ಣಿನ ರಚನೆ ಮತ್ತು ಆರೋಗ್ಯವನ್ನು ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು
• ಮಣ್ಣಿನ ಸಾರಜನಕ ಸಮತೋಲನ ಸುಧಾರಿಸಲು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು', NULL, '• Uproot and destroy all plants immediately after the last harvest to control further infestation of shoot and fruit borers
• Deep ploughing during summer season to remove and destroy insect remains (larvae and pupae)
• Avoid growing brinjal again in the same field for at least one season
• Incorporate organic manures into the soil to improve soil structure and health
• Rotate crops with legumes to improve soil nitrogen balance', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1225, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', '•ಗುಲಗಂಜಿ ಹುಳು, ಜಿಗಿ ಹುಳು ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆಗಳ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ. ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಸಣ್ಣ ಎಲೆಗಳ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪಿಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ರೋಗ ಹರಡುವ ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Drain excess water from the land and plant the seedlings at a distance of 4x2 feet on one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potassium fertilizers based on LRI.', '•If there is a problem of mealybug, scale insect and mealybug, spray with 1.7 ml. Dimethoate 30 EC or 2 ml. Quinalphos 25 EC per liter of water
•If there is a problem of small leaf spot, it is better to uproot and destroy the diseased plants and spray with 1.7 ml. Dimethoate 30 EC per liter of water to control the disease-spreading insects', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1226, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಗುಲಗಂಜಿ ಹುಳು, ಜಿಗಿ ಹುಳು ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆಗಳ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ. ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಸಣ್ಣ ಎಲೆಗಳ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪಿಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ರೋಗ ಹರಡುವ ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Providing support for plants to grow upright
• Weed management through intercropping', '•If there is a problem of mealybug, scale insect and mealybug, spray with 1.7 ml. Dimethoate 30 EC or 2 ml. Quinalphos 25 EC per liter of water
•If there is a problem of small leaf spot, it is better to uproot and destroy the diseased plants and spray with 1.7 ml. Dimethoate 30 EC per liter of water to control the disease-spreading insects', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1227, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'NORMAL', 'NO', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಗುಲಗಂಜಿ ಹುಳು, ಜಿಗಿ ಹುಳು ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆಗಳ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ. ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಸಣ್ಣ ಎಲೆಗಳ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪಿಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ರೋಗ ಹರಡುವ ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Providing support for plants to grow upright
• Weed management through intercropping', '•If there is a problem of mealybug, scale insect and mealybug, spray with 1.7 ml. Dimethoate 30 EC or 2 ml. Quinalphos 25 EC per liter of water
•If there is a problem of small leaf spot, it is better to uproot and destroy the diseased plants and spray with 1.7 ml. Dimethoate 30 EC per liter of water to control the disease-spreading insects', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1228, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', NULL, '• Providing support for plants to grow upright
• Weed management through intercropping', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1296, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'NORMAL', 'YES', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಕುಡಿ ಕೊರೆಯುವ ಹುಳು ಭಾದೆಗೊಂಡ ಕಾಂಡದ ತುದಿಗಳನ್ನು ಚಿವುಟಿ ನಾಶಪಡಿಸಿ, ಬೆಳೆಗೆ 1 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ್ 75 ಡಬ್ಲೂಪಿ. ಅಥವಾ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 ಇ.ಸಿ.ಯನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'Pinch off and destroy the stem ends affected by the stem borer and spray the crop with 1 gm Thiodicarb 75 WP or 2 ml Malathion 50 EC per litre of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1297, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'NORMAL', 'NO', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಕುಡಿ ಕೊರೆಯುವ ಹುಳು ಭಾದೆಗೊಂಡ ಕಾಂಡದ ತುದಿಗಳನ್ನು ಚಿವುಟಿ ನಾಶಪಡಿಸಿ, ಬೆಳೆಗೆ 1 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ್ 75 ಡಬ್ಲೂಪಿ. ಅಥವಾ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 ಇ.ಸಿ.ಯನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'Pinch off and destroy the stem ends affected by the stem borer and spray the crop with 1 gm Thiodicarb 75 WP or 2 ml Malathion 50 EC per litre of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1298, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'BELOW NORMAL', 'YES', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಮೊದಲದ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಡೈಫೆನ್‌ಕೊನಾಜೋಲ್ 10 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯಾಪ್ಟಾನ್ 50 WP ಯನ್ನು ಬೇರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'If early stage of leaf spot is detected, spray 1 ml of Difenconazole 10 WP or 2 gm Mancozeb 75 WP or 2.5 gm Captan 50 WP per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1299, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಯ ಮೊಳಕೆಯೊಡೆಯದಂತಿರಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಎಂ.ಹೆಚ್. (ಶೇ. 0.3) ಸಿಂಪಡಿಸುವುದು', NULL, '• Provide conservation irrigation using water available from agricultural wells and other sources
• Spray MH (0.3%) 4 weeks before harvest to prevent potato sprouting during storage', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1300, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1301, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1302, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'NORMAL', 'YES', 'ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಗೊಣ್ಣೆಹುಳುವಿನ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ 5 ಮಿ.ಲೀ ಕ್ಲೋರೊಪೈರಿಫೋಸ್ 20 ಇಸಿ ಬೆರಸಿ ತಯೆರಿಸಿದ 500 ಲೀಟರ್ ದ್ರಾವಣವನ್ನು ಬೇರು ತೊಯುವ ಹಾಗೆ ಸಿಂಪಡಿಸಬೇಕು', 'Harvesting tubers', 'If aphid infestation is found, 500 liters of a solution prepared by mixing 5 ml of Chlorpyrifos 20 EC per liter of water should be sprayed as a root-drench', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1310, 'ONION', 46, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿತನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ, ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕನ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', 'ಪ್ರತಿ ಕಿ.ಗ್ರಾಂ ಬೀಜಕ್ಕೆ 15 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 60 FS ಜೊತೆಗೆ 5 ಗ್ರಾಂ ಸುಡೋಮೊನಾಸ್‍ ರಿಂದ ಬೀಜೋಪಚರಿಸಿ ಬಿತ್ತುವುದರಿಂದ ಈರುಳ್ಳಿ ಬೆಳೆಯ ಕೀಟ ಮತ್ತು ರೋಗವನ್ನು ನಿಯಂತ್ರಿಸಬಹುದು', 'Preparation: Plow the land 2-3 times, add the recommended amount of manure to the soil, add 50% of the recommended amount of nitrogen, full amount of phosphorus and potash to the soil based on LRI.', 'Pests and diseases of onion crop can be controlled by treating the seeds with 15 ml of Imidacloprid 60 FS and 5 g of Pseudomonas per kg of seeds', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1311, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'NORMAL', 'YES', 'ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿಯ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ. ಆಸಿಟಮಾಪ್ರತಿಡ್‍20 SP ಅಥವಾ 0.3 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 1 ಮಿ.ಲೀ. ಪಿಫ್ರೋನಿಲ್ 5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting seedlings at a distance of 10 cm.', 'For the control of thrips, spray 0.2 gm. Acetamaprid 20 SP or 0.3 gm. Thiomethoxam 25 WG or 1 ml. Pifronil 5 SC per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1312, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿಯ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ. ಆಸಿಟಮಾಪ್ರತಿಡ್‍20 SP ಅಥವಾ 0.3 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 1 ಮಿ.ಲೀ. ಪಿಫ್ರೋನಿಲ್ 5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting seedlings at a distance of 10 cm, keeping in mind the rainfall forecast.', 'For the control of thrips, spray 0.2 gm. Acetamaprid 20 SP or 0.3 gm. Thiomethoxam 25 WG or 1 ml. Pifronil 5 SC per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1313, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, seedlings should be planted at a distance of 10 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
