INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1305, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'BELOW NORMAL', 'NO', 'ಜಮೀನಿಗೆ ನೀರು ಒದಗಿಸಿ ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಿ ನಂತರ ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Watering the field, loosening the soil, and then harvesting the tubers', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1306, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting tubers', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1307, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting tubers', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1308, 'POTATO', 51, N'16-17 weeks', N'16-17 weeks', 'Post harvest 1', 6, 'NIL', 'NIL', '• ಕೊಯ್ಲಿನ ನಂತರ ಗಡ್ಡೆಯ ಹೊರ ಚರ್ಮ ಹದಕ್ಕೆ ಬರಲು ಅಗೆದು ತೆಗೆದ ಗಡ್ಡೆಗಳನ್ನು ಚೆನ್ನಾಗಿ ಗಾಳಿಯಾಡುವಂತಹ ಒಣ ಪ್ರದೇಶದಲ್ಲಿ (8-10 ದಿನಗಳು) ಹರಡುವುದು
• ಸಂಗ್ರಹಣೆಗೆ ಮುಂಚೆ ಸಂಗ್ರಹಣಾ ಕೊಠಡಿಯಲ್ಲಿ ಸಿ.ಐ.ಪಿ.ಸಿ. (500-1000 ppm) ಧೂಪ ಹಾಕಿ ನಂತರ ಸಂಗ್ರಹಿಸುವುದರಿಂದ ಗೆಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದು ಕಡಿಮೆಯಾಗುತ್ತದೆ', 'ಕೊನೆಯ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗಕ್ಕೆ ಶಿಫಾರಸ್ಸು ಮಾಡಲಾದ ಶಿಲೀಂಧ್ರಾನಾಶಕಗಳನ್ನು ಪುನರಾವರ್ತನೆ ಮಾಡುವುದು. ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಅಜಕ್ಸಿಸ್ಟ್ರೋಬಿನ್‍ 23 SC ಅಥವಾ 20 ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ+3 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್‍ 75 WP ಅನ್ನು ಸೇರಿಸಿ ಬೆಳೆಗೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• After harvesting, spread the dug tubers in a well-ventilated dry area (8-10 days) to allow the tuber skin to soften. • Before storage, fumigation of the storage room with CIPC (500-1000 ppm) and subsequent storage reduces the germination of tubers.', 'Repeat the recommended fungicides for late blight. It is better to spray the crop by adding 1 ml of Azaxystrobin 23 SC or 20 gm neem powder + 3 gm Mancozeb 75 WP per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1309, 'POTATO', 51, N'18-19 weeks', N'>17 weeks', 'Post harvest 2', 7, 'NIL', 'NIL', '• ಹೊಲದಲ್ಲಿ ಉಳಿದಿರುವ ಎಲ್ಲಾ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ತಡವಾಗಿ ಬರುವ ಅಂಗಮಾರಿ ರೋಗದ ಮುಂದುವರಿದ ಸೋಂಕು ತಪ್ಪಿಸಬಹುದು
• ಬೇಸಿಗೆ ಕಾಲದಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣನ್ನು ಸೂರ್ಯಕಿರಣಗಳಿಗೆ ಒಡ್ಡುವುದರಿಂದ ನೆಮಾಟೋಡ್‌ಗಳ ಸಂಖ್ಯೆ ಕಡಿಮೆಯಾಗುತ್ತದೆ
• ಅದೇ ಹೊಲದಲ್ಲಿ ನಿರಂತರವಾಗಿ ಆಲೂಗಡ್ಡೆ ಬೆಳೆಯನ್ನು ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ, ಬೆಳೆ ಬದಲಾವಣೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Destroy all crop residues in the field to prevent further infection of late blight
• Deep ploughing during summer and exposure of the soil to sunlight reduces the number of nematodes
• Avoid growing potato continuously in the same field and rotate crops', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1267, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ  ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಎನ್. ಎ. ಎ. (ಫ್ಲಾನೋಫಿಕ್ಸ್) ಅನ್ನು 50 ಮಿ. ಗ್ರಾಂ 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದರಿಂದ ಹೂವು ಉದುರುವುದು ನಿಲ್ಲುತ್ತದೆ', 'ಹಣ್ಣು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1ಗ್ರಾಂ ಕಾರ್ಬಂಡೈಜಿಮ್ 50 WP ಬೆರೆಸಿ, 15 ದನಗಳ ಅಂತರದಲ್ಲಿ ನಾಲ್ಕು ಸಾರಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Apply 50% of the recommended LRI based nitrogen, phosphorus and potash as top dressing to the plants
• Provide conservation irrigation using water available from agricultural wells and other sources
• Spray N. A. A. (Flanofix) at 50 mg. gm. in 1 l. of water to stop flower drop', 'When fruit rot disease is detected, it is best to spray 1 gram of Carbandizim 50 WP per liter of water and spray four times at an interval of 15 cm', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1268, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'ABOVE NORMAL', 'YES', '• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ
• ಹಸಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬೂದಿ ರೋಗ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ  ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡೈಜಿಮ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಅಥವಾ 1 ಮಿ.ಲೀ ಪೆನ್‌ಕೊನಾಜೋಲ್ 10 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ತಿವ್ರತೆ ಕಂಡುಬಂದಲ್ಲಿ ಸಿಂಪರಣೆಯನ್ನು 15 ದಿನಗಳಿಗೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• If there has been heavy rainfall in the past few days, allow the water to drain away from the field. • Harvesting green beans', 'If powdery mildew is found, spray with 1 gram of Carbendazim 50 WP or 3 grams of water-soluble sulfur or 1 ml of Penconazole 10 EC per liter of water. If the disease is severe, it is better to spray once in 15 days', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1269, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'ABOVE NORMAL', 'NO', '• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ
• ಹಸಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಕಾಯಿ ಕೊರಕದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.25 ಫ್ಲುಬೆಂಡಿಯಾಮೈಡ್ 39.35 SC ಅಥವಾ 2 ಮಿ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 50 EC ಅಥವಾ ಶೇ.5 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು', '• If there has been heavy rainfall in the past few days, allow the water to drain away from the field. • Harvesting green beans', 'To control the nut borer, spray 0.25 ml of Flubendiamide 39.35 SC or 2 ml of Chlorpyrifos 50 EC or 5% neem seed extract per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1270, 'CHILLIES', 20, N'20-28 weeks', N'20-28', 'Harvesting stage', 4, 'NORMAL', 'YES', 'ಒಣ ಮೆಣಸಿನಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting dry chilies', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1271, 'CHILLIES', 20, N'20-28 weeks', N'20-28', 'Harvesting stage', 4, 'NORMAL', 'NO', 'ಒಣ ಮೆಣಸಿನಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting dry chilies', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1272, 'CHILLIES', 20, N'20-28 weeks', N'20-28', 'Harvesting stage', 4, 'BELOW NORMAL', 'YES', 'ಒಣ ಮೆಣಸಿನಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting dry chilies', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
