INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1293, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Apply 50% of the recommended nitrogen fertilizer based on LRI to the plants as top dressing
• Provide conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1294, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕೊನೆಯ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ತಡೆಗಟ್ಟಲು ಬಿತ್ತಿದ 5 ವಾರಗಳ ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್‍ 75 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾನೆಬ್ ಅಥವಾ 3 ಗ್ರಾಂ ಫಿನಾಮಿಡಾನ್‍+ಮ್ಯಾಂಕೋಜೆಬ್‍ 60 WP ಅಥವಾ 1 ಮಿ.ಲೀ. ಅಜಕ್ಸಿಸ್ಟ್ರೋಬಿನ್‍ 23 SC ಅನ್ನು ಸೇರಿಸಿ ಬೆಳೆಗೆ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'To prevent late blight, spray the crop with 2 g Mancozeb 75 WP or 2 g Maneb or 3 g Fenamidon + Mancozeb 60 WP or 1 ml Azaxystrobin 23 SC per liter of water 5 weeks after sowing', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1295, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1325, 'ONION', 46, N'10-13 weeks', N'10-13', 'Bulb development stage', 3, 'BELOW NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ನಂತರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣು ಏರು ಹಾಕುವುದು', 'ಕಾಡಿಗೆ ರೋಗ ಹಾಗೂ ಆಲ್ಟರ್ನೆರಿಯಾ ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್‍75 WP ಅಥವಾ 1 ಮಿ.ಲೀ ಡೈಪೆಕೊನಜೋಲ್ 25 EC ಅಥವಾ 1.5 ಮಿ.ಲೀ ಅಜಾಕ್ಸಿಸ್ಟ್ರೋಬಿನ್‍ 11 % + ಟೆಬುಕೊನಜೋಲ್ 18.3% ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI
• Then mulching the soil at the base of the plants', 'If you find Alternaria leaf spot or Alternaria leaf spot, spray with 2 grams of Mancozeb 75 WP or 1 ml of Dipeconazole 25 EC or 1.5 ml of Azoxystrobin 11% + Tebuconazole 18.3% per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1326, 'ONION', 46, N'10-13 weeks', N'10-13', 'Bulb development stage', 3, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ನಂತರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣು ಏರು ಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ನೇರಳೆ ಎಲೆಮಚ್ಚೆ ರೋಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನಿರಿಗೆ 1 ಮಿ.ಲೀ ಹೆಕ್ಸಾಕೊನಾಜೋಲ್ 5 EC ಅಥವಾ 1 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 25 % EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯುಪ್ರಸ್ ಆಕ್ಸೈಡ್ 82% WP ಅನ್ನು ಬೆರಸಿ 15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಎರಡು ಬಾರಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI
• Then mulching the soil at the base of the plants
• Conservation irrigation using water available from agricultural wells and other sources', 'To control purple leaf spot, it is best to spray twice at an interval of 15 days with 1 ml of Hexaconazole 5 EC or 1 ml of Propiconazole 25% EC or 2.5 gm of Cuprous Oxide 82% WP per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
