• ಮಣ್ಣಿನಲ್ಲಿ ಇರುವ ಹಣ್ಣುನೊಣದ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸಲು ಆಳವಾದ ಉಳುಮೆ ಮಾಡಿ, ಮಣ್ಣನ್ನು ಸೂರ್ಯನ ಕಿರಣಗಳಿಗೆ ಒಡ್ಡುವುದು
• ಮುಂದಿನ ಋತುವಿನ ಬೆಳೆಗಾಗಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸಿ
• ಕೀಟಗಳ ಜೀವನಚಕ್ರವನ್ನು ಮುರಿಯಲು ಕುಂಬಳ ಜಾತಿಗೆ ಸೇರಿರದ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1375, 'CABBAGE', 13, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ಧತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಹದಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಿ ಅಲ್ಪಾವಧಿ ತಳಿಗಳಿಗೆ 45 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ತಯಾರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್ ಗೊಬ್ಬರ ಹಾಕಿ ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸುವುದು
ಅಲ್ಪಾವಧಿ ತಳಿಗಳು: ಪ್ರೈಡ್ಡ್ ಆಫ ಇಂಡಿಯಾ,  ಗೋಲ್ಡನ್ ಏಕರ್, ಅರ್ಲಿ ಡ್ರಮ್ ಹೆಡ್', NULL, 'Preparation: After ploughing and harrowing the land 2-3 times, mix the recommended manure with the soil well and make furrows at a distance of 45 cm for short-duration varieties and apply 50% nitrogen and full amount of phosphorus and potash fertilizer as recommended based on LRI and mix it well into the soil. Short-duration varieties: Proud of India, Golden Acre, Early Drum Head', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
