INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1377, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting seedlings at a distance of 30 cm, keeping in mind the rainfall forecast.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
