INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1380, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1381, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1382, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'YES', 'ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', '•ಎಲೆ ಮಚ್ಚೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WPಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ವಜ್ರ ಗುರುತಿನ ಬೆನ್ನಿನ ಪತಂಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಥೈಯಾಕ್ಲೋಪ್ರಿಡ್ 21.7 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Planting another plant in a place where the tree is not established', '•If leaf spot disease is found, spray 3.0 g of copper oxychloride 50 WP or 2.0 g of metalaxyl MZ 72 WP per liter of water
•For the control of diamondback moth, spray 0.3 ml of spinosad 45 SC or 2.0 ml of thiacloprid 21.7 SC or 0.5 ml of chloranthraniliprol 18.5 SC per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1333, 'ONION', 46, N'14-17 weeks', N'14-17', 'Harvesting stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿ, ಕೊಯ್ಲು ಮಾಡುವುದು', 'ನೇರಳೆ ಎಲೆಮಚ್ಚೆ ರೋಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನಿರಿಗೆ 1 ಮಿ.ಲೀ ಹೆಕ್ಸಾಕೊನಾಜೋಲ್ 5 EC ಅಥವಾ 1 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 25 % EC ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯುಪ್ರಸ್ ಆಕ್ಸೈಡ್ 82% WP ಅನ್ನು ಬೆರಸಿ 15 ದಿನಗಳ ಅಂತರದಲ್ಲಿ ಎರಡು ಬಾರಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', 'If there has been heavy rainfall in the past few days, allow the water to drain away from the field and harvest.', 'To control purple leaf spot, it is best to spray twice at an interval of 15 days with 1 ml of Hexaconazole 5 EC or 1 ml of Propiconazole 25% EC or 2.5 gm of Cuprous Oxide 82% WP per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1334, 'ONION', 46, N'14-17 weeks', N'14-17', 'Harvesting stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿ, ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away from the field and harvest.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1335, 'ONION', 46, N'18-19 weeks', N'18-19', 'Post harvesting 1', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲಿನ ನಂತರ ಗಡ್ಡೆಗಳನ್ನು ಚೆನ್ನಾಗಿ ಗಾಳಿಯಾಡುವಂತಹ ಒಣ ಪ್ರದೇಶದಲ್ಲಿ ಹರಡುವುದರಿಂದ ಗಡ್ಡೆಯ ಹೊರ ಪಡರ ಚೆನ್ನಾಗಿ ಒಣಗುತ್ತದೆ
• ಸಂಗ್ರಹಣಾ ಕೊಠಡಿಯಲ್ಲಿ ಸರಿಯಾದ ಗಾಳಿಚಲನೆ ಮತ್ತು ತೇವಾಂಶವನ್ನು ನಿರ್ವಹಣೆ ಮಾಡುವುದು ಅತ್ಯವಶ್ಯಕ', NULL, '• Spreading the tubers in a well-ventilated, dry area after harvesting will help the outer skin of the tuber dry out better. • Maintaining proper ventilation and humidity in the storage room is essential.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1336, 'ONION', 46, N'>19 weeks', N'>19', 'Post harvesting 2', 6, 'NIL', 'NIL', '• ಥ್ರಿಪ್ಸ್‌ಗಳ ಸಂಖ್ಯೆಯನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಹೊಲದಲ್ಲಿರುವ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟ ಮತ್ತು ರೋಗಾಣುಗಳನ್ನು ಕಡಿಮೆ ಮಾಡಲು ಬೇಸಿಗೆ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣನ್ನು ಸೂರ್ಯನ ಕಿರಣಗಳಿಗೆ ಒಡ್ಡುವುದು
• ದ್ವಿದಳ ಧಾನ್ಯ ಬೆಳೆಯೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Remove and destroy all crop residues in the field to reduce thrips numbers
• Summer ploughing to expose the soil to sunlight to reduce soil borne pests and pathogens
• Crop rotation with legume crops is advisable', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1337, 'CUCUMBER', NULL, N'o week', N'0', 'Preparation', 0, 'NIL', 'NIL', 'ಭೂಮಿಯನ್ನು 2 ರಿಂದ 3 ಸಾರಿ ಉಳುಮೆ ಮಾಡಿ ಚೆನ್ನಾಗಿ ಹದ ಮಾಡಬೇಕು. 1.5 ರಿಂದ 2 ಮೀಟರ್ ಅಂತರದಲ್ಲಿ ಹರಿಗಳನ್ನು ತೆಗೆಯಬೇಕು. ಚೆನ್ನಾಗಿ ಕೊಳೆತ ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಬೇಕು. ಬಿತ್ತುವ ಪೂರ್ವದಲ್ಲಿಯೇ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇಕಡಾ 50 ರಷ್ಟು ಸಾರಜನಕ, ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಒದಗಿಸಬೇಕು. 75 ರಿಂದ 90 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ 3-4 ಬೀಜಗಳನ್ನು ಬಿತ್ತಬೇಕು. ಬೆಳಗಾವಿ ಲೋಕಲ್, ಹಿಮಾಂಗಿ ಲೋಕಲ್, ಜಪ್ನೀಸ್ ಉದ್ದ ಹಸಿರು ನಾಟಿಗೆ ಸೂಕ್ತತಳಿಗಳು', NULL, 'Prepardeness: Plough the land for 2-3 times. Prepare bed of size of 1.5 to 2 meter. Apply FYM and before planting apply 50% recommended dose of nitrogenous fertilizer and full Phosphorus and potassium fertilizers. Cover the bed with plastic. Sow 3-4 the seeds at a spacing of 75 to 90 cm. After 15 days leave one or two plant and remove others', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1338, 'CUCUMBER', NULL, N'1 weeks', N'1', 'Germination stage', 1, 'NORMAL', 'YES', 'ಬಿತ್ತಿದ 15 ದಿನಗಳಲ್ಲಿ ಬಂದಿರುವ ಸಸಿಗಳಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಅಥವಾ ಎರಡು ಸಸಿಗಳು ಉಳಿಯುವಂತೆ ಬಿಟ್ಟು ಉಳಿದವನ್ನು ಕಿತ್ತು ಹಾಕಬೇಕು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಎರಡು ವರ್ಷಕ್ಕೊಮ್ಮೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡಬೇಕು (ರಾಗಿ/ ಮೆಕ್ಕೆಜೋಳ/ ಜೋಳದೊಂದಿಗೆ) ಬಿತ್ತನೆ ಪೂರ್ವದಲ್ಲಿ ಹೆಕ್ಟೇರಿಗೆ 15 ಕಿ.ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್ ಪುಡಿಯನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸಿ ನೀರು ಹಾಯಿಸಬೇಕು', '4 weeks after planting apply remaining 50% of nitrogenous fertilizer mix properly in soil.', 'For Bacterial wilt disease follow crop rotation with finger millet/ maize / jowar. Before sowing add 15 Kg bleaching powder to soil and give water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1339, 'CUCUMBER', NULL, N'1 weeks', N'1', 'Germination stage', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬಿತ್ತಿದ 15 ದಿನಗಳಲ್ಲಿ ಬಂದಿರುವ ಸಸಿಗಳಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಅಥವಾ ಎರಡು ಸಸಿಗಳು ಉಳಿಯುವಂತೆ ಬಿಟ್ಟು ಉಳಿದವನ್ನು ಕಿತ್ತು ಹಾಕಬೇಕು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಎರಡು ವರ್ಷಕ್ಕೊಮ್ಮೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡಬೇಕು (ರಾಗಿ/ ಮೆಕ್ಕೆಜೋಳ/ ಜೋಳದೊಂದಿಗೆ) ಬಿತ್ತನೆ ಪೂರ್ವದಲ್ಲಿ ಹೆಕ್ಟೇರಿಗೆ 15 ಕಿ.ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್ ಪುಡಿಯನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸಿ ನೀರು ಹಾಯಿಸಬೇಕು', '4 weeks after planting apply remaining 50% of nitrogenous fertilizer mix properly in soil.', 'For Bacterial wilt disease follow crop rotation with finger millet/ maize / jowar. Before sowing add 15 Kg bleaching powder to soil and give water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1340, 'CUCUMBER', NULL, N'1 weeks', N'1', 'Germination stage', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತಿದ 15 ದಿನಗಳಲ್ಲಿ ಬಂದಿರುವ ಸಸಿಗಳಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಅಥವಾ ಎರಡು ಸಸಿಗಳು ಉಳಿಯುವಂತೆ ಬಿಟ್ಟು ಉಳಿದವನ್ನು ಕಿತ್ತು ಹಾಕಬೇಕು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1341, 'CUCUMBER', NULL, N'1 weeks', N'1', 'Germination stage', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತಿದ 15 ದಿನಗಳಲ್ಲಿ ಬಂದಿರುವ ಸಸಿಗಳಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಅಥವಾ ಎರಡು ಸಸಿಗಳು ಉಳಿಯುವಂತೆ ಬಿಟ್ಟು ಉಳಿದವನ್ನು ಕಿತ್ತು ಹಾಕಬೇಕು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
