INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1343, 'CUCUMBER', NULL, N'1 weeks', N'1', 'Germination stage', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತಿದ 15 ದಿನಗಳಲ್ಲಿ ಬಂದಿರುವ ಸಸಿಗಳಲ್ಲಿ ಪ್ರತಿ ಗುಣಿಗೆ ಒಂದು ಅಥವಾ ಎರಡು ಸಸಿಗಳು ಉಳಿಯುವಂತೆ ಬಿಟ್ಟು ಉಳಿದವನ್ನು ಕಿತ್ತು ಹಾಕಬೇಕು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1344, 'CUCUMBER', NULL, N'2-3 weeks', N'2-3', 'Seedling development stage', 2, 'NORMAL', 'YES', 'ಬಿತ್ತಿದ ನಾಲ್ಕು ವಾರಗಳ ನಂತರ ಉಳಿದ ಶೇ.50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸಿ ಏರು ಮಡಿಗಳಾಗಿ ಮಣ್ಣನ್ನು ಚೆನ್ನಾಗಿ ವಿಸ್ತರಿಸಬೇಕು', 'ಕೆಂಪು ಕುಂಬಳ ದುಂಬಿ ಹತೋಟಿಗೆ ಬಿತ್ತನೆಯಾದ 3 ವಾರಗಳ ನಂತರ ಬೆಳೆಗೆ 4 ಗ್ರಾಂ ಕಾರ್ಬಾರಿಲ್ ಶೇ. 50 WP ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'No action needs to be taken.', 'For Red pumpkin beetle 3 weeks after sowing spray 4 g carbaryl 50% per liter of water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1345, 'CUCUMBER', NULL, N'2-3 weeks', N'2-3', 'Seedling development stage', 2, 'NORMAL', 'NO', 'ಬಿತ್ತಿದ ನಾಲ್ಕು ವಾರಗಳ ನಂತರ ಉಳಿದ ಶೇ.50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸಿ ಏರು ಮಡಿಗಳಾಗಿ ಮಣ್ಣನ್ನು ಚೆನ್ನಾಗಿ ವಿಸ್ತರಿಸಬೇಕು', 'ಕೆಂಪು ಕುಂಬಳ ದುಂಬಿ ಹತೋಟಿಗೆ ಬಿತ್ತನೆಯಾದ 3 ವಾರಗಳ ನಂತರ ಬೆಳೆಗೆ 4 ಗ್ರಾಂ ಕಾರ್ಬಾರಿಲ್ ಶೇ. 50 WP ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'No action needs to be taken.', 'For Red pumpkin beetle 3 weeks after sowing spray 4 g carbaryl 50% per liter of water.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1346, 'CUCUMBER', NULL, N'2-3 weeks', N'2-3', 'Seedling development stage', 2, 'BELOW NORMAL', 'YES', '250 ಪಿ.ಪಿ.ಎಂ. ಸಾಂದ್ರತೆಯ ಇಥೆರೆಲ್ ದ್ರಾವಣವನ್ನು ಬಳ್ಳಿಗಳಲ್ಲಿ 2-4 ಎಲೆಗಳು ಬಂದ ನಂತರ 15 ದಿವಸಗಳ ಅಂತರದಲ್ಲಿ ಎರಡು ಸಾರಿ ಸಿಂಪಡಣೆ ಮಾಡುವುದರಿಂದ ಹೆಚ್ಚು ಹೂವುಗಳು ಬಿಟ್ಟು ಬೇಗನೆ ಕಾಯಿಗಳು ಕೊಯ್ಲಿಗೆ ಬರುತ್ತದೆ', NULL, 'At 2-4 leaf stage spray 250 ppm ethrel two times at 15 days interval this will increase flower set and early fruit harvasting.', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1347, 'CUCUMBER', NULL, N'2-3 weeks', N'2-3', 'Seedling development stage', 2, 'BELOW NORMAL', 'NO', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸಿ', NULL, 'No action needs to be taken.', 'No action needs to be taken.', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
