INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1404, 'CABBAGE', 13, N'9 week', N'9', 'Harvesting stage', 5, 'ABOVE NORMAL', 'YES', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1405, 'CABBAGE', 13, N'9 week', N'9', 'Harvesting stage', 5, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1406, 'CABBAGE', 13, N'>9 Weeks', N'>9', 'Post harvest', 6, 'NIL', 'NIL', '• ಕ್ಲಬ್‌ರೂಟ್‌ ರೋಗ ಅಥವಾ ವಜ್ರ ಬೆನ್ನಿನ ಪತಂಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ರೋಗ ಹಾಗೂ ಕೀಟಗಳ ಮುಂದುವರಿದ ಸೋಂಕನ್ನು ತಪ್ಪಿಸಬಹುದು
• ನಿರಂತರವಾಗಿ ಎಲೆಕೋಸು ಜಾತಿಯ ಬೆಳೆಗಳನ್ನು ಅದೇ ಹೊಲದಲ್ಲಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮಜೀವಿ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಸೇರಿಸುವುದು', NULL, '• Remove and destroy all crop residues, including those affected by clubroot disease or diamondback moth, to prevent further spread of disease and pests
• Rotate crops by avoiding continuous cultivation of cabbage varieties in the same field
• Deep summer tillage to destroy soil-borne pest residues
• Add organic manure to improve soil health by increasing soil microbial activity', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1407, 'CABBAGE', 13, N'0 week', N'0', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ಧತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಹದಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಿ ದೀರ್ಘಾವಧಿ ತಳಿಗಳಿಗೆ 60 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ತಯಾರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್ ಗೊಬ್ಬರ ಹಾಕಿ ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸುವುದು
ದೀರ್ಘಾವಧಿ ತಳಿಗಳು: ಲೇಟ್ ಡ್ರಮ್ ಹೆಡ್,  ಡ್ಯಾನಿಷ್ ಬಾಲ್ ಹೆಡ್', NULL, 'Preparation: After ploughing and harrowing the land 2-3 times, mix the recommended amount of manure well into the soil and for long-term varieties, make holes at a distance of 60 cm and prepare furrows, apply 50% nitrogen and full amount of phosphorus and potash fertilizer as recommended based on LRI and mix well into the soil. Long-term varieties: Late Drum Head, Danish Ball Head', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1408, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'NORMAL', 'YES', 'ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1409, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting seedlings at a distance of 30 cm, keeping in mind the rainfall forecast.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1410, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, seedlings should be planted at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1411, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, seedlings should be planted at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1412, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1413, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1414, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'YES', 'ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', '•ಎಲೆ ಮಚ್ಚೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WPಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ವಜ್ರ ಗುರುತಿನ ಬೆನ್ನಿನ ಪತಂಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಥೈಯಾಕ್ಲೋಪ್ರಿಡ್ 21.7 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Planting another plant in a place where the tree is not established', '•If leaf spot disease is found, spray 3.0 g of copper oxychloride 50 WP or 2.0 g of metalaxyl MZ 72 WP per liter of water
•For the control of diamondback moth, spray 0.3 ml of spinosad 45 SC or 2.0 ml of thiacloprid 21.7 SC or 0.5 ml of chloranthraniliprol 18.5 SC per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1415, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'NO', 'ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', '•ಎಲೆ ಮಚ್ಚೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WPಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ವಜ್ರ ಗುರುತಿನ ಬೆನ್ನಿನ ಪತಂಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಥೈಯಾಕ್ಲೋಪ್ರಿಡ್ 21.7 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Planting another plant in a place where the tree is not established', '•If leaf spot disease is found, spray 3.0 g of copper oxychloride 50 WP or 2.0 g of metalaxyl MZ 72 WP per liter of water
•For the control of diamondback moth, spray 0.3 ml of spinosad 45 SC or 2.0 ml of thiacloprid 21.7 SC or 0.5 ml of chloranthraniliprol 18.5 SC per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1416, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'BELOW NORMAL', 'YES', 'ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', NULL, 'Planting another plant in a place where the tree is not established', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1417, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'BELOW NORMAL', 'NO', '• ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Planting other plants in areas where the pea is not established
• Providing conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1418, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು, ಕೊಂಡಲ್ಲಿ ಹುಳು, ಗೆಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು, ಸಾಸಿವೆ ಗರಗಸದ ಹುಳು ಹಾಗೂ ಎಲೆಕೋಸು ತಿಗಣೆ  ಕಾಣಿಸಿಕೊಂಡಾಗ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ ಅಸಿಟಾಮಾಫ್ರಿಡ್ 20 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಟಾಲ್‌ಫೇನ್‌ಪೈರಾಡ್ 15 EC ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರಿನಿಲಿಪ್ರೋಲ್ 10.26 OD ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'When aphids, leafhoppers, tuber borers, mustard sawflies and cabbage loopers appear, spray 0.2 g Acetamafrid 20 SP or 2.0 ml Talfenpyrad 15 EC or 1.0 ml Cyanthriniliprol 10.26 OD per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1444, 'CABBAGE', 13, N'>12 Weeks', N'>12', 'Post harvest', 6, 'NIL', 'NIL', '• ಕ್ಲಬ್‌ರೂಟ್‌ ರೋಗ ಅಥವಾ ವಜ್ರ ಬೆನ್ನಿನ ಪತಂಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ರೋಗ ಹಾಗೂ ಕೀಟಗಳ ಮುಂದುವರಿದ ಸೋಂಕನ್ನು ತಪ್ಪಿಸಬಹುದು
• ನಿರಂತರವಾಗಿ ಎಲೆಕೋಸು ಜಾತಿಯ ಬೆಳೆಗಳನ್ನು ಅದೇ ಹೊಲದಲ್ಲಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮಜೀವಿ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಸೇರಿಸುವುದು', NULL, '• Remove and destroy all crop residues, including those affected by clubroot disease or diamondback moth, to prevent further spread of disease and pests
• Rotate crops by avoiding continuous cultivation of cabbage varieties in the same field
• Deep summer tillage to destroy soil-borne pest residues
• Add organic manure to improve soil health by increasing soil microbial activity', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1445, 'CAULIFLOWER', NULL, N'0 week', N'0', 'Preparation', 0, 'NORMAL', 'YES', 'ಪೂರ್ವಸಿದ್ದತೆ: ಅಲ್ಪಾವಧಿ ತಳಿಗಳು 45 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಮತ್ತು ದೀರ್ಘಾವಧಿ ತಳಿಗಳಾದಲ್ಲಿ 60 ಸೆಂ. ಮೀ. ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ತಯಾರಿಸಿ, ಹರಿಗಳಲ್ಲಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೋಟ್ಯಾಷ್ ಗೊಬ್ಬರ ಹಾಕಿ ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಬೇಕು. 7.5 ಸೆಂ. ಮೀ. ಅಂತರದ ಸಾಲುಗಳಲ್ಲಿ ಬೀಜಗಳನ್ನು ಬಿತ್ತಿ, ಬೀಜದ ಮೇಲೆ ತೆಳುವಾಗಿ ಮಣ್ಣನ್ನು ಹಾಕಿ ನೀರನ್ನು ಒದಗಿಸಬೇಕು. ಹಿಮ ಚೆಂಡು, ತಡವಾದ ಹಿಮ ಚೆಂಡು, ಸ್ನೋಬಾಲ್, ಅರ್ಕಾ ವಿಮಲ್, ಅರ್ಕಾ ಸ್ಫೂರ್ತಿ ನಾಟಿಗೆ ಸೂಕ್ತ ತಳಿಗಳು', 'ಬೀಜವನ್ನು 1.5 ಗ್ರಾಂ ಪಾದರಸ ಸಂಯುಕ್ತ ವಸ್ತುವನ್ನು 1.5 ಲೀ. ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷಗಳ ಕಾಲ ಅದ್ದಿ ತೆಗೆದು ನೆರಳಿನಲ್ಲಿ ಒಣಗಿಸಿ ಬಿತ್ತನೆ ಮಾಡಬೇಕು', NULL, 'Preparedness: For early variety 45 cm and for late variety 60 cm spacing given.Apply 50% of nitrogen and full dose of phoshorus and pottash fertilizer.', '1.5 g Seeds should be soaked in murcury pore it in 1.5 liter of water after  30 minutes dry the seeds and use for sowing.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
