INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1447, 'CAULIFLOWER', NULL, N'1 week', N'1', 'Transplanting', 1, 'NORMAL', 'YES', 'ಅಲ್ಪಾವಧಿ ತಳಿಗಳನ್ನು45 ಸೆಂ. ಮೀ. ಮತ್ತು ಧೀರ್ಘಾವಧಿ ತಳಿಗಳನ್ನು 60 ಸೆಂ.ಮೀ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡಬೇಕು. ಪ್ರತಿ 3-4 ದಿನಗಳಿಗೊಮ್ಮೆ ನೀರನ್ನು ಹಾಯಿಸಬೇಕು', NULL, NULL, 'Transplant the short duration varieties at 30 cm and for long duration 60 cm.  Irrigate the crop once in 3-4 days.', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1448, 'CAULIFLOWER', NULL, N'1 week', N'1', 'Transplanting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಅಲ್ಪಾವಧಿ ತಳಿಗಳನ್ನು45 ಸೆಂ. ಮೀ. ಮತ್ತು ಧೀರ್ಘಾವಧಿ ತಳಿಗಳನ್ನು 60 ಸೆಂ.ಮೀ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡಬೇಕು. ಪ್ರತಿ 3-4 ದಿನಗಳಿಗೊಮ್ಮೆ ನೀರನ್ನು ಹಾಯಿಸಬೇಕು', NULL, NULL, 'Transplant the short duration varieties at 30 cm and for long duration 60 cm.  Irrigate the crop once in 3-4 days.', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1478, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 1 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಾಸಿಹಲೋಥ್ರಿನ್ 5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', '•If stem and tuber borer is found, spray 0.25 ml. Spinosad 45 SC or 1 ml. Lambdacyhalothrin 5 EC per liter of water or mix 250 kg. Neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 200 SL per liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1479, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'BELOW NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1480, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching around the plant
• Conservation irrigation using water available from farm wells and other sources', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1481, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ರೋಗಗ್ರಸ್ಥ ಗಡ್ಡೆಗಳನ್ನು ತೆಗೆದು ಹಾಕಿ, ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍3 ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್‍ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣವನ್ನು ರೋಗ ಬಂದ ಮಡಿಗೆ ಹಾಗೂ ಸುತ್ತಮುತ್ತಲಿನ ಮಡಿಗಳಿಗೆ ಹಾಕುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If tuber rot is detected, remove the diseased tubers and then apply a solution prepared by mixing 3 grams of copper oxychloride 50 WP per 3 liters of water to the affected tuber and surrounding tubers', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1482, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1488, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1489, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕೊಂಬು ಮತ್ತು ಬೇರು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದರೆ ಶೇ. 1ರ ಬೋರ್ಡೊ ದ್ರಾವಣ ಅಥವಾ ಶೇ. 0.3 ರ ಮ್ಯಾಂಕೋಜೆಬ್ ದ್ರಾವಣವನ್ನು ಬೇರು ನೆನೆಯುವಂತೆ ಸುರಿಯವುದು
•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Harvesting tubers', '•If stem and root rot disease is found, spray 1% Bordeaux mixture or 0.3% Mancozeb solution as a root drench. •If powdery mildew disease is found, spray 2 grams Mancozeb 75 WP or 1 gram Carbondiazim 50 WP dissolved in every liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1490, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'NO', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕೊಂಬು ಮತ್ತು ಬೇರು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದರೆ ಶೇ. 1ರ ಬೋರ್ಡೊ ದ್ರಾವಣ ಅಥವಾ ಶೇ. 0.3 ರ ಮ್ಯಾಂಕೋಜೆಬ್ ದ್ರಾವಣವನ್ನು ಬೇರು ನೆನೆಯುವಂತೆ ಸುರಿಯವುದು
•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Harvesting tubers', '•If stem and root rot disease is found, spray 1% Bordeaux mixture or 0.3% Mancozeb solution as a root drench. •If powdery mildew disease is found, spray 2 grams Mancozeb 75 WP or 1 gram Carbondiazim 50 WP dissolved in every liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1491, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', 'Harvesting tubers', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1492, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'NO', 'ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಲು ನೀರಾವರಿ ಒದಗಿಸಿ ನಂತರ ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Irrigation to loosen the soil and then harvesting', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
