INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1483, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', '•ಎಲೆ ತಿನ್ನುವ ಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ ಶೇ. 5 ರ ಬೇವಿನ ಕಷಾಯ ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ. ಲೀ. ಫೋಸಲೋನ್ 50 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆಚುಕ್ಕೆ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗಗಳ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', '•If leaf-eating worms are found, spray with 5% neem infusion or 2 ml. Quinalphos 25 EC or 2 ml. Phosalone 50 EC per liter of water
•If leaf spot and powdery mildew are found, spray with 2 gm Mancozeb 75 WP or 1 gm Carbondiazim 50 WP dissolved in 1 liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1484, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', '•ಎಲೆ ತಿನ್ನುವ ಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ ಶೇ. 5 ರ ಬೇವಿನ ಕಷಾಯ ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ. ಲೀ. ಫೋಸಲೋನ್ 50 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆಚುಕ್ಕೆ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗಗಳ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', '•If leaf-eating worms are found, spray with 5% neem infusion or 2 ml. Quinalphos 25 EC or 2 ml. Phosalone 50 EC per liter of water
•If leaf spot and powdery mildew are found, spray with 2 gm Mancozeb 75 WP or 1 gm Carbondiazim 50 WP dissolved in 1 liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1485, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1486, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸಿ', NULL, '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• If the crop is doing well at the current stage, focus on managing other crops if they are growing.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1487, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ರೋಗಗ್ರಸ್ಥ ಗಡ್ಡೆಗಳನ್ನು ತೆಗೆದು ಹಾಕಿ, ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍3 ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್‍ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣವನ್ನು ರೋಗ ಬಂದ ಮಡಿಗೆ ಹಾಗೂ ಸುತ್ತಮುತ್ತಲಿನ ಮಡಿಗಳಿಗೆ ಹಾಕುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If tuber rot is detected, remove the diseased tubers and then apply a solution prepared by mixing 3 grams of copper oxychloride 50 WP per 3 liters of water to the affected tuber and surrounding tubers', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1449, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'YES', 'LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ ಮಳೆ ಇಲ್ಲದ ಪಕ್ಷದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಒದಗಿಸುವುದು', NULL, NULL, 'Apply FYM 25 tonn 150:100:125 Kg fertilizers per hactor.', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1450, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'NO', 'LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಕೊಡುವುದು. ನಾಟಿ ಮಾಡಿದ ನಂತರ ಮಳೆ ಇಲ್ಲದ ಪಕ್ಷದಲ್ಲಿ ಗಿಡಗಳಿಗೆ ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಒದಗಿಸುವುದು', NULL, NULL, 'Apply FYM 25 tonn 150:100:125 Kg fertilizers per hactor.', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1451, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'BELOW NORMAL', 'YES', 'ನಾಟಿಯಾದ ನಂತರದಲ್ಲಿ ಕಳೆಗಳನ್ನು ತೆಗೆದು ಸ್ವಚ್ಛ ಮಾಡಬೇಕು', NULL, NULL, 'After planting weeding should be followed.', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1452, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'BELOW NORMAL', 'NO', 'ನೀರು ನಿಂತಿದ್ದಲ್ಲಿ ನೀರನ್ನು ಬಸಿಯುವಂತೆ ಮಾಡಬೇಕು', 'ನಾಟಿ ಮಾಡಿದ 4 ವಾರಗಳ ನಂತರ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡಬೇಕು', NULL, 'Drain the excess water from the field', 'Four weeks after planting apply remaining 50% nitrogen.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1453, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'ABOVE NORMAL', 'YES', 'ಕಳೆ ಇಲ್ಲದಂತೆ ನೋಡಿಕೊಳ್ಳಬೇಕು', 'ಎಲೆ ಮಚ್ಚೆ ರೋಗ : ಬಿತ್ತನೆಯಾದ 2 ಮತ್ತು4 ವಾರಗಳ ನಂತರ ಸಸಿ ಮಡಿಯಲ್ಲಿ ಸಸಿಗಳಿಗೆ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು. ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡಿದ 6 ಮತ್ತು 8 ವಾರಗಳ ನಂತರ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಸೇರಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', NULL, 'Weeding operation', 'For leaf spot: 2-4 weeks after planting  spray 3 g copper oxychloride 50WP per liter of water. 6-8 weeks after planting spray 3 g copper oxychloride 50WP per liter of water.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1454, 'CAULIFLOWER', NULL, N'2 weeks', N'2', 'Establishment stage', 2, 'ABOVE NORMAL', 'NO', 'ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', NULL, NULL, 'Weeding operation and mulch the soil using dried leaves', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1455, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, NULL, 'Provide irrigation for 1-2 years old plants', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1456, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, NULL, 'Provide irrigation for 1-2 years old plants', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1457, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'BELOW NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು. ಸುರುಳಿ ಪೂಚಿ, ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು. ಸಾಸಿವೆ ಗರಗಸ ನೊಣ ಹತೋಟಿಗೆ ಬಿತ್ತನೆಯಾದ 2 ಮತ್ತು 4 ವಾರಗಳ ನಂತರ ಸಸಿ ಮಡಿಯಲ್ಲಿ ಸಸಿಗಳಿಗೆ 0.5 ಮಿ.ಲೀ. ಫಾಸ್ಫಾಮಿಡಾನ್ 40 EC ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಆಕ್ಸಿಡೆಮಿಟಾನ್ ಮಿಥೈಲ್ 25 EC ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ ಸೇರಿಸಿ ಸಿಂಪಡಿಸಬೇಕು', NULL, NULL, 'Aphids, leaf webber, head borer, musturd saw fly 2 to 4 weeks after planting spray 0.5 ml phosphomedon 40EC or 1.7 ml oxydemeton methyl 25 EC per liter of water.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1458, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, NULL, NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1459, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'ABOVE NORMAL', 'YES', 'ಉಳಿದ ಶೇ. ೫೦ ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು. ಮಣ್ಣನ್ನು ಏರಿಸುವುದು', 'ಬಿಳಿ ತುಕ್ಕು ರೋಗ : ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2 ಗ್ರಾಂ ಜೈನೆಬ್ ಬೆರೆಸಿದ ದ್ರಾವಣ ಸಿಂಪಡಣೆ ಕೈಕೊಳ್ಳಬೇಕು', NULL, 'Provide irrigation for 1-2 years old plants', 'White rust: spray 2g mancozeb 75 WP or 2 g zineb per liter of water.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1460, 'CAULIFLOWER', NULL, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'ABOVE NORMAL', 'NO', 'ಉಳಿದ ಶೇ. ೫೦ ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು. ಮಣ್ಣನ್ನು ಏರಿಸುವುದು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
