INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1462, 'CAULIFLOWER', NULL, N'7-8 weeks', N'7-8', 'Curd development stage', 4, 'NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1463, 'CAULIFLOWER', NULL, N'7-8 weeks', N'7-8', 'Curd development stage', 4, 'BELOW NORMAL', 'YES', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ವಜ್ರದ ಬೆನ್ನಿನ ಚಿಟ್ಟೆ (ಡೈಮಂಡ್ ಬ್ಯಾಕ್ ಮಾಥ್) ಹತೋಟಿಗೆ ಫೆರೋಮೋನ್ ಬಲೆ ಬಳಸಬೇಕು (5 ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ) ಅಥವಾ ಅಜರ್ಡೆಕ್ಟಿನ್ 300 PPM 2 ಮಿ.ಲೀ. ಅಥವಾ ಸ್ಪಿನೋಸಾಡ್ 2.5% SC ಪ್ರತೀ ಲೀಟರ್ ನೀರಿಗೆ ಸೇರಿಸಿ ಸಿಂಪಡಣೆ ಮಾಡಬೇಕು', NULL, NULL, 'To control diamond  back moth spray pheremon trap 5 per hactoror  azardectin 3000 ppm 2ml or  spinosad 2.5% SC 1.2 ml per liter of water.', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
