INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1468, 'CAULIFLOWER', NULL, N'9 week', N'9', 'Harvesting stage', 5, 'NORMAL', 'NO', 'ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, NULL, NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1469, 'CAULIFLOWER', NULL, N'> 10 week', N'> 10', 'Post harvest', 6, 'NIL', 'NIL', '• ಕ್ಲಬ್‌ರೂಟ್‌ ರೋಗ ಅಥವಾ ವಜ್ರ ಬೆನ್ನಿನ ಪತಂಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ರೋಗ ಹಾಗೂ ಕೀಟಗಳ ಮುಂದುವರಿದ ಸೋಂಕನ್ನು ತಪ್ಪಿಸಬಹುದು
• ನಿರಂತರವಾಗಿ ಎಲೆಕೋಸು ಜಾತಿಯ ಬೆಳೆಗಳನ್ನು ಅದೇ ಹೊಲದಲ್ಲಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮಜೀವಿ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಸೇರಿಸುವುದು', NULL, NULL, NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1470, 'GINGER', 29, N'-2', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವ ಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡುವಾಗ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು. 3 ಅಡಿ ಅಗಲದ, ಅರ್ಧ ಅಡಿ ಎತ್ತರದ ಏರು ಮಡಿಗಳನ್ನು ತಯಾರಿಸಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Pre-preparation: Incorporate the recommended amount of manure into the soil while ploughing the land. Prepare 3 feet wide, half a foot high raised beds and apply the full amount of phosphorus and potash fertilizers recommended based on LRI to the soil.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1471, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'NORMAL', 'YES', '• ಬಿತ್ತನೆಗಿಂತ ಮುಂಚೆ ಬೀಜದ ಗಡ್ಡೆಗಳನ್ನು 2 ಗ್ರಾಂ ಬ್ಲಿಚಿಂಗ್ ಪೌಡರ್, 1 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ ಎಂಝಡ್-72, 1 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ ಮತ್ತು 2 ಮಿ.ಲೀ. ಎಂಡೋಸಲ್ಫಾನ್ ಕೀಟನಾಶಕಗಳನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿಗೆ ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷ ನೆನೆಸಿ ನೆರಳಿನಲ್ಲಿ ಹರಡಿ ನಾಟಿಗೆ ಬಳಸುವುದರಿಂದ ಗೆಡ್ಡೆ ಕೊಳೆ ರೋಗ ಮತ್ತು ಶಲ್ಕ ಕೀಟಗಳ ಬಾಧೆಯಿಂದ ರಕ್ಷಿಸಬಹುದು.  ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 30 ರಿಂದ 40 ದಿನಗಳ ನಂತರವೂ, ಉಳಿದ ಶೇ. 50 ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 60 ರಿಂದ 70 ದಿನಗಳ ನಂತರವೂ ಕೊಡುವುದು
• ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, '• Before sowing, the seed tubers can be protected from tuber rot and scale insects by soaking them in a solution of 2 g bleaching powder, 1 g metalaxyl MZ-72, 1 g streptocycline and 2 ml endosulfan insecticide per liter of water for 30 minutes and spreading them in the shade before planting. 50% nitrogen should be given 30 to 40 days after planting and the remaining 50% nitrogen should be given 60 to 70 days after planting. • Sowing ginger pieces (pieces weighing at least 15-25 g) should be planted in the beds at a distance of 1 foot.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1472, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seeded ginger pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot, keeping in mind the rainfall forecast', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1473, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting ginger seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1474, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting ginger seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1475, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the land and plant the ginger seed pieces (pieces weighing at least 15-25 grams) in the beds at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1476, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the land and plant the ginger seed pieces (pieces weighing at least 15-25 grams) in the beds at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1477, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 1 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಾಸಿಹಲೋಥ್ರಿನ್ 5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', '•If stem and tuber borer is found, spray 0.25 ml. Spinosad 45 SC or 1 ml. Lambdacyhalothrin 5 EC per liter of water or mix 250 kg. Neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 200 SL per liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1435, 'CABBAGE', 13, N'9-10 week', N'9-10', 'Head development stage', 5, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ವಜ್ರದ ಬೆನ್ನಿನ ಚಿಟ್ಟೆ (ಡೈಮಂಡ್ ಬ್ಯಾಕ್ ಮಾಥ್) ಹತೋಟಿಗೆ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 5 ಫೆರೋಮೋನ್ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು  ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಗ್ರಾಂ ಇಂಡಾಕ್ಸಕಾರ್ಬ 14.5 SC ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್‍ ಬೆಂಜೋಯೆಟ್‍ ಅಥವಾ 1.0 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ 75 WP ಅಥವಾ 2 ಮಿ.ಲೀ.  ಅಜರ್ಡೆಕ್ಟಿನ್ 300 ppm ಅಥವಾ 1 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರಿನಿಲಿಪ್ರೋಲ್‍ 10.26 OD ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಣೆ  ಮಾಡುವುದು', '• Weed management through intercropping
• Conservation irrigation using water available from agricultural wells and other sources', 'For the control of diamondback moth, use 5 pheromone traps per hectare and spray with 0.3 g indoxacarb 14.5 SC or 0.2 g emamectin benzoate or 1.0 g thiodicarb 75 WP or 2 ml azardectin 300 ppm or 1 ml cyanthrinyl 10.26 OD per liter of water', NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1436, 'CABBAGE', 13, N'9-10 week', N'9-10', 'Head development stage', 5, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
