INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1522, 'TOMATO', 69, N'-2', N'-2', 'Preparation', 0, 'NORMAL', 'YES', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, ಬೋದುಗಳನ್ನು ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕ ಹಾಗೂ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್‌ ಯುಕ್ತ ರಸಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Prepardeness: Plough the land and add 25 tonnes of FYM. Apply recommended dose of 75 per cent nitrogen based fertilisers. Uasge of drip pipes and mulching.', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1523, 'TOMATO', 69, N'-2', N'-2', 'Preparation', 0, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, ಬೋದುಗಳನ್ನು ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕ ಹಾಗೂ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್‌ ಯುಕ್ತ ರಸಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Prepardeness: Plough the land and add 25 tonnes of FYM. Apply recommended dose of 75 per cent nitrogen based fertilisers. Uasge of drip pipes and mulching.', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1524, 'TOMATO', 69, N'1', N'1', 'Transplanting', 1, 'NORMAL', 'YES', '• ಟೊಮ್ಯಾಟೊ  ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿ ಮಾಡುವಾಗ ಪ್ರತಿ 16 ಟೊಮ್ಯಾಟೊ ಸಾಲುಗಳಿಗೆ 1 ಸಾಲು ಆಫ್ರಿಕನ್ ಚೆಂಡು ಹೂವನ್ನು ಅಥವಾ ಆಫ್ರಿಕನ್ ಟಾಲ್ ಮೆಕ್ಕೆ ಜೋಳವನ್ನು ತಡೆ ಬೆಳೆಯಾಗಿ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿನ ಬಾಧೆ ಕಡಿಮೆಯಾಗುತ್ತದೆ', NULL, 'Planting of seedlings. During planting sow 1 row of african marigold or African tall maize in every 16th row of tomato plants as border crop', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1525, 'TOMATO', 69, N'1', N'1', 'Transplanting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಟೊಮ್ಯಾಟೊ  ಸಸಿಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿ ಮಾಡುವಾಗ ಪ್ರತಿ 16 ಟೊಮ್ಯಾಟೊ ಸಾಲುಗಳಿಗೆ 1 ಸಾಲು ಆಫ್ರಿಕನ್ ಚೆಂಡು ಹೂವನ್ನು ಅಥವಾ ಆಫ್ರಿಕನ್ ಟಾಲ್ ಮೆಕ್ಕೆ ಜೋಳವನ್ನು ತಡೆ ಬೆಳೆಯಾಗಿ ನಾಟಿ ಮಾಡುವುದರಿಂದ ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿನ ಬಾಧೆ ಕಡಿಮೆಯಾಗುತ್ತದೆ', NULL, 'Planting of seedlings. During planting sow 1 row of african marigold or African tall maize in every 16th row of tomato plants as border crop', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1526, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'NORMAL', 'YES', '• ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸುವುದು', 'ಎಲೆ ಮುದುಡು ರೋಗ ಹಾಗೂ ಜಿಗಿಹುಳು, ಹೇನು, ಬಿಳಿನೊಣ ಮತ್ತು ಎಲೆ ಸುರಂಗ ಕೀಟಗಳು ಕಂಡು ಬಂದಲ್ಲಿ ಎಕೆರೆಗೆ 15 ಹಳದಿ ಮೋಹಕ ಅಂಟು ಬಲೆಗಳನ್ನು   ಬಳಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.8 ಮಿ. ಲೀ. ಸೈಯಾಂಟ್ರಾನಿಲಿಪ್ರೊಲ್ 10.26 OD ಅಥವಾ 0.3 ಗ್ರಾಂ. ಥಯಾಮಿಥಾಕ್ಸಾಮ್ 25 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'No action needs to be taken.', 'For leaf curl disease, aphids, whitefly, leaf hoppers and leaf eating caterpillar install yellow sticky traps 15 per acre and 1.8 ml cyantriniprole 10.26 OD or 0.3 g Thiamethoxam 25 WP for one litre of water.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1527, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'NORMAL', 'NO', '• ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು
