INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1530, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Drain out the ABOVE NORMAL water', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1531, 'TOMATO', 69, N'3-5', N'3-5', 'Vegetative stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'Drain out the ABOVE NORMAL water', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1532, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 2 ಗ್ರಾಂ ಮ್ಯಾಕೋಜೆಬ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿಗೆ ಶೇ.4 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.8 ಮಿ. ಲೀ. ಫ್ಲುಬೆಂಡಿಯಮೈಡ್ 10 EC, 0.25 ಮಿ. ಲೀ. ‌ ಸ್ಪೈನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ. ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'No action needs to be taken.', 'For leaf spot disease spray 2 g Mancozeb 75 WP for one litre of water. If Powdery mildew disease was found spray 3 g wettable sulphur in litre of water. For fruit borer spray 4 per cent neem oil or 0.8 ml or 0.8 ml  Flubendamide 10 EC or 0.25 ml Spinosad 45 SC or 0.5 ml Chlorantriniprole 18.5 SC for litre of water.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1533, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ 2 ಗ್ರಾಂ ಮ್ಯಾಕೋಜೆಬ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳುವಿಗೆ ಶೇ.4 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.8 ಮಿ. ಲೀ. ಫ್ಲುಬೆಂಡಿಯಮೈಡ್ 10 EC, 0.25 ಮಿ. ಲೀ. ‌ ಸ್ಪೈನೋಸಾಡ್ 45 SC ಅಥವಾ 0.5 ಮಿ. ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'No action needs to be taken.', 'For leaf spot disease spray 2 g Mancozeb 75 WP for one litre of water. If Powdery mildew disease was found spray 3 g wettable sulphur in litre of water. For fruit borer spray 4 per cent neem oil or 0.8 ml or 0.8 ml  Flubendamide 10 EC or 0.25 ml Spinosad 45 SC or 0.5 ml Chlorantriniprole 18.5 SC for litre of water.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1534, 'TOMATO', 69, N'6-10', N'6-10', 'Flower initiation to Flowering', 3, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'No action needs to be taken.', 'No action needs to be taken.', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1495, 'GINGER', 29, N'>36', N'>36', 'Post harvest stage', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲು ಮುಗಿದ ನಂತರ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ಭೂಮಿಗೆ ಸೇರಿಸುವುದು
• ಭೂಮಿಯನ್ನು ಬೇಸಿಗೆ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಸೂರ್ಯಕಿರಣಕ್ಕೆ ಒಡ್ಡುವುದು, ಇದರಿಂದ ರೋಗ ಅಥವಾ ಕೀಟಗಳ ಅವಶೇಷಗಳು ನಾಶವಾಗುತ್ತದೆ
• ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಬಹುದು
• ಮುಂದಿನ ಹಂಗಾಮಿನಲ್ಲಿ ದ್ವಿದಳ ಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Incorporate crop residues into the soil after harvest
• Deep ploughing of the soil in summer and exposure to sunlight, which destroys any disease or insect residues
• Incorporating organic manure into the soil
• Growing green manure crops can improve soil health
• It is better to rotate crops with legumes in the next season', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1496, 'TURMERIC', 71, N'-2', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವ ಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡುವಾಗ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು. 3 ಅಡಿ ಅಗಲದ, ಅರ್ಧ ಅಡಿ ಎತ್ತರದ ಏರು ಮಡಿಗಳನ್ನು ತಯಾರಿಸಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Pre-preparation: Incorporate the recommended amount of manure into the soil while ploughing the land. Prepare 3 feet wide, half a foot high raised beds and apply the full amount of phosphorus and potash fertilizers recommended based on LRI to the soil.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1497, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'NORMAL', 'YES', '• ಬಿತ್ತನೆಗಿಂತ ಮುಂಚೆ ಬೀಜದ ಗಡ್ಡೆಗಳನ್ನು 2 ಗ್ರಾಂ ಬ್ಲಿಚಿಂಗ್ ಪೌಡರ್, 1 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ ಎಂಝಡ್-72, 1 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ ಮತ್ತು 2 ಮಿ.ಲೀ. ಎಂಡೋಸಲ್ಫಾನ್ ಕೀಟನಾಶಕಗಳನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿಗೆ ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷ ನೆನೆಸಿ ನೆರಳಿನಲ್ಲಿ ಹರಡಿ ನಾಟಿಗೆ ಬಳಸುವುದರಿಂದ ಗೆಡ್ಡೆ ಕೊಳೆ ರೋಗ ಮತ್ತು ಶಲ್ಕ ಕೀಟಗಳ ಬಾಧೆಯಿಂದ ರಕ್ಷಿಸಬಹುದು.  ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 30 ರಿಂದ 40 ದಿನಗಳ ನಂತರವೂ, ಉಳಿದ ಶೇ. 50 ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 60 ರಿಂದ 70 ದಿನಗಳ ನಂತರವೂ ಕೊಡುವುದು
• ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, '• Before sowing, the seed tubers can be protected from tuber rot and scale insects by soaking them in a solution of 2 g bleaching powder, 1 g metalaxyl MZ-72, 1 g streptocycline and 2 ml endosulfan insecticide per liter of water for 30 minutes and spreading them in the shade before planting. 50% nitrogen should be given 30 to 40 days after planting and the remaining 50% nitrogen should be given 60 to 70 days after planting. • Sowing pieces (pieces weighing at least 15-25 g) should be planted in the furrows at a distance of 1 foot.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1498, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seed pieces (pieces weighing at least 15-25 grams) in furrows at a distance of 1 foot, keeping in mind the rainfall forecast', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1499, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting of seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1500, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting of seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1501, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the field and plant the seed pieces (pieces weighing at least 15-25 grams) in the furrows at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1502, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the field and plant the seed pieces (pieces weighing at least 15-25 grams) in the furrows at a distance of 1 foot.', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1503, 'TURMERIC', 71, N'2-10', N'2-10', 'Growth stage', 2, 'NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', 'ಬೇರು ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಶೇ. 1 ಬೋರ್ಡೋ ದ್ರಾವಣ ಅಥವಾ ಶೇ 0.3 ರ ಮ್ಯಾಂಕೋಜೆಬ್‍ ದ್ರಾವಣವನ್ನು ಬೆರೆಸಿ ಬೇರು ನೆನೆಯುವಂತೆ ಸುರಿಯುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
