INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1514, 'TURMERIC', 71, N'11-24', N'11-24', 'Rhizome development stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1515, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 ಇಸಿ. ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Harvesting tubers', '•If stem and tuber borer is found, spray 0.25 ml. of Spinosad 45 SC per liter of water or mix 250 kg of neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. of Dimethoate 30 EC per liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1516, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'NO', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 ಇಸಿ. ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Harvesting tubers', '•If stem and tuber borer is found, spray 0.25 ml. of Spinosad 45 SC per liter of water or mix 250 kg of neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. of Dimethoate 30 EC per liter of water', 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1517, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting tubers', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1518, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'NO', 'ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಲು ನೀರಾವರಿ ಒದಗಿಸಿ ನಂತರ ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Irrigation to loosen the soil and then harvesting', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1519, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1520, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, 'NIL', NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1521, 'TURMERIC', 71, N'>36', N'>36', 'Post aharvest', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲು ಮುಗಿದ ನಂತರ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ಭೂಮಿಗೆ ಸೇರಿಸುವುದು
• ಭೂಮಿಯನ್ನು ಬೇಸಿಗೆ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಸೂರ್ಯಕಿರಣಕ್ಕೆ ಒಡ್ಡುವುದು, ಇದರಿಂದ ರೋಗ ಅಥವಾ ಕೀಟಗಳ ಅವಶೇಷಗಳು ನಾಶವಾಗುತ್ತದೆ
• ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಬಹುದು
• ಮುಂದಿನ ಹಂಗಾಮಿನಲ್ಲಿ ದ್ವಿದಳ ಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Incorporate crop residues into the soil after harvest
• Deep ploughing of the soil in summer and exposure to sunlight, which destroys any disease or insect residues
• Incorporating organic manure into the soil
• Growing green manure crops can improve soil health
• It is better to rotate crops with legumes in the next season', NULL, NULL, NULL, 'NIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1553, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', '•ಮಡಿಯಲ್ಲಿ ಸಸಿ ಸಾಯುವ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕರ‍್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್  50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು, ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು
•ಸಸಿ ಕತ್ತರಿಸುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೊಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ  2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಬೆರೆಸಿ ಗಿಡದ ಸುತ್ತಲೂ ತೋಯಿಸುವುದು', '• Planting seedlings at 4x2 feet spacing along one side of the bed, keeping in mind the rainfall forecast
• After planting, applying 50% of the recommended nitrogen and full dose of phosphorus and potash fertilizers based on LRI', '•If symptoms of seedling death are seen in the field, spray 2 g Mancozeb 75 WP or 0.5 g Carbendazim 50 WP or 2.5 g Copper Oxychloride 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days. •If seedling cutworm is seen, spray 2 ml Chlorpyrifos 20 EC or 2 ml Quinalphos 25 EC per liter of water and water around the plant', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1554, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'YES', '• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', NULL, '• If irrigation facilities are available, plant the seedlings at a spacing of 4x2 feet along one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potash fertilizers based on LRI.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1555, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'NO', '• ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', NULL, '• If irrigation facilities are available, plant the seedlings at a spacing of 4x2 feet along one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potash fertilizers based on LRI.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1556, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'YES', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', NULL, '• Drain excess water from the land and plant the seedlings at a distance of 4x2 feet on one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potassium fertilizers based on LRI.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1571, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'NORMAL', 'NO', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಕಾಂಡ, ಕುಡಿ ಮತ್ತು ಕಾಯಿ ಕೊರೆಯುವ ಹುಳುಗಳು ಕಂಡುಬಂದಾಗ ಕಾಯಿಬಿಡುವ ಸಮಯದಲ್ಲಿ 15 ದಿವಸಗಳ ಅಂತರದಲ್ಲಿ 2-3 ಸಾರಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 0.5 ಡೆಲ್ಟಾಮಿಥ್ರಿನ್ 2.8 EC ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೋಯೇಟ್ 5 SG ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಮತ್ತು ದುಂಡಾಣು ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ  ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಮೈಸಿನ್ ಸಲ್ಫೇಟ್ ಮತ್ತು 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', '•When stem, shoot and fruit borers are found, spray 2-3 times at an interval of 15 days with 0.5 ml of chloranthraniliprol 18.5 SC or 0.5 ml of deltamethrin 2.8 EC or 0.2 g of emamectin benzoate 5 SG per liter of water
•If roundworm and roundworm leaf spot are found, spray 0.5 g of streptomycin sulphate and 3.0 g of copper oxychloride 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1572, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1573, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Provide 25% of the recommended nitrogen, phosphorus and potash as top dressing based on LRI to the plants. • Provide conservation irrigation using water available from agricultural wells and other sources.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1574, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1575, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1576, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'NORMAL', 'YES', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬ್ಲೈಟ್ ಮತ್ತು ಹಣ್ಣು ಕೊಳೆರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು', 'Harvesting eggplants', 'If symptoms of blight and fruit rot are seen, spray with 2 grams of Mancozeb 75 WP or 0.5 grams of Carbendazim 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1583, 'CHILLIES', 20, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ, ಹೆಂಟೆಗಳನ್ನು ಒಡೆದು ನಾಟಿಗೆ ಸಿದ್ದಪಡಿಸಿ, ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಿ, 75 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದುಗಳನ್ನು ಮಾಡುವುದು. ಈ ಬೋದುಗಳಲ್ಲಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ರಸಗೊಬ್ಬರಗಳನ್ನು ಕೊಟ್ಟು ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸಿ ತೆಳುವಾಗಿ ನೀರು ಹಾಯಿಸಿ', 'ಬಿತ್ತುವುದಕ್ಕೆ ಮುಂಚೆ ಪ್ರತಿ ಕಿಲೋ ಬೀಜಕ್ಕೆ 200 ಗ್ರಾಂ. ಅಜೋಸ್ಪಿರಿಲ್ಲಂ ರಿಂದ ಬೀಜೋಪಚಾರ ಮಾಡುವುದು ಮತ್ತು ಸಸಿಗಳ ಬೇರುಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದಕ್ಕೆ ಮುಂಚೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 400 ಗ್ರಾಂ ಅಜೋಸ್ಪಿರಿಲ್ಲಂ ಅಣುಜೀವಿಯ ದ್ರಾವಣದಲ್ಲಿ ಅದ್ದುವುದು ಉತ್ತಮ', 'Preparation: Plough the land deeply, break the clods and prepare it for planting, mix the recommended manure well with the soil, and make furrows at a distance of 75 cm. In these furrows, apply 50% of the recommended nitrogen, phosphorus and potash fertilizers based on LRI, mix them with the soil and water them lightly.', 'It is better to treat the seeds with Azospirillum at 200 grams per kilo of seed before sowing and dip the roots of the seedlings in a solution of 400 grams of Azospirillum per liter of water before planting', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1584, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'NORMAL', 'YES', '1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿ, ಹೇನು ಹಾಗೂ ಜೇಡ ನುಸಿ ಕಂಡು ಬಂದಾಗ ಬಿತ್ತನೆಯಾದ 3 ವಾರಗಳ ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪಾಸ್ಫಾಮಿಡಾನ್ 85 SC ಅಥವಾ 1 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting seedlings on one side of the bed at a distance of 1.5 feet.', 'When thrips, aphids and spider mites are found, spray 0.25 g Thiomethoxam 25 WG or 0.5 ml Phosphamidon 85 SC or 1 g Acephate 75 SP per liter of water 3 weeks after sowing', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1585, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು 1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿ, ಹೇನು ಹಾಗೂ ಜೇಡ ನುಸಿ ಕಂಡು ಬಂದಾಗ ಬಿತ್ತನೆಯಾದ 3 ವಾರಗಳ ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪಾಸ್ಫಾಮಿಡಾನ್ 85 SC ಅಥವಾ 1 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting saplings on one side of the bed at a distance of 1.5 feet, keeping in mind the rainfall forecast.', 'When thrips, aphids and spider mites are found, spray 0.25 g Thiomethoxam 25 WG or 0.5 ml Phosphamidon 85 SC or 1 g Acephate 75 SP per liter of water 3 weeks after sowing', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1586, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ 1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, plant the saplings on one side of the bed at a distance of 1.5 feet.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1587, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ 1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, plant the saplings on one side of the bed at a distance of 1.5 feet.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1588, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, 1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting seedlings on one side of the bed at a distance of 1.5 feet to drain excess water from the land.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1577, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'NORMAL', 'NO', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬ್ಲೈಟ್ ಮತ್ತು ಹಣ್ಣು ಕೊಳೆರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು', 'Harvesting eggplants', 'If symptoms of blight and fruit rot are seen, spray with 2 grams of Mancozeb 75 WP or 0.5 grams of Carbendazim 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1578, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'BELOW NORMAL', 'YES', 'ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting eggplants', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1579, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಬದನೆಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Conservation irrigation using water available from agricultural wells and other sources
• Harvesting brinjals', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1580, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'ABOVE NORMAL', 'YES', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1581, 'BRINJAL', 12, N'20-28 Weeks', N'20-28', 'Harvesting stage', 5, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1582, 'BRINJAL', 12, N'>28 Weeks', N'>28 Weeks', 'Post Harvest', 6, 'NIL', 'NIL', '• ಕೊನೆಯ ಕೊಯ್ಲಿನ ತಕ್ಷಣವೇ ಎಲ್ಲಾ ಗಿಡಗಳನ್ನು ಬೇರುಸಮೇತ ತೆಗೆಯಿಸಿ ನಾಶಪಡಿಸಬೇಕು, ಇದರಿಂದ ಶೂಟ್‌ ಮತ್ತು ಹಣ್ಣು ತಿನ್ನುವ ಹುಳದ ಮುಂದುವರಿದ ಸೋಂಕು ನಿಯಂತ್ರಿಸಬಹುದು
• ಬೇಸಿಗೆ ಕಾಲದಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡುವುದು, ಇದರಿಂದ ಕೀಟಗಳ ಅವಶೇಷಗಳು (ಲಾರ್ವಾ ಮತ್ತು ಪುಪಾಗಳು) ಹೊರಬಂದು ನಾಶವಾಗುತ್ತವೆ
• ಕನಿಷ್ಠ ಒಂದು ಋತುವಿನವರೆಗೆ ಅದೇ ಹೊಲದಲ್ಲಿ ಮತ್ತೆ ಬದನೆಕಾಯಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸುವುದು ಉತ್ತಮ
• ಮಣ್ಣಿನ ರಚನೆ ಮತ್ತು ಆರೋಗ್ಯವನ್ನು ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು
• ಮಣ್ಣಿನ ಸಾರಜನಕ ಸಮತೋಲನ ಸುಧಾರಿಸಲು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು', NULL, '• Uproot and destroy all plants immediately after the last harvest to control further infestation of shoot and fruit borers
• Deep ploughing during summer season to remove and destroy insect remains (larvae and pupae)
• Avoid growing brinjal again in the same field for at least one season
• Incorporate organic manures into the soil to improve soil structure and health
• Rotate crops with legumes to improve soil nitrogen balance', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1557, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', '• ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', '•ಗುಲಗಂಜಿ ಹುಳು, ಜಿಗಿ ಹುಳು ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆಗಳ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ. ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಸಣ್ಣ ಎಲೆಗಳ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪಿಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ರೋಗ ಹರಡುವ ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Drain excess water from the land and plant the seedlings at a distance of 4x2 feet on one side of the bed. • After planting, apply 50% of the recommended nitrogen and full amount of phosphorus and potassium fertilizers based on LRI.', '•If there is a problem of mealybug, scale insect and mealybug, spray with 1.7 ml. Dimethoate 30 EC or 2 ml. Quinalphos 25 EC per liter of water
•If there is a problem of small leaf spot, it is better to uproot and destroy the diseased plants and spray with 1.7 ml. Dimethoate 30 EC per liter of water to control the disease-spreading insects', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1558, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಗುಲಗಂಜಿ ಹುಳು, ಜಿಗಿ ಹುಳು ಹಾಗೂ ಹಿಟ್ಟು ತಿಗಣೆಗಳ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ. ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅಥವಾ 2 ಮಿ.ಲೀ ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಸಣ್ಣ ಎಲೆಗಳ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗಪಿಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶಪಡಿಸುವುದು ಹಾಗೂ ರೋಗ ಹರಡುವ ಕೀಟಗಳ ಹತೋಟಿಗಾಗಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Providing support for plants to grow upright
• Weed management through intercropping', '•If there is a problem of mealybug, scale insect and mealybug, spray with 1.7 ml. Dimethoate 30 EC or 2 ml. Quinalphos 25 EC per liter of water
•If there is a problem of small leaf spot, it is better to uproot and destroy the diseased plants and spray with 1.7 ml. Dimethoate 30 EC per liter of water to control the disease-spreading insects', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
