INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1563, 'BRINJAL', 12, N'2-11 Weeks', N'2-11', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1564, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ನುಸಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2.5 ಮಿ.ಲೀ. ಡೈಕೋಫಾಲ್ 18.5 EC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೊಪರಗೈಟ್ 57 % EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2 ಗ್ರಾಂ ಕ್ಲೋರೋಥೆಲೋನಿಲ್ 70 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ಶೇ.80 ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಅಥವಾ 1 ಗ್ರಾಂ ಬೆನೊಮಿಲ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', '•If there is a disease of fungus, spray 2.5 ml. Dicofol 18.5 EC or 2 ml. Propargite 57 % EC per liter of water
•If there is a disease of leaf spot, spray 2 g. Mancozeb 75 WP or 2 g. Chlorothalonil 70 WP per liter of water
•If there are symptoms of powdery mildew, spray 3 g. 80% water-soluble sulfur or 1 g. Benomyl 50 WP or 1 g. Carbendazim 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1565, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'NORMAL', 'NO', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ನುಸಿಯ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2.5 ಮಿ.ಲೀ. ಡೈಕೋಫಾಲ್ 18.5 EC ಅಥವಾ 2 ಮಿ.ಲೀ. ಪ್ರೊಪರಗೈಟ್ 57 % EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2 ಗ್ರಾಂ ಕ್ಲೋರೋಥೆಲೋನಿಲ್ 70 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗದ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 3 ಗ್ರಾಂ ಶೇ.80 ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಅಥವಾ 1 ಗ್ರಾಂ ಬೆನೊಮಿಲ್ 50 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ 50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', '•If there is a disease of fungus, spray 2.5 ml. Dicofol 18.5 EC or 2 ml. Propargite 57 % EC per liter of water
•If there is a disease of leaf spot, spray 2 g. Mancozeb 75 WP or 2 g. Chlorothalonil 70 WP per liter of water
•If there are symptoms of powdery mildew, spray 3 g. 80% water-soluble sulfur or 1 g. Benomyl 50 WP or 1 g. Carbendazim 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1566, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1567, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Provide 25% of the recommended nitrogen, phosphorus and potash as top dressing based on LRI to the plants. • Provide conservation irrigation using water available from agricultural wells and other sources.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1568, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1569, 'BRINJAL', 12, N'12-15 Weeks', N'12-15', 'Flowering stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1570, 'BRINJAL', 12, N'16-19 Weeks', N'16-19', 'Fruit set and fruit development stage', 4, 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 25 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಕಾಂಡ, ಕುಡಿ ಮತ್ತು ಕಾಯಿ ಕೊರೆಯುವ ಹುಳುಗಳು ಕಂಡುಬಂದಾಗ ಕಾಯಿಬಿಡುವ ಸಮಯದಲ್ಲಿ 15 ದಿವಸಗಳ ಅಂತರದಲ್ಲಿ 2-3 ಸಾರಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಅಥವಾ 0.5 ಡೆಲ್ಟಾಮಿಥ್ರಿನ್ 2.8 EC ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್ ಬೆಂಜೋಯೇಟ್ 5 SG ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಮತ್ತು ದುಂಡಾಣು ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ  ಲೀಟರ್‍ ನೀರಿಗೆ 0.5 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಮೈಸಿನ್ ಸಲ್ಫೇಟ್ ಮತ್ತು 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing of plants with 25% of the recommended nitrogen, phosphorus and potassium based on LRI', '•When stem, shoot and fruit borers are found, spray 2-3 times at an interval of 15 days with 0.5 ml of chloranthraniliprol 18.5 SC or 0.5 ml of deltamethrin 2.8 EC or 0.2 g of emamectin benzoate 5 SG per liter of water
•If roundworm and roundworm leaf spot are found, spray 0.5 g of streptomycin sulphate and 3.0 g of copper oxychloride 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1550, 'TOMATO', 69, N'28-31', N'28-31', 'Post harvest', 6, 'NIL', 'NIL', '• ವೈರಸ್ ಸೋಂಕಿತ ಮತ್ತು ಸೊರಗು ರೋಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತಕ್ಷಣವೇ ತೆಗೆದುಹಾಕಿ ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ಬಿಳಿನೊಣ ಹಾಗೂ ಬ್ಯಾಕ್ಟೀರಿಯಾ ವಿಲ್ಟ್‌ನ ಜೀವನಚಕ್ರ ಮುರಿಯಬಹುದು
• ಹಳೆಯ ಬೆಳೆಯನ್ನು ದೀರ್ಘಕಾಲ ಕೊಯ್ಲಿಗಾಗಿ ಉಳಿಸಿಕೊಳ್ಳುವುದನ್ನು ತಪ್ಪಿಸಿ
• ಬೇಸಿಗೆ ಕಾಲದಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡುವುದು, ಇದರಿಂದ ಮಣ್ಣಿನಲ್ಲಿ ಇರುವ ರೋಗಾಣುಗಳು ಹಾಗೂ ಹಣ್ಣು ಕೊರೆಯುವ ಹುಳಗಳ ಅವಶೇಷಗಳು ಸೂರ್ಯನ ಬೆಳಕಿಗೆ ಬಂದು ನಾಶವಾಗುತ್ತವೆ
• ಭಾರಿ ರಸಗೊಬ್ಬರ ಬಳಕೆಯಿಂದ ಕುಂದಿರುವ ಮಣ್ಣಿನ ಸಾವಯವ ಅಂಶದ ಪುನಃಸ್ಥಾಪನೆಗಾಗಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು
• ಕನಿಷ್ಠ ಒಂದು ಹಂಗಾಮಿಗೆ ಅಲಸಂದೆ, ಬೀನ್ಸ್ ಅಥವಾ ಸಿರಿಧಾನ್ಯಗಳಂತಹ ಟೊಮ್ಯಾಟೊ ಜಾತಿಗೆ ಸೇರಿರದ ಬೆಳೆಗಳಿಂದ ಬೆಳೆ ಬದಲಾವಣೆ ಮಾಡಿ', NULL, NULL, NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1551, 'BRINJAL', 12, N'-2 Weeks', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಹೆಂಟೆಗಳನ್ನು ಒಡೆದು ನಾಟಿ ಮಾಡಲು ಸಿದ್ದಪಡಿಸಿ, ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಹಾಕಿ ಚೆನ್ನಾಗಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು. ನಂತರ 120 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದುಗಳನ್ನು ಮಾಡುವುದು. LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸುವುದು', NULL, 'Preparation: Prepare the land by deep ploughing, breaking the clods and preparing it for planting, adding the recommended manure and mixing it well into the soil. Then make furrows at a distance of 120 cm. Based on LRI, 50% of the recommended nitrogen and full amount of phosphorus and potash fertilizers are mixed well into the soil.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1552, 'BRINJAL', 12, N'1 Weeks', N'1', 'Transplanting', 1, 'NORMAL', 'YES', '• ಸಸಿಗಳನ್ನು 4x2 ಅಡಿ ಅಂತರದಲ್ಲಿ ಬೋದಿನ ಒಂದು ಪಕ್ಕದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು
• ನಾಟಿಯ ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ಣ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಕೊಡುವುದು', '•ಮಡಿಯಲ್ಲಿ ಸಸಿ ಸಾಯುವ ರೋಗ ಲಕ್ಷಣಗಳು ಕಂಡಲ್ಲಿ ಲೀ. ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 0.5 ಗ್ರಾಂ ಕರ‍್ಬೆಂಡಜಿಮ್ 50 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್  50 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು, ರೋಗ ಹತೋಟಿ ಪೂರ್ಣ ಆಗದಿದ್ದಲ್ಲಿ 15 ದಿವಸಕ್ಕೆ ಮತ್ತೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು
•ಸಸಿ ಕತ್ತರಿಸುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಕ್ಲೋರೊಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ  2 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಬೆರೆಸಿ ಗಿಡದ ಸುತ್ತಲೂ ತೋಯಿಸುವುದು', '• Planting the seedlings at a spacing of 4x2 feet on one side of the bed
• After planting, apply 50% of the recommended nitrogen and full dose of phosphorus and potash fertilizers based on LRI', '•If symptoms of seedling death are seen in the field, spray 2 g Mancozeb 75 WP or 0.5 g Carbendazim 50 WP or 2.5 g Copper Oxychloride 50 WP per liter of water. If the disease is not completely controlled, spray again after 15 days. •If seedling cutworm is seen, spray 2 ml Chlorpyrifos 20 EC or 2 ml Quinalphos 25 EC per liter of water and water around the plant', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1613, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, the seeds should be planted at a distance of 20 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1614, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the field and plant the seeds at a distance of 20 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1615, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the field and plant the seeds at a distance of 20 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1616, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣನ್ನು ಏರಿಸುವುದು', 'ಮೊದಲದ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಡೈಫೆನ್‌ಕೊನಾಜೋಲ್ 10 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯಾಪ್ಟಾನ್ 50 WP ಯನ್ನು ಬೇರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping and raising soil at the base of plants', 'If early stage of leaf spot is detected, spray 1 ml of Difenconazole 10 WP or 2 gm Mancozeb 75 WP or 2.5 gm Captan 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1617, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣನ್ನು ಏರಿಸುವುದು', 'ಮೊದಲದ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಡೈಫೆನ್‌ಕೊನಾಜೋಲ್ 10 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯಾಪ್ಟಾನ್ 50 WP ಯನ್ನು ಬೇರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping and raising soil at the base of plants', 'If early stage of leaf spot is detected, spray 1 ml of Difenconazole 10 WP or 2 gm Mancozeb 75 WP or 2.5 gm Captan 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1618, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣನ್ನು ಏರಿಸುವುದು', 'ಸಸಿ ಕತ್ತರಿಸುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2.5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ 2.0 ಮಿಲೀ. ಕ್ವಿನಾಲ್ ಫಾಸ್ 20 EC ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping and raising soil at the base of plants', 'If the sap cutting worm is found, spray by adding 2.5 ml. Chlorpyrifos 20 EC or 2.0 ml. Quinolphos 20 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1619, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣನ್ನು ಏರಿಸುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಬಿತ್ತದ 4-5 ವಾರಗಳ ನಂತರ ಹೇನು, ಜಿಗಿಹುಳು ಹಾಗೂ ಗುಲಗಂಜಿ ಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ  1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೊಯೇಟ್‍ 30 EC ಅಥವಾ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WGಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Weed management through intercropping and raising the soil at the base of the plants
• Conservation irrigation using water available from agricultural wells and other sources', 'If aphids, leafhoppers and mealybugs are found 4-5 weeks after sowing, spray with 1.7 ml of Dimethoate 30 EC or 0.25 g of Thiomethoxam 25 WG per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1620, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1628, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'NORMAL', 'YES', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಕುಡಿ ಕೊರೆಯುವ ಹುಳು ಭಾದೆಗೊಂಡ ಕಾಂಡದ ತುದಿಗಳನ್ನು ಚಿವುಟಿ ನಾಶಪಡಿಸಿ, ಬೆಳೆಗೆ 1 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ್ 75 ಡಬ್ಲೂಪಿ. ಅಥವಾ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 ಇ.ಸಿ.ಯನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'Pinch off and destroy the stem ends affected by the stem borer and spray the crop with 1 gm Thiodicarb 75 WP or 2 ml Malathion 50 EC per litre of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1629, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'NORMAL', 'NO', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಕುಡಿ ಕೊರೆಯುವ ಹುಳು ಭಾದೆಗೊಂಡ ಕಾಂಡದ ತುದಿಗಳನ್ನು ಚಿವುಟಿ ನಾಶಪಡಿಸಿ, ಬೆಳೆಗೆ 1 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ್ 75 ಡಬ್ಲೂಪಿ. ಅಥವಾ 2 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 ಇ.ಸಿ.ಯನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸಬೇಕು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'Pinch off and destroy the stem ends affected by the stem borer and spray the crop with 1 gm Thiodicarb 75 WP or 2 ml Malathion 50 EC per litre of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1630, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'BELOW NORMAL', 'YES', 'ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಗಳು ಮೊಳಕೆಯೊಡೆಯುವುದನ್ನು ತಡೆಯಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಶೇ. 0.3ರ ಎಂ.ಹೆಚ್. ಅನ್ನು ಸಿಂಪಡಿಸುವುದು', 'ಮೊದಲದ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1 ಮಿ.ಲೀ. ಡೈಫೆನ್‌ಕೊನಾಜೋಲ್ 10 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.5 ಗ್ರಾಂ ಕ್ಯಾಪ್ಟಾನ್ 50 WP ಯನ್ನು ಬೇರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Spraying 0.3% MH 4 weeks before harvest to prevent sprouting of potatoes during storage', 'If early stage of leaf spot is detected, spray 1 ml of Difenconazole 10 WP or 2 gm Mancozeb 75 WP or 2.5 gm Captan 50 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1631, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಸಂಗ್ರಹಣೆಯ ಕಾಲದಲ್ಲಿ ಆಲೂಗಡ್ಡೆಯ ಮೊಳಕೆಯೊಡೆಯದಂತಿರಲು ಕಟಾವಿಗೆ 4 ವಾರಗಳ ಮೊದಲು ಎಂ.ಹೆಚ್. (ಶೇ. 0.3) ಸಿಂಪಡಿಸುವುದು', NULL, '• Provide conservation irrigation using water available from agricultural wells and other sources
• Spray MH (0.3%) 4 weeks before harvest to prevent potato sprouting during storage', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1632, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1633, 'POTATO', 51, N'10-12 weeks', N'10-12', 'Tuber development stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1634, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'NORMAL', 'YES', 'ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಗೊಣ್ಣೆಹುಳುವಿನ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀ. ನೀರಿನಲ್ಲಿ 5 ಮಿ.ಲೀ ಕ್ಲೋರೊಪೈರಿಫೋಸ್ 20 ಇಸಿ ಬೆರಸಿ ತಯೆರಿಸಿದ 500 ಲೀಟರ್ ದ್ರಾವಣವನ್ನು ಬೇರು ತೊಯುವ ಹಾಗೆ ಸಿಂಪಡಿಸಬೇಕು', 'Harvesting tubers', 'If aphid infestation is found, 500 liters of a solution prepared by mixing 5 ml of Chlorpyrifos 20 EC per liter of water should be sprayed as a root-drench', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1621, 'POTATO', 51, N'2-6 weeks', N'2-6', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1622, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', 'ಎಲೆ ಸುರುಳಿ ರೋಗ ಹಾಗೂ ಮೊಸಾಯಿಕ್ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗ ಪೀಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶ ಪಡಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing the plants with 50% of the recommended nitrogen fertilizer based on LRI.', 'If leaf curl and mosaic virus disease are found, uproot and destroy the affected plants and spray with 0.25 g Thiomethoxam 25 WG mixed with 0.25 g per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1623, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'NORMAL', 'NO', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', 'ಎಲೆ ಸುರುಳಿ ರೋಗ ಹಾಗೂ ಮೊಸಾಯಿಕ್ ನಂಜು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ರೋಗ ಪೀಡಿತ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ನಾಶ ಪಡಿಸುವುದು ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Top dressing the plants with 50% of the recommended nitrogen fertilizer based on LRI.', 'If leaf curl and mosaic virus disease are found, uproot and destroy the affected plants and spray with 0.25 g Thiomethoxam 25 WG mixed with 0.25 g per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1624, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'BELOW NORMAL', 'YES', 'ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'Top dressing the plants with 50% of the recommended nitrogen fertilizer based on LRI.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1625, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಗೊಬ್ಬರವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Apply 50% of the recommended nitrogen fertilizer based on LRI to the plants as top dressing
• Provide conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1626, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕೊನೆಯ ಹಂತದ ಅಂಗಮಾರಿ ರೋಗ ತಡೆಗಟ್ಟಲು ಬಿತ್ತಿದ 5 ವಾರಗಳ ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್‍ 75 WP ಅಥವಾ 2 ಗ್ರಾಂ ಮ್ಯಾನೆಬ್ ಅಥವಾ 3 ಗ್ರಾಂ ಫಿನಾಮಿಡಾನ್‍+ಮ್ಯಾಂಕೋಜೆಬ್‍ 60 WP ಅಥವಾ 1 ಮಿ.ಲೀ. ಅಜಕ್ಸಿಸ್ಟ್ರೋಬಿನ್‍ 23 SC ಅನ್ನು ಸೇರಿಸಿ ಬೆಳೆಗೆ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'To prevent late blight, spray the crop with 2 g Mancozeb 75 WP or 2 g Maneb or 3 g Fenamidon + Mancozeb 60 WP or 1 ml Azaxystrobin 23 SC per liter of water 5 weeks after sowing', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1627, 'POTATO', 51, N'7-9 weeks', N'7-9', 'Tuber initiation stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1589, 'CHILLIES', 20, N'1 weeks', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, 1.5 ಅಡಿ ಅಂತರದಲ್ಲಿ  ಬೋದಿನ ಒಂದು ಬದಿಯಲ್ಲಿ ಸಸಿಯನ್ನು ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting seedlings on one side of the bed at a distance of 1.5 feet to drain excess water from the land.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1590, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', 'ಮುರುಟು ರೋಗದ ಬಾಧೆ ತಡೆಗಟ್ಟಲು ಶೇ. 0.5 ರ ಬೆಳ್ಳೊಳ್ಳಿ + ಹಸಿಮೆಣಿಸಿನಕಾಯಿ + ಸೀಮೆ ಎಣ್ಣೆ ಕಷಾಯವನ್ನು ಬೇವು ಜನ್ಯ ಕೀಟನಾಶಕದೊಂದಿಗೆ (2.5 ಮಿ. ಲೀ. ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ) ಬೆರಸಿ ಅವಶ್ಯವಿದ್ದಾಗ ಸಿಂಪಡಿಸುವುದು', '• Providing support for plants to grow upright
• Weed management through intercropping', 'To prevent the disease, spray 0.5% garlic + green chili + kerosene oil infusion mixed with neem based insecticide (2.5 ml per liter of water) whenever necessary', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1591, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'NORMAL', 'NO', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', 'ಮುರುಟು ರೋಗದ ಬಾಧೆ ತಡೆಗಟ್ಟಲು ಶೇ. 0.5 ರ ಬೆಳ್ಳೊಳ್ಳಿ + ಹಸಿಮೆಣಿಸಿನಕಾಯಿ + ಸೀಮೆ ಎಣ್ಣೆ ಕಷಾಯವನ್ನು ಬೇವು ಜನ್ಯ ಕೀಟನಾಶಕದೊಂದಿಗೆ (2.5 ಮಿ. ಲೀ. ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ) ಬೆರಸಿ ಅವಶ್ಯವಿದ್ದಾಗ ಸಿಂಪಡಿಸುವುದು', '• Providing support for plants to grow upright
• Weed management through intercropping', 'To prevent the disease, spray 0.5% garlic + green chili + kerosene oil infusion mixed with neem based insecticide (2.5 ml per liter of water) whenever necessary', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1592, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿ, ಹೇನು ಹಾಗೂ ಜೇಡ ನುಸಿ ಕಂಡು ಬಂದಲ್ಲಿ ಬಿತ್ತನೆಯಾದ 3 ವಾರಗಳ ನಂತರ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.25 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪಾಸ್ಫಾಮಿಡಾನ್ 85 SC ಅಥವಾ 1 ಗ್ರಾಂ ಅಸಿಫೇಟ್ 75 SC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Providing support for plants to grow upright
• Weed management through intercropping', 'If thrips, aphids and spider mites are found, spray 0.25 g Thiomethoxam 25 WG or 0.5 ml Phosphamidon 85 SC or 1 g Acephate 75 SC per liter of water 3 weeks after sowing', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1593, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'BELOW NORMAL', 'NO', '• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಗಿಡಗಳು ನೇರವಾಗಿ ಬೆಳೆಯಲು ಆಸರೆ ಒದಗಿಸುವುದು
• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', NULL, '• Provide conservation irrigation using water available from agricultural wells and other sources
• Provide support for plants to grow upright
• Manage weeds through intercropping', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1594, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1595, 'CHILLIES', 20, N'2-12 weeks', N'2-12', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಕಾಯಿ ಕೊರಕದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.25 ಫ್ಲುಬೆಂಡಿಯಾಮೈಡ್ 39.35 SC ಅಥವಾ 2 ಮಿ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 50 EC ಅಥವಾ ಶೇ.5 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'To control the nut borer, spray 0.25 ml of Flubendiamide 39.35 SC or 2 ml of Chlorpyrifos 50 EC or 5% neem seed extract per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1596, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'NORMAL', 'YES', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ  ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಎನ್. ಎ. ಎ. (ಫ್ಲಾನೋಫಿಕ್ಸ್) ಅನ್ನು 50 ಮಿ. ಗ್ರಾಂ 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದರಿಂದ ಹೂವು ಉದುರುವುದು ನಿಲ್ಲುತ್ತದೆ', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ, ಬೂದಿ ರೋಗ ಮತ್ತು ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬಂಡೈಜಿಮ್ 50 WP  ಅಥವಾ 1 ಗ್ರಾಂ ಬೆನೊಮಿಲ್ ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. 15 ದಿವಸಗಳ ನಂತರ ಇದನ್ನು ಪುನ: ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Give 50% of the recommended nitrogen, phosphorus and potash as top dressing to the plants based on LRI
• Spray N. A. A. (Flanofix) at 50 mg. gm. in 1 l. of water to stop flower drop', 'If leaf spot, powdery mildew and powdery mildew are found, spray 1 gram of Carbandizim 50 WP or 1 gram of Benomyl per liter of water. It is better to spray again after 15 days', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1597, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ  ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಎನ್. ಎ. ಎ. (ಫ್ಲಾನೋಫಿಕ್ಸ್) ಅನ್ನು 50 ಮಿ. ಗ್ರಾಂ 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದರಿಂದ ಹೂವು ಉದುರುವುದು ನಿಲ್ಲುತ್ತದೆ', 'ಎಲೆ ಚುಕ್ಕೆ ರೋಗ, ಬೂದಿ ರೋಗ ಮತ್ತು ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬಂಡೈಜಿಮ್ 50 WP  ಅಥವಾ 1 ಗ್ರಾಂ ಬೆನೊಮಿಲ್ ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. 15 ದಿವಸಗಳ ನಂತರ ಇದನ್ನು ಪುನ: ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Give 50% of the recommended nitrogen, phosphorus and potash as top dressing to the plants based on LRI
• Spray N. A. A. (Flanofix) at 50 mg. gm. in 1 l. of water to stop flower drop', 'If leaf spot, powdery mildew and powdery mildew are found, spray 1 gram of Carbandizim 50 WP or 1 gram of Benomyl per liter of water. It is better to spray again after 15 days', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1598, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ  ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಎನ್. ಎ. ಎ. (ಫ್ಲಾನೋಫಿಕ್ಸ್) ಅನ್ನು 50 ಮಿ. ಗ್ರಾಂ 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದರಿಂದ ಹೂವು ಉದುರುವುದು ನಿಲ್ಲುತ್ತದೆ', 'ಮುರುಟು ರೋಗದ ಬಾಧೆ ಕಂಡು ಬಂದಾಗ 3.2 ಮಿ.ಲೀ ಪ್ರೊಪರ್‌ಗೈಟ್ 7% EC ಅಥವಾ 2 ಮಿ.ಲೀ. ಕ್ಲೋರ್‌ಪೈರಿಫಾಸ್ 50 EC ಹಾಗೂ 3 ಗ್ರಾಂ ಕರಗುವ ಗಂಧಕ ನೀರಿನಲ್ಲಿ ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Give 50% of the recommended nitrogen, phosphorus and potash as top dressing to the plants based on LRI
• Spray N. A. A. (Flanofix) at 50 mg. gm. in 1 l. of water to stop flower drop', 'When powdery mildew is observed, spray 3.2 ml of Propargite 7% EC or 2 ml of Chlorpyrifos 50 EC and 3 g of soluble sulfur mixed in water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1599, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳಿಗೆ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ  ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ರಂಜಕ ಹಾಗೂ ಪೊಟ್ಯಾಷ್ ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಎನ್. ಎ. ಎ. (ಫ್ಲಾನೋಫಿಕ್ಸ್) ಅನ್ನು 50 ಮಿ. ಗ್ರಾಂ 1 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪರಿಸುವುದರಿಂದ ಹೂವು ಉದುರುವುದು ನಿಲ್ಲುತ್ತದೆ', 'ಹಣ್ಣು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದಾಗ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1ಗ್ರಾಂ ಕಾರ್ಬಂಡೈಜಿಮ್ 50 WP ಬೆರೆಸಿ, 15 ದನಗಳ ಅಂತರದಲ್ಲಿ ನಾಲ್ಕು ಸಾರಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Apply 50% of the recommended LRI based nitrogen, phosphorus and potash as top dressing to the plants
• Provide conservation irrigation using water available from agricultural wells and other sources
• Spray N. A. A. (Flanofix) at 50 mg. gm. in 1 l. of water to stop flower drop', 'When fruit rot disease is detected, it is best to spray 1 gram of Carbandizim 50 WP per liter of water and spray four times at an interval of 15 cm', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1600, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'ABOVE NORMAL', 'YES', '• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ
• ಹಸಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಬೂದಿ ರೋಗ ಬಾಧೆ ಕಂಡುಬಂದಲ್ಲಿ  ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 1 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡೈಜಿಮ್ 50 WP ಅಥವಾ 3 ಗ್ರಾಂ ನೀರಿನಲ್ಲಿ ಕರಗುವ ಗಂಧಕ ಅಥವಾ 1 ಮಿ.ಲೀ ಪೆನ್‌ಕೊನಾಜೋಲ್ 10 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ತಿವ್ರತೆ ಕಂಡುಬಂದಲ್ಲಿ ಸಿಂಪರಣೆಯನ್ನು 15 ದಿನಗಳಿಗೊಮ್ಮೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• If there has been heavy rainfall in the past few days, allow the water to drain away from the field. • Harvesting green beans', 'If powdery mildew is found, spray with 1 gram of Carbendazim 50 WP or 3 grams of water-soluble sulfur or 1 ml of Penconazole 10 EC per liter of water. If the disease is severe, it is better to spray once in 15 days', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1601, 'CHILLIES', 20, N'13-19 weeks', N'13-19', 'Flowering and fruit set stage', 3, 'ABOVE NORMAL', 'NO', '• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ
• ಹಸಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಕಾಯಿ ಕೊರಕದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.25 ಫ್ಲುಬೆಂಡಿಯಾಮೈಡ್ 39.35 SC ಅಥವಾ 2 ಮಿ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 50 EC ಅಥವಾ ಶೇ.5 ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು ಸಿಂಪಡಿಸುವುದು', '• If there has been heavy rainfall in the past few days, allow the water to drain away from the field. • Harvesting green beans', 'To control the nut borer, spray 0.25 ml of Flubendiamide 39.35 SC or 2 ml of Chlorpyrifos 50 EC or 5% neem seed extract per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1602, 'CHILLIES', 20, N'20-28 weeks', N'20-28', 'Harvesting stage', 4, 'NORMAL', 'YES', 'ಒಣ ಮೆಣಸಿನಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting dry chilies', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
