• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1607, 'CHILLIES', 20, N'20-28 weeks', N'20-28', 'Harvesting stage', 4, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ. ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1608, 'CHILLIES', 20, N'>28 weeks', N'>28 weeks', 'Post harvest', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲಿನ ನಂತರ ಒಣಗಿದ ಮೆಣಸಿನ ಗಿಡಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ಥ್ರಿಪ್ಸ್‌ ಹಾಗೂ ನುಸಿಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸಬಹುದು
• ಹೊಲದಲ್ಲಿ ಬೆಳೆ ಕೂಳೆಗಳನ್ನು ಬಿಡಬಾರದು
• ಬೇಸಿಗೆಯಲ್ಲಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡುವುದು
• ಮಣ್ಣಿನ ರಚನೆ ಮತ್ತು ಆರೋಗ್ಯವನ್ನು ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು
• ಕೀಟಗಳ ಒತ್ತಡ ಕಡಿಮೆ ಮಾಡಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು, ಅಲಸಂಡೆ ಅಥವಾ ಹೆಸರು ಬೆಳೆಗಳಂತಹ ದ್ವಿದಳಧಾನ್ಯಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವದು', NULL, '• Completely remove and destroy dried chilli plants after harvest, which can kill thrips and weevils
• Do not leave crop stubble in the field
• Deep ploughing in summer
• Incorporate organic manures into the soil to improve soil structure and health
• Crop rotation with legumes such as sorghum or cowpea to reduce pest pressure and improve soil health', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1609, 'POTATO', 51, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಸಾರಿ ಆಳವಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಹೆಂಟೆಗಳನ್ನು ಚೆನ್ನಾಗಿ ಒಡೆದು ಪುಡಿ ಮಾಡುವುದು. ಗೆದ್ದಲಿನ ಸಮಸ್ಯೆ ಇದ್ದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ 3.3 ಮೀ. ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 ಇ.ಸಿ. ಕರಗಿಸಿ ಪ್ರತಿ ಹುತ್ತಕ್ಕೂ 18 ಲೀಟರ್ ದ್ರಾವಣದಂತೆ ಸುರಿಯುವುದು. ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, 60 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಸಾಲುಗಳನ್ನು ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಹಾಗೂ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್‌ಯುಕ್ತ ರಸಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು', 'ಕತ್ತರಿಸಿದ ಬೀಜದ ಗಡ್ಡೆಯನ್ನು 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್‍ 75 WP ಅನ್ನು ಒಂದು ಲೀಟರ್‍ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 5 ನಿಮಿಷ ಅದ್ದಿ ಉಪಚರಿಸುವುದು', 'Preparation: Plough the land deeply 2-3 times and break the clods well and grind them. If there is a problem of termites, dissolve 3.3 ml. L. Chlorpyrifos 20 EC in every liter of water and pour it as a solution of 18 liters per hole. Then add the recommended manure to the soil, make rows at a distance of 60 cm. and mix 50% nitrogen and full amount of phosphorus and potash fertilizers recommended based on LRI into the soil.', 'Treat the cut seed tuber by dipping it in a solution prepared by dissolving 2 grams of Mancozeb 75 WP in one liter of water for 5 minutes', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1610, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'NORMAL', 'YES', 'ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seed tubers at a distance of 20 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1611, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seed tubers at a distance of 20 cm, keeping in mind the rainfall forecast', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1612, 'POTATO', 51, N'1 weeks', N'1', 'Planting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬೀಜ ಗೆಡ್ಡೆಗಳನ್ನು 20 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, the seeds should be planted at a distance of 20 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1642, 'CABBAGE', 13, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ಧತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಹದಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಿ ಅಲ್ಪಾವಧಿ ತಳಿಗಳಿಗೆ 45 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ತಯಾರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್ ಗೊಬ್ಬರ ಹಾಕಿ ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸುವುದು
ಅಲ್ಪಾವಧಿ ತಳಿಗಳು: ಪ್ರೈಡ್ಡ್ ಆಫ ಇಂಡಿಯಾ,  ಗೋಲ್ಡನ್ ಏಕರ್, ಅರ್ಲಿ ಡ್ರಮ್ ಹೆಡ್', NULL, 'Preparation: After ploughing and harrowing the land 2-3 times, mix the recommended manure with the soil well and make furrows at a distance of 45 cm for short-duration varieties and apply 50% nitrogen and full amount of phosphorus and potash fertilizer as recommended based on LRI and mix it well into the soil. Short-duration varieties: Proud of India, Golden Acre, Early Drum Head', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
