INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1647, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1648, 'CABBAGE', 13, N'1 week', N'1', 'Transplanting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 30 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1649, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'NORMAL', 'YES', 'ಪೈರು ಸ್ಥಾಪಿತವಾಗದೆ ಇರುವ ಜಾಗದಲ್ಲಿ ಬೇರೆ ಸಸಿಯನ್ನು ನೆಡುವುದು', '•ಎಲೆ ಮಚ್ಚೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 3.0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ MZ 72 WPಯನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ವಜ್ರ ಗುರುತಿನ ಬೆನ್ನಿನ ಪತಂಗದ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಮಿಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಥೈಯಾಕ್ಲೋಪ್ರಿಡ್ 21.7 SC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಕ್ಲೋರಾಂಟ್ರೀನಿಲಿಪ್ರೋಲ್ 18.5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Planting another plant in a place where the tree is not established', '•If leaf spot disease is found, spray 3.0 g of copper oxychloride 50 WP or 2.0 g of metalaxyl MZ 72 WP per liter of water
•For the control of diamondback moth, spray 0.3 ml of spinosad 45 SC or 2.0 ml of thiacloprid 21.7 SC or 0.5 ml of chloranthraniliprol 18.5 SC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1671, 'CABBAGE', 13, N'9 week', N'9', 'Harvesting stage', 5, 'ABOVE NORMAL', 'YES', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1672, 'CABBAGE', 13, N'9 week', N'9', 'Harvesting stage', 5, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1673, 'CABBAGE', 13, N'>9 Weeks', N'>9', 'Post harvest', 6, 'NIL', 'NIL', '• ಕ್ಲಬ್‌ರೂಟ್‌ ರೋಗ ಅಥವಾ ವಜ್ರ ಬೆನ್ನಿನ ಪತಂಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ರೋಗ ಹಾಗೂ ಕೀಟಗಳ ಮುಂದುವರಿದ ಸೋಂಕನ್ನು ತಪ್ಪಿಸಬಹುದು
• ನಿರಂತರವಾಗಿ ಎಲೆಕೋಸು ಜಾತಿಯ ಬೆಳೆಗಳನ್ನು ಅದೇ ಹೊಲದಲ್ಲಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮಜೀವಿ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಸೇರಿಸುವುದು', NULL, '• Remove and destroy all crop residues, including those affected by clubroot disease or diamondback moth, to prevent further spread of disease and pests
• Rotate crops by avoiding continuous cultivation of cabbage varieties in the same field
• Deep summer tillage to destroy soil-borne pest residues
• Add organic manure to improve soil health by increasing soil microbial activity', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1674, 'CABBAGE', 13, N'0 week', N'0', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ಧತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಹದಮಾಡಿದ ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸಿ ದೀರ್ಘಾವಧಿ ತಳಿಗಳಿಗೆ 60 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ತಯಾರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ, ಪೊಟ್ಯಾಷ್ ಗೊಬ್ಬರ ಹಾಕಿ ಮಣ್ಣಿನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆರೆಸುವುದು
ದೀರ್ಘಾವಧಿ ತಳಿಗಳು: ಲೇಟ್ ಡ್ರಮ್ ಹೆಡ್,  ಡ್ಯಾನಿಷ್ ಬಾಲ್ ಹೆಡ್', NULL, 'Preparation: After ploughing and harrowing the land 2-3 times, mix the recommended amount of manure well into the soil and for long-term varieties, make holes at a distance of 60 cm and prepare furrows, apply 50% nitrogen and full amount of phosphorus and potash fertilizer as recommended based on LRI and mix well into the soil. Long-term varieties: Late Drum Head, Danish Ball Head', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
