INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1685, 'CABBAGE', 13, N'2 weeks', N'2', 'Establishment stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಸ್ಯ ಹೇನು, ಕೊಂಡಲ್ಲಿ ಹುಳು, ಗೆಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು, ಸಾಸಿವೆ ಗರಗಸದ ಹುಳು ಹಾಗೂ ಎಲೆಕೋಸು ತಿಗಣೆ  ಕಾಣಿಸಿಕೊಂಡಾಗ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ ಅಸಿಟಾಮಾಫ್ರಿಡ್ 20 SP ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಟಾಲ್‌ಫೇನ್‌ಪೈರಾಡ್ 15 EC ಅಥವಾ 1.0 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರಿನಿಲಿಪ್ರೋಲ್ 10.26 OD ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'When aphids, leafhoppers, tuber borers, mustard sawflies and cabbage loopers appear, spray 0.2 g Acetamafrid 20 SP or 2.0 ml Talfenpyrad 15 EC or 1.0 ml Cyanthriniliprol 10.26 OD per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
