INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1637, 'POTATO', 51, N'13-15 weeks', N'13-15', 'Harvesting stage', 5, 'BELOW NORMAL', 'NO', 'ಜಮೀನಿಗೆ ನೀರು ಒದಗಿಸಿ ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಿ ನಂತರ ಗಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Watering the field, loosening the soil, and then harvesting the tubers', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
