INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1733, 'ONION', 46, N'14-17 weeks', N'14-17', 'Harvesting stage', 4, 'BELOW NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting tubers', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1734, 'ONION', 46, N'14-17 weeks', N'14-17', 'Harvesting stage', 4, 'BELOW NORMAL', 'NO', 'ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಲು ನೀರಾವರಿ ಒದಗಿಸಿ ನಂತರ ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Irrigation to loosen the soil and then harvesting', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1690, 'CABBAGE', 13, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ನಂತರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ಸಸ್ಯ ಹೇನು. ಸುರುಳಿ ಪೂಚಿ, ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು. ಸಾಸಿವೆ ಗರಗಸ ನೊಣ ಹತೋಟಿಗೆ ಬಿತ್ತನೆಯಾದ 2 ಮತ್ತು 4 ವಾರಗಳ ನಂತರ ಸಸಿ ಮಡಿಯಲ್ಲಿ ಸಸಿಗಳಿಗೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ  0.5 ಮಿ.ಲೀ. ಫಾಸ್ಫಾಮಿಡಾನ್ 40 EC ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಆಕ್ಸಿಡೆಮಿಟಾನ್ ಮಿಥೈಲ್ 25 EC ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI
• Then mulch the soil around the base of the plants
• Provide conservation irrigation using water available from agricultural wells and other sources', 'Plant aphids. Spiral leafhoppers, tuber borers. Mustard sawfly control: Spray the seedlings in the seedling bed at 2 and 4 weeks after sowing with 0.5 ml. Phosphamidon 40 EC or 1.7 ml. Oxydemitan methyl 25 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1691, 'CABBAGE', 13, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ವಜ್ರದ ಬೆನ್ನಿನ ಚಿಟ್ಟೆ (ಡೈಮಂಡ್ ಬ್ಯಾಕ್ ಮಾಥ್) ಹತೋಟಿಗೆ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 5 ಫೆರೋಮೋನ್ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು  ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಗ್ರಾಂ ಇಂಡಾಕ್ಸಕಾರ್ಬ 14.5 SC ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್‍ ಬೆಂಜೋಯೆಟ್‍ ಅಥವಾ 1.0 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ 75 WP ಅಥವಾ 2 ಮಿ.ಲೀ.  ಅಜರ್ಡೆಕ್ಟಿನ್ 300 ppm ಅಥವಾ 1 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರಿನಿಲಿಪ್ರೋಲ್‍ 10.26 OD ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಣೆ  ಮಾಡುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For the control of diamondback moth, use 5 pheromone traps per hectare and spray with 0.3 g indoxacarb 14.5 SC or 0.2 g emamectin benzoate or 1.0 g thiodicarb 75 WP or 2 ml azardectin 300 ppm or 1 ml cyanthrinyl 10.26 OD per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1692, 'CABBAGE', 13, N'3-6 weeks', N'3-6', 'Growth stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1693, 'CABBAGE', 13, N'7-8 weeks', N'7-8', 'Head initiation stage', 4, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಎಲೆ ಸುಡುವ ಹಾಗೂ ಬುಡ ಕೊಳೆಯುವ ರೋಗಕ್ಕೆ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಕ್ಲೋರೋಥಲೋನಿಲ್ 70 WP ಅಥವಾ 3. 0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬಿಳಿ ತುಕ್ಕು ರೋಗ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಜೈನೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ 18 + ಮ್ಯಾಂಕೋಜೆಬ್ 64 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping', '•For leaf scorch and stem rot, spray 2.0 g Mancozeb 75 WP or 2.0 g Chlorothalonil 70 WP or 3. 0 g Copper Oxychloride 50 WP. •If white rust is found, spray 2.0 g Mancozeb 75 WP or 2.0 g Zaineb 75 WP or 2.0 g Metalaxyl 18 + Mancozeb 64 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1694, 'CABBAGE', 13, N'7-8 weeks', N'7-8', 'Head initiation stage', 4, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಎಲೆ ಸುಡುವ ಹಾಗೂ ಬುಡ ಕೊಳೆಯುವ ರೋಗಕ್ಕೆ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಕ್ಲೋರೋಥಲೋನಿಲ್ 70 WP ಅಥವಾ 3. 0 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬಿಳಿ ತುಕ್ಕು ರೋಗ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 2.0 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಜೈನೆಬ್ 75 WP ಅಥವಾ 2.0 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ 18 + ಮ್ಯಾಂಕೋಜೆಬ್ 64 WP ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping', '•For leaf scorch and stem rot, spray 2.0 g Mancozeb 75 WP or 2.0 g Chlorothalonil 70 WP or 3. 0 g Copper Oxychloride 50 WP. •If white rust is found, spray 2.0 g Mancozeb 75 WP or 2.0 g Zaineb 75 WP or 2.0 g Metalaxyl 18 + Mancozeb 64 WP per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1695, 'CABBAGE', 13, N'7-8 weeks', N'7-8', 'Head initiation stage', 4, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', NULL, 'Weed management through intercropping', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1696, 'CABBAGE', 13, N'7-8 weeks', N'7-8', 'Head initiation stage', 4, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು
