INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1702, 'CABBAGE', 13, N'9-10 week', N'9-10', 'Head development stage', 5, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', 'ವಜ್ರದ ಬೆನ್ನಿನ ಚಿಟ್ಟೆ (ಡೈಮಂಡ್ ಬ್ಯಾಕ್ ಮಾಥ್) ಹತೋಟಿಗೆ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 5 ಫೆರೋಮೋನ್ ಬಲೆಗಳನ್ನು ಬಳಸುವುದು  ಹಾಗೂ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.3 ಗ್ರಾಂ ಇಂಡಾಕ್ಸಕಾರ್ಬ 14.5 SC ಅಥವಾ 0.2 ಗ್ರಾಂ ಇಮಾಮೆಕ್ಟಿನ್‍ ಬೆಂಜೋಯೆಟ್‍ ಅಥವಾ 1.0 ಗ್ರಾಂ ಥೈಯೋಡಿಕಾರ್ಬ 75 WP ಅಥವಾ 2 ಮಿ.ಲೀ.  ಅಜರ್ಡೆಕ್ಟಿನ್ 300 ppm ಅಥವಾ 1 ಮಿ.ಲೀ. ಸೈಯಾಂಟ್ರಿನಿಲಿಪ್ರೋಲ್‍ 10.26 OD ಅನ್ನು ಸೇರಿಸಿ ಸಿಂಪಡಣೆ  ಮಾಡುವುದು', '• Weed management through intercropping
• Conservation irrigation using water available from agricultural wells and other sources', 'For the control of diamondback moth, use 5 pheromone traps per hectare and spray with 0.3 g indoxacarb 14.5 SC or 0.2 g emamectin benzoate or 1.0 g thiodicarb 75 WP or 2 ml azardectin 300 ppm or 1 ml cyanthrinyl 10.26 OD per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
