• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1710, 'CABBAGE', 13, N'11-12 week', N'11-12', 'Harvesting stage', 6, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting in dry weather
• If there has been heavy rainfall in the past, allow the water to drain away from the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1711, 'CABBAGE', 13, N'>12 Weeks', N'>12', 'Post harvest', 6, 'NIL', 'NIL', '• ಕ್ಲಬ್‌ರೂಟ್‌ ರೋಗ ಅಥವಾ ವಜ್ರ ಬೆನ್ನಿನ ಪತಂಗ ಬಾಧಿತ ಗಿಡಗಳನ್ನು ಒಳಗೊಂಡಂತೆ ಎಲ್ಲಾ ಬೆಳೆ ಅವಶೇಷಗಳನ್ನು ತೆಗೆದು ನಾಶಪಡಿಸುವುದು, ಇದರಿಂದ ರೋಗ ಹಾಗೂ ಕೀಟಗಳ ಮುಂದುವರಿದ ಸೋಂಕನ್ನು ತಪ್ಪಿಸಬಹುದು
• ನಿರಂತರವಾಗಿ ಎಲೆಕೋಸು ಜಾತಿಯ ಬೆಳೆಗಳನ್ನು ಅದೇ ಹೊಲದಲ್ಲಿ ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಮಣ್ಣಿನೊಳಗಿನ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನ ಸೂಕ್ಷ್ಮಜೀವಿ ಚಟುವಟಿಕೆ ಹೆಚ್ಚಿಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಸೇರಿಸುವುದು', NULL, '• Remove and destroy all crop residues, including those affected by clubroot disease or diamondback moth, to prevent further spread of disease and pests
• Rotate crops by avoiding continuous cultivation of cabbage varieties in the same field
• Deep summer tillage to destroy soil-borne pest residues
• Add organic manure to improve soil health by increasing soil microbial activity', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1712, 'ONION', 46, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿತನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ, ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ, ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕನ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', 'ಪ್ರತಿ ಕಿ.ಗ್ರಾಂ ಬೀಜಕ್ಕೆ 15 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 60 FS ಜೊತೆಗೆ 5 ಗ್ರಾಂ ಸುಡೋಮೊನಾಸ್‍ ರಿಂದ ಬೀಜೋಪಚರಿಸಿ ಬಿತ್ತುವುದರಿಂದ ಈರುಳ್ಳಿ ಬೆಳೆಯ ಕೀಟ ಮತ್ತು ರೋಗವನ್ನು ನಿಯಂತ್ರಿಸಬಹುದು', 'Preparation: Plow the land 2-3 times, add the recommended amount of manure to the soil, add 50% of the recommended amount of nitrogen, full amount of phosphorus and potash to the soil based on LRI.', 'Pests and diseases of onion crop can be controlled by treating the seeds with 15 ml of Imidacloprid 60 FS and 5 g of Pseudomonas per kg of seeds', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1713, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'NORMAL', 'YES', 'ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿಯ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ. ಆಸಿಟಮಾಪ್ರತಿಡ್‍20 SP ಅಥವಾ 0.3 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 1 ಮಿ.ಲೀ. ಪಿಫ್ರೋನಿಲ್ 5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting seedlings at a distance of 10 cm.', 'For the control of thrips, spray 0.2 gm. Acetamaprid 20 SP or 0.3 gm. Thiomethoxam 25 WG or 1 ml. Pifronil 5 SC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1714, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', 'ಥ್ರಿಪ್ಸ್ ನುಸಿಯ ಹತೋಟಿಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.2 ಗ್ರಾಂ. ಆಸಿಟಮಾಪ್ರತಿಡ್‍20 SP ಅಥವಾ 0.3 ಗ್ರಾಂ ಥೈಯೋಮಿಥಾಕ್ಸಾಮ್ 25 WG ಅಥವಾ 1 ಮಿ.ಲೀ. ಪಿಫ್ರೋನಿಲ್ 5 SC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Planting seedlings at a distance of 10 cm, keeping in mind the rainfall forecast.', 'For the control of thrips, spray 0.2 gm. Acetamaprid 20 SP or 0.3 gm. Thiomethoxam 25 WG or 1 ml. Pifronil 5 SC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1715, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, seedlings should be planted at a distance of 10 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1716, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, seedlings should be planted at a distance of 10 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1717, 'ONION', 46, N'1-4 weeks', N'1', 'Sowing and germination stage', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಸಸಿಗಳನ್ನು 10 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Allow excess water to drain from the land and plant the seedlings at a distance of 10 cm.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1751, 'PUMPKIN', NULL, N'1-2', N'1-2', 'Crop Establishment Stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1752, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'NORMAL', 'YES', '• ಬಿತ್ತಿದ 25 ದಿನಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕುಂಬಳ ಸಸಿಗಳು 2 ರಿಂದ 4 ಎಲೆ ಹೊಂದಿದಾಗ 250 ಪಿ.ಪಿ.ಎಮ್. ಇಥ್ರೇಲ್ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು, ಇದರಿಂದ ಬಳ್ಳಿಯಲ್ಲಿ ಹೆಣ್ಣು ಹೂಗಳ ಸಂಖ್ಯೆ ಹೆಚ್ಚಾಗಿ ಇಳುವರಿ ಹೆಚ್ಚುತ್ತದೆ
• 1 ಗ್ರಾಂ ತರಕಾರಿ ಸ್ಪೆಷಲ್ ಪುಡಿಯನ್ನು 15 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಒಂದು ನಿಂಬೆ ಹಣ್ಣಿನ ರಸವನ್ನು ಚೆನ್ನಾಗಿ ಮಿಶ್ರಣ ಮಾಡಿ ಸಿಂಪಡಿಸುವುದು', '•ಹಣ್ಣು ನೊಣದ ಭಾದೆಗೆ ಹೂ ಬಿಡಲು ಪ್ರಾರಂಭವಾದಾಗ ಬೆಳೆಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 EC ಮತ್ತು 10 ಗ್ರಾಂ ಸಕ್ಕರೆ ಅಥವಾ ಬೆಲ್ಲವನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗದ ಹತೋಟಿಗೆ ಲೀ. ನೀರಿಗೆ 1.0 ಗ್ರಾಂ ಕಾರ್ಬಂಡೆಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಗ್ರಾಂ ಡಿನೋಕ್ಯಾಪ್ 35 % EC ಅನ್ನು ಲೀ. ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• After 25 days of sowing, weed control through intercropping and top dressing with 50% nitrogen as recommended based on LRI
• When the Kumbala seedlings have 2 to 4 leaves, spray 250 ppm of Ethral solution, which increases the number of female flowers in the vine and increases the yield
• Mix 1 gm of Vegetable Special powder in 15 l. of water and mix well with the juice of one lemon and spray', '•When the fruit fly starts to bloom, spray the crop with 1.0 ml of Malathion 50 EC and 10 g of sugar or jaggery dissolved in 1 liter of water
•To control powdery mildew, spray 1.0 g of Carbandezim 50 WP or 1.5 g of Dinocap 35 % EC dissolved in 1 liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1753, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'NORMAL', 'NO', '• ಬಿತ್ತಿದ 25 ದಿನಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕುಂಬಳ ಸಸಿಗಳು 2 ರಿಂದ 4 ಎಲೆ ಹೊಂದಿದಾಗ 250 ಪಿ.ಪಿ.ಎಮ್. ಇಥ್ರೇಲ್ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು, ಇದರಿಂದ ಬಳ್ಳಿಯಲ್ಲಿ ಹೆಣ್ಣು ಹೂಗಳ ಸಂಖ್ಯೆ ಹೆಚ್ಚಾಗಿ ಇಳುವರಿ ಹೆಚ್ಚುತ್ತದೆ
• 1 ಗ್ರಾಂ ತರಕಾರಿ ಸ್ಪೆಷಲ್ ಪುಡಿಯನ್ನು 15 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಒಂದು ನಿಂಬೆ ಹಣ್ಣಿನ ರಸವನ್ನು ಚೆನ್ನಾಗಿ ಮಿಶ್ರಣ ಮಾಡಿ ಸಿಂಪಡಿಸುವುದು', '•ಹಣ್ಣು ನೊಣದ ಭಾದೆಗೆ ಹೂ ಬಿಡಲು ಪ್ರಾರಂಭವಾದಾಗ ಬೆಳೆಗೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 1.0 ಮಿ.ಲೀ. ಮೆಲಾಥಿಯಾನ್ 50 EC ಮತ್ತು 10 ಗ್ರಾಂ ಸಕ್ಕರೆ ಅಥವಾ ಬೆಲ್ಲವನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಬೂದಿ ರೋಗದ ಹತೋಟಿಗೆ ಲೀ. ನೀರಿಗೆ 1.0 ಗ್ರಾಂ ಕಾರ್ಬಂಡೆಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಗ್ರಾಂ ಡಿನೋಕ್ಯಾಪ್ 35 % EC ಅನ್ನು ಲೀ. ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', '• After 25 days of sowing, weed control through intercropping and top dressing with 50% nitrogen as recommended based on LRI
• When the Kumbala seedlings have 2 to 4 leaves, spray 250 ppm of Ethral solution, which increases the number of female flowers in the vine and increases the yield
• Mix 1 gm of Vegetable Special powder in 15 l. of water and mix well with the juice of one lemon and spray', '•When the fruit fly starts to bloom, spray the crop with 1.0 ml of Malathion 50 EC and 10 g of sugar or jaggery dissolved in 1 liter of water
•To control powdery mildew, spray 1.0 g of Carbandezim 50 WP or 1.5 g of Dinocap 35 % EC dissolved in 1 liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1777, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', NULL, 'Drain excess water from the field, sow short varieties at a distance of 15 cm from seed to seed (40 kg. of seed), and spread varieties at a distance of 30 cm (15-20 kg. of seed).', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1778, 'FRENCH BEAN', NULL, N'2-3 weeks', N'2-3', 'Establishment stage', 2, 'NORMAL', 'YES', '• ಹಬ್ಬುವ ತಳಿಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಬಿತ್ತಿನೆ ಮಾಡಿದ 20 ದಿನಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡುವುದು', '•ಅಗ್ರೋಮೈಜಿಡ್ ಹಾಗೂ ಹೇನುಗಳ ಹತೋಟಿಗೆ ಬಿತ್ತಿದ 2 ವಾರಗಳ ನಂತರ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 EC ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಹಳದಿ ನಂಜು ರೋಗವನ್ನು ತಡೆಗಟ್ಟಲು ಮುಂಜಾಗ್ರತ ಕ್ರಮವಾಗಿ ಲೀ. ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಸೈಂಟ್ರಾನಿಲಿಪ್ರೋಲ್ 10.26 % OD ಅಥವಾ 0.5 ಗ್ರಾಂ. ಅಸೆಟಾಮಿಪ್ರಿಡ್ 20% SP ಅಥವಾ 1.7 ಮಿಲೀ ಡೈಮಿಥೋಯೇಟ್ 30 EC ಸೇರಿಸಿ ಕೀಟನಾಶಕವನ್ನು ಸಿಂಪಡಿಸುವುದು', '• Provide support for creeping varieties to encourage them to spread upwards
• Weed management through intercropping 20 days after sowing', '•For control of agromycide and aphids, spray 1.7 ml of dimethoate 30 EC per liter of water 2 weeks after sowing
•As a preventive measure to prevent yellow fever, spray 2 ml of cytraniliprole 10.26 % OD or 0.5 gm. of acetamiprid 20% SP or 1.7 ml of dimethoate 30 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
