•If the pod borer is found, spray the crop with 0.4 ml Indoxacarb 14.5 SC or 2 ml Malathion 50 EC mixed with water per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1781, 'FRENCH BEAN', NULL, N'2-3 weeks', N'2-3', 'Establishment stage', 2, 'BELOW NORMAL', 'NO', '• ಹಬ್ಬುವ ತಳಿಗಳಿಗೆ ಕೋಲಿನ ಆಸರೆ ಒದಗಿಸಿ ಮೇಲಕ್ಕೆ ಹಬ್ಬುವಂತೆ ಮಾಡುವುದು
• ಒತ್ತಾಗಿರುವ ಕಡೆ ಹೆಚ್ಚು ಗಿಡಗಳನ್ನು ತೆಗೆದು ಸರಿಯಾದ ಸಸ್ಯ ಸಂಖ್ಯೆಯನ್ನು ಕಾಪಾಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Provide support for spreading varieties to encourage them to spread upwards
• Remove excess plants from crowded areas to maintain the right plant population
• Provide conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1782, 'FRENCH BEAN', NULL, N'2-3 weeks', N'2-3', 'Establishment stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1783, 'FRENCH BEAN', NULL, N'2-3 weeks', N'2-3', 'Establishment stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1784, 'FRENCH BEAN', NULL, N'4-5 weeks', N'4-5', 'Growth stage', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ ಶೇ. 12 + ಮ್ಯಾಂಕೋಜೆಬ್ ಶೇ. 63 WP ಮಿಶ್ರಣ ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 0.25 ಮಿ. ಲೀ. ಡೈಫೆನ್ಕೋನಜೋಲ್ ಶೇ. 25 + ಪ್ರೊಪಿಕೊನಜೋಲ್ ಶೇ. 25 ಮಿಶ್ರಣ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಫೈಟೊಪ್ತೋರಾ ಕಾಯಿ ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಕಾಯಿ ಬಲಿಯುವ ಹಂತದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP + ಮೆಟಾಲಾಕ್ಸಿಲ್ MZ 72 WP ಬೆರೆಸಿದ ದ್ರಾವಣದಿಂದ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI', '•If leaf spot disease is found, spray with a mixture of 2 gm Carbendazim 12% + Mancozeb 63% WP per liter of water or 3 gm Thram oxychloride 50 WP or 0.25 ml Difenconazole 25% + Propiconazole 25% mixture
•If Phytophthora fruit rot disease is found, spray with a mixture of 2 gm Mancozeb 75 WP + Metalaxyl MZ 72 WP per liter of water at the stage of fruit ripening', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1785, 'FRENCH BEAN', NULL, N'4-5 weeks', N'4-5', 'Growth stage', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', '•ಎಲೆ ಚುಕ್ಕೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಕಾರ್ಬೆಂಡಜಿಮ್ ಶೇ. 12 + ಮ್ಯಾಂಕೋಜೆಬ್ ಶೇ. 63 WP ಮಿಶ್ರಣ ಅಥವಾ 3 ಗ್ರಾಂ ತ್ರಾಮದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಅಥವಾ 0.25 ಮಿ. ಲೀ. ಡೈಫೆನ್ಕೋನಜೋಲ್ ಶೇ. 25 + ಪ್ರೊಪಿಕೊನಜೋಲ್ ಶೇ. 25 ಮಿಶ್ರಣ ಸೇರಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ಫೈಟೊಪ್ತೋರಾ ಕಾಯಿ ಕೊಳೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಕಾಯಿ ಬಲಿಯುವ ಹಂತದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP + ಮೆಟಾಲಾಕ್ಸಿಲ್ MZ 72 WP ಬೆರೆಸಿದ ದ್ರಾವಣದಿಂದ ಸಿಂಪಡಿಸುವುದು', 'Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI', '•If leaf spot disease is found, spray with a mixture of 2 gm Carbendazim 12% + Mancozeb 63% WP per liter of water or 3 gm Thram oxychloride 50 WP or 0.25 ml Difenconazole 25% + Propiconazole 25% mixture
•If Phytophthora fruit rot disease is found, spray with a mixture of 2 gm Mancozeb 75 WP + Metalaxyl MZ 72 WP per liter of water at the stage of fruit ripening', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1754, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'BELOW NORMAL', 'YES', '• ಬಿತ್ತಿದ 25 ದಿನಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕುಂಬಳ ಸಸಿಗಳು 2 ರಿಂದ 4 ಎಲೆ ಹೊಂದಿದಾಗ 250 ಪಿ.ಪಿ.ಎಮ್. ಇಥ್ರೇಲ್ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು, ಇದರಿಂದ ಬಳ್ಳಿಯಲ್ಲಿ ಹೆಣ್ಣು ಹೂಗಳ ಸಂಖ್ಯೆ ಹೆಚ್ಚಾಗಿ ಇಳುವರಿ ಹೆಚ್ಚುತ್ತದೆ
• 1 ಗ್ರಾಂ ತರಕಾರಿ ಸ್ಪೆಷಲ್ ಪುಡಿಯನ್ನು 15 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಒಂದು ನಿಂಬೆ ಹಣ್ಣಿನ ರಸವನ್ನು ಚೆನ್ನಾಗಿ ಮಿಶ್ರಣ ಮಾಡಿ ಸಿಂಪಡಿಸುವುದು', NULL, '• After 25 days of sowing, weed control through intercropping and top dressing with 50% nitrogen as recommended based on LRI
• When the Kumbala seedlings have 2 to 4 leaves, spray 250 ppm of Ethral solution, which increases the number of female flowers in the vine and increases the yield
• Mix 1 gm of Vegetable Special powder in 15 l. of water and mix well with the juice of one lemon and spray', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1755, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'BELOW NORMAL', 'NO', '• ಬಿತ್ತಿದ 25 ದಿನಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರ ಸಾರಜನಕವನ್ನು ಮೇಲು ಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ಕುಂಬಳ ಸಸಿಗಳು 2 ರಿಂದ 4 ಎಲೆ ಹೊಂದಿದಾಗ 250 ಪಿ.ಪಿ.ಎಮ್. ಇಥ್ರೇಲ್ ದ್ರಾವಣ ಸಿಂಪಡಿಸುವುದು, ಇದರಿಂದ ಬಳ್ಳಿಯಲ್ಲಿ ಹೆಣ್ಣು ಹೂಗಳ ಸಂಖ್ಯೆ ಹೆಚ್ಚಾಗಿ ಇಳುವರಿ ಹೆಚ್ಚುತ್ತದೆ
• 1 ಗ್ರಾಂ ತರಕಾರಿ ಸ್ಪೆಷಲ್ ಪುಡಿಯನ್ನು 15 ಲೀ. ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಒಂದು ನಿಂಬೆ ಹಣ್ಣಿನ ರಸವನ್ನು ಚೆನ್ನಾಗಿ ಮಿಶ್ರಣ ಮಾಡಿ ಸಿಂಪಡಿಸುವುದು', NULL, '• After 25 days of sowing, weed control through intercropping and top dressing with 50% nitrogen as recommended based on LRI
• Conservation irrigation using water available from agricultural wells and other sources
• Spraying 250 ppm of ethral solution when the Kumbala seedlings have 2 to 4 leaves, due to which the number of female flowers in the vine increases and the yield increases
• Mix 1 gram of vegetable special powder in 15 liters of water and mix well with the juice of one lemon and spray', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1756, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1757, 'PUMPKIN', NULL, N'3-5', N'3-5', 'Vegetative Stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1758, 'PUMPKIN', NULL, N'6-11', N'6-11', 'Flower initiation to first picking', 4, 'NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಹೇನು ಬಾಧೆ ಕಂಡುಬಂದಾಗ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೊಯೇಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ ಶೇ. 1.4 ಮಿ.ಲೀ. ಅಝಾಡಿರಕ್ಟಿನ್ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'When aphid infestation is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 17.8 SL or 1.4 ml. Azadirachtin mixed with water per liter', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1759, 'PUMPKIN', NULL, N'6-11', N'6-11', 'Flower initiation to first picking', 4, 'NORMAL', 'NO', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', 'ಹೇನು ಬಾಧೆ ಕಂಡುಬಂದಾಗ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೊಯೇಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 17.8 SL ಅಥವಾ ಶೇ. 1.4 ಮಿ.ಲೀ. ಅಝಾಡಿರಕ್ಟಿನ್ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Carrying out the recommended plant protection measures', 'When aphid infestation is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 17.8 SL or 1.4 ml. Azadirachtin mixed with water per liter', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1760, 'PUMPKIN', NULL, N'6-11', N'6-11', 'Flower initiation to first picking', 4, 'BELOW NORMAL', 'YES', 'ಸೂಚಿಸಲಾದ ಸಸ್ಯ ಸಂರಕ್ಷಣಾ ಕ್ರಮಗಳನ್ನು ಕೈಗೊಳ್ಳುವುದು', '•ಬೂದಿ ರೋಗದ ಹತೋಟಿಗೆ ಲೀ. ನೀರಿಗೆ 1.0 ಗ್ರಾಂ ಕಾರ್ಬಂಡೆಜಿಮ್ 50 WP ಅಥವಾ 1.5 ಗ್ರಾಂ ಡಿನೋಕ್ಯಾಪ್ 35 % EC ಅನ್ನು ಲೀ. ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು
•ನಂಜು ರೋಗಕ್ಕೆ ತುತ್ತಾದ ಗಿಡಗಳನ್ನು ಕಿತ್ತು ಸುಡುವುದರಿಂದ ರೋಗ ಹರಡುವುದನ್ನು ತಡೆಗಟ್ಟಬಹುದು', 'Carrying out the recommended plant protection measures', '•To control powdery mildew, spray 1.0 g Carbandezim 50 WP or 1.5 g Dinocap 35 % EC per liter of water
•Uprooting and burning of plants affected by powdery mildew can prevent the spread of the disease', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
