INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1767, 'PUMPKIN', NULL, N'12-17', N'12-17', 'Harvesting', 5, 'BELOW NORMAL', 'NO', 'ಕುಂಬಳಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Harvesting pumpkins', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1768, 'PUMPKIN', NULL, N'12-17', N'12-17', 'Harvesting', 5, 'ABOVE NORMAL', 'YES', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting nuts when there is no rain
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1769, 'PUMPKIN', NULL, N'12-17', N'12-17', 'Harvesting', 5, 'ABOVE NORMAL', 'NO', '• ಮಳೆ ಇಲ್ಲದ ಸಂದರ್ಭದಲ್ಲಿ ಕಾಯಿಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು
• ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, '• Harvesting nuts when there is no rain
• If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1770, 'PUMPKIN', NULL, N'>17', N'>17', 'Post harvest', 6, 'NIL', 'NIL', '• ಕುಂಬಳ ಬಳ್ಳಿಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ತೆಗೆದುಹಾಕಿ, ಹಣ್ಣುನೊಣ ಬಾಧಿತ ಹಣ್ಣುಗಳನ್ನು ಸಂಗ್ರಹಿಸಿ ನಾಶಪಡಿಸುವುದು
• ಮಣ್ಣಿನಲ್ಲಿ ಇರುವ ಹಣ್ಣುನೊಣದ ಅವಶೇಷಗಳನ್ನು ನಾಶಪಡಿಸಲು ಆಳವಾದ ಉಳುಮೆ ಮಾಡಿ, ಮಣ್ಣನ್ನು ಸೂರ್ಯನ ಕಿರಣಗಳಿಗೆ ಒಡ್ಡುವುದು
• ಮುಂದಿನ ಋತುವಿನ ಬೆಳೆಗಾಗಿ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸಿ
• ಕೀಟಗಳ ಜೀವನಚಕ್ರವನ್ನು ಮುರಿಯಲು ಕುಂಬಳ ಜಾತಿಗೆ ಸೇರಿರದ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು', NULL, '• Remove all fruit flies and collect and destroy fruit flies
• Deep ploughing to destroy fruit fly residues in the soil and expose the soil to sunlight
• Incorporate manure into the soil for the next season''s crop
• Crop rotation with non-fruit fly species to break the insect life cycle', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1771, 'FRENCH BEAN', NULL, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಉಳುಮೆ ಮಾಡಿ ಚೆನ್ನಾಗಿ ಹದ ಮಾಡಿ, ಗಿಡ್ಡ ತಳಿಗಳಿಗೆ 45 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಹಾಗೂ ಹಬ್ಬುವ ತಳಿಗಳಿಗೆ 120 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ ಬೋದು ಮತ್ತು ಹರಿಗಳನ್ನು ಮಾಡುವುದು. ನಂತರ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕ ಮತ್ತು ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಅನ್ನು ಹರಿಗಳಲ್ಲಿ ಹಾಕುವುದು', NULL, 'Preparation: Plough the land 2-3 times and harrow it well, make furrows and furrows at 45 cm. for short varieties and 120 cm. for spreading varieties. Then apply the recommended manure, 50% of the recommended nitrogen based on LRI and full amount of phosphorus and potash in the furrows.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1772, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'NORMAL', 'YES', 'ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', 'ನುಸಿ ಬಾಧೆ ತಡೆಗಟ್ಟಲು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಪ್ರೋಪಾರ್‌ಗೈಟ್ 57 EC ಅಥವಾ 2.5 ಮಿ.ಲೀ. ಡೈಕೋಫಾಲ್ 18.5 EC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Sow seeds of short varieties at a distance of 15 cm from seed to seed (40 kg. of seed), seeds of spreading varieties at a distance of 30 cm (15-20 kg. of seed).', 'To prevent pest infestation, spray 2 ml of Propargite 57 EC or 2.5 ml of Dicofol 18.5 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1773, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', 'ನುಸಿ ಬಾಧೆ ತಡೆಗಟ್ಟಲು ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಮಿ.ಲೀ. ಪ್ರೋಪಾರ್‌ಗೈಟ್ 57 EC ಅಥವಾ 2.5 ಮಿ.ಲೀ. ಡೈಕೋಫಾಲ್ 18.5 EC ಯನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Sow seeds of short varieties at a distance of 15 cm from seed to seed (40 kg. of seed), and seeds of spreading varieties at a distance of 30 cm (15-20 kg. of seed) keeping in mind the rainfall forecast.', 'To prevent pest infestation, spray 2 ml of Propargite 57 EC or 2.5 ml of Dicofol 18.5 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1774, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, short varieties should be sown at a distance of 15 cm from seed to seed (40 kg. of seed), and spreading varieties should be sown at a distance of 30 cm (15-20 kg. of seed).', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1775, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, short varieties should be sown at a distance of 15 cm from seed to seed (40 kg. of seed), and spreading varieties should be sown at a distance of 30 cm (15-20 kg. of seed).', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1776, 'FRENCH BEAN', NULL, N'1 week', N'1', 'Sowing', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಗಿಡ್ಡ ತಳಿಗಳನ್ನು ಬೀಜದಿಂದ ಬೀಜಕ್ಕೆ 15 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (40 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ), ಹಬ್ಬುವ ತಳಿಗಳ ಬೀಜಗಳನ್ನು 30 ಸೆಂ. ಮೀ. ಅಂತರದಲ್ಲಿ (15-20 ಕಿ. ಗ್ರಾಂ. ಬಿತ್ತನೆ ಬೀಜ) ಬಿತ್ತನೆ ಮಾಡುವುದು', NULL, 'Drain excess water from the field, sow short varieties at a distance of 15 cm from seed to seed (40 kg. of seed), and spread varieties at a distance of 30 cm (15-20 kg. of seed).', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1742, 'PUMPKIN', NULL, N'1', N'1', 'Sowing', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಪ್ರತಿ ಮಡಿಯಲ್ಲಿ 3 ರಿಂದ 5 ಬೀಜಗಳನ್ನು ಬಿತ್ತುವುದು. ಒಂದು ಹೆಕ್ಟೇರ್ ಗೆ 4 ಕಿಲೊ ಗ್ರಾಂ ಬಿತ್ತನೆ ಬೀಜ ಬೇಕಾಗುತ್ತದೆ', NULL, 'If irrigation facilities are available, 3 to 5 seeds are sown in each furrow. 4 kg of seeds are required per hectare.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1743, 'PUMPKIN', NULL, N'1', N'1', 'Sowing', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಪ್ರತಿ ಮಡಿಯಲ್ಲಿ 3 ರಿಂದ 5 ಬೀಜಗಳನ್ನು ಬಿತ್ತುವುದು. ಒಂದು ಹೆಕ್ಟೇರ್ ಗೆ 4 ಕಿಲೊ ಗ್ರಾಂ ಬಿತ್ತನೆ ಬೀಜ ಬೇಕಾಗುತ್ತದೆ', NULL, 'If irrigation facilities are available, 3 to 5 seeds are sown in each furrow. 4 kg of seeds are required per hectare.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1744, 'PUMPKIN', NULL, N'1', N'1', 'Sowing', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಪ್ರತಿ ಮಡಿಯಲ್ಲಿ 3 ರಿಂದ 5 ಬೀಜಗಳನ್ನು ಬಿತ್ತುವುದು. ಒಂದು ಹೆಕ್ಟೇರ್ ಗೆ 4 ಕಿಲೊ ಗ್ರಾಂ ಬಿತ್ತನೆ ಬೀಜ ಬೇಕಾಗುತ್ತದೆ', NULL, 'Allow excess water to drain from the field and sow 3 to 5 seeds in each furrow. 4 kg of seeds are required per hectare.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1745, 'PUMPKIN', NULL, N'1', N'1', 'Sowing', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಪ್ರತಿ ಮಡಿಯಲ್ಲಿ 3 ರಿಂದ 5 ಬೀಜಗಳನ್ನು ಬಿತ್ತುವುದು. ಒಂದು ಹೆಕ್ಟೇರ್ ಗೆ 4 ಕಿಲೊ ಗ್ರಾಂ ಬಿತ್ತನೆ ಬೀಜ ಬೇಕಾಗುತ್ತದೆ', NULL, 'Allow excess water to drain from the field and sow 3 to 5 seeds in each furrow. 4 kg of seeds are required per hectare.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1746, 'PUMPKIN', NULL, N'1-2', N'1-2', 'Crop Establishment Stage', 2, 'NORMAL', 'YES', 'ಮೊಳಕೆ ಬಾರದಿರುವ ಜಾಗದಲ್ಲಿ ಮರುಬಿತ್ತನೆ ಮಾಡುವುದು', '•ಕುಂಬಳ ದುಂಬಿ ಭಾದೆ ಕಂಡುಬಂದಲ್ಲಿ ಬಿತ್ತಿದ 3 ವಾರಗಳ ನಂತರ ಶೇ. 4ರ ಬೇವಿನ ಬೀಜದ ಕಷಾಯವನ್ನು 1 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ
•ಬೂಜು ತುಪ್ಪಟ ರೋಗಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Reseeding in areas where seedlings have not sprouted', '•If there is a problem of Kumbala Dumbi, it is better to spray 4% neem seed extract dissolved in 1 liter of water 3 weeks after sowing
•For powdery mildew, spray 2 grams of Mancozeb 75 WP mixed with 1 liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
