INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1749, 'PUMPKIN', NULL, N'1-2', N'1-2', 'Crop Establishment Stage', 2, 'BELOW NORMAL', 'NO', '• ಹೆಚ್ಚಾಗಿರುವ ಗಿಡಗಳನ್ನು ತೆಗೆದುಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Removing overgrown plants
• Providing conservation irrigation using water available from agricultural wells and other sources', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1750, 'PUMPKIN', NULL, N'1-2', N'1-2', 'Crop Establishment Stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1831, 'BANANA', NULL, N'1 week', N'1', 'Planting', 1, 'NORMAL', 'NO', '• ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಅಂಗಾಂಶ ಸಸಿ/ ಕಂದುಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು, ನಾಟಿ ಮಾಡಿದ ಕೂಡಲೆ ನೀರುಣಿಸುವುದು
• ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', 'ಕಂದುಗಳನ್ನು ಶೇ.20 ಬೇವಿನ ಬೀಜ ಅಥವಾ ಶೇ. 0.1 ರ ಕಾರ್ಬೆನ್‌ಡೆಜಿಮ್ 50 WP ಅಥವಾ ಶೇ. 0.1 ರ ಪ್ರೋಪಿಕೋನಜೋಲ್ 25 EC ದ್ರಾವಣದಲ್ಲಿ ಕೆಲ ನಿಮಿಷ ಅದ್ದಿ ನಾಟಿಮಾಡುವುದರಿಂದ ಮುಂಬರುವ ಕೀಟ ಹಾಗೂ ರೋಗದ ಭಾದೆಯಿಂದ ಕಾಪಾಡಬಹುದು', '• Planting of tissue seedlings/roots keeping in mind the rainfall forecast, watering immediately after planting
• Then providing recommended fertilizers based on LRI', 'Soaking the seedlings in 20% neem seed or 0.1% Carbendazim 50 WP or 0.1% Propiconazole 25 EC solution for a few minutes before planting can protect them from future pest and disease attacks', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
