INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1839, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'BELOW NORMAL', 'NO', '• ನಾಟಿ ಮಾಡಿದ ನಂತರ 35 ದಿನಗಳ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು
• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ಪ್ರಾರಂಭದ 3-4 ತಿಂಗಳು ಅಲ್ಪಾವಧಿ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಮತ್ತು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳನ್ನು ಅಂತರ ಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Intercrop twice at 35 days interval after planting, provide recommended fertilizer based on LRI and harrow the soil
• Provide conservation irrigation using water available from agricultural wells, other sources
• Remove all weeds coming next to the mother plant
• For the initial 3-4 months, short-term vegetable crops and pulses can be grown as intercrops', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1840, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಿಗಟೋಕಾ ಎಲೆ ಚುಕ್ಕೆ ರೋಗಕ್ಕೆ 1.0 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 5 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 25 EC + ಶೇ.1 ಪೆಟ್ರೋಲಯಂ ಮಿನರಲ್ ಎಣ್ಣೆ ಅಥವಾ 1 ಗ್ರಾಂ ಥಯೋಫಿನೇಟ್ ಮಿಥೈಲ್ ಶೇ. 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ತೀವ್ರತೆ ಹೆಚ್ಚಾಗಿರುವ ಪ್ರದೇಶದಲ್ಲಿ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯುವುದು ಸೂಕ್ತ', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For Sigatoka leaf spot, spray 1.0 ml Propiconazole 5 EC or 0.5 ml Propiconazole 25 EC + 1% petroleum mineral oil or 1 g Thiophinate methyl 70% WP per liter of water. It is advisable to grow resistant varieties in areas where the disease is severe', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1841, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1842, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'NORMAL', 'YES', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ 3 ತಿಂಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರಿಹಾಕುವುದು', '•ಸಸ್ಯ ಹೇನು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೊಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆ ಸುರುಳಿ ಹುಳುವಿನ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 2.5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC  ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Remove all the weeds coming near the mother plant
• Intercrop 3 months after planting, provide recommended fertilizer based on LRI and till the soil', '•If aphids are found, spray 0.3 ml of Imidacloprid 17.8 SL or 1.7 ml of Dimethoate 30 EC per liter of water
•For the control of leaf curl, spray 2.5 ml of Chlorpyrifos 20 EC or 2.0 ml of Quinalphos 25 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1836, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'NORMAL', 'YES', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ 35 ದಿನಗಳ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು
• ಪ್ರಾರಂಭದ 3-4 ತಿಂಗಳು ಅಲ್ಪಾವಧಿ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಮತ್ತು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳನ್ನು ಅಂತರ ಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರೆಯುವ ಮೂತಿ ಹುಳುವಿನ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ 5 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಕಾಂಡಕ್ಕೆ ಭೂಮಿಯಿಂದ 1 ಅಡಿ ಎತ್ತರಕ್ಕೆ ಚುಚ್ಚುಮದ್ದಿನ ಮೂಲಕ ಕೊಡುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2.5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಬೆರೆಸಿ ಕಾಂಡದ ಮೇಲೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Remove all the weeds coming next to the mother plant
• Intercrop twice at an interval of 35 days after planting, then provide fertilizer as recommended based on LRI and till the soil
• For the initial 3-4 months, short-term vegetable crops and pulses can be grown as intercrops', 'For the control of stem borer, it is better to spray 5 ml. Chlorpyrifos 20 EC or 5 ml. Dimethoate 30 EC per liter of water on the stem at a height of 1 foot from the ground or mix 2.5 ml. Chlorpyrifos 20 EC per liter of water and spray it on the stem', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1837, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'NORMAL', 'NO', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ 35 ದಿನಗಳ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು
• ಪ್ರಾರಂಭದ 3-4 ತಿಂಗಳು ಅಲ್ಪಾವಧಿ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಮತ್ತು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳನ್ನು ಅಂತರ ಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', 'ಕಾಂಡ ಕೊರೆಯುವ ಮೂತಿ ಹುಳುವಿನ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ 5 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಕಾಂಡಕ್ಕೆ ಭೂಮಿಯಿಂದ 1 ಅಡಿ ಎತ್ತರಕ್ಕೆ ಚುಚ್ಚುಮದ್ದಿನ ಮೂಲಕ ಕೊಡುವುದು ಅಥವಾ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿಗೆ 2.5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಬೆರೆಸಿ ಕಾಂಡದ ಮೇಲೆ ಸಿಂಪಡಿಸುವುದು ಉತ್ತಮ', '• Remove all the weeds coming next to the mother plant
• Intercrop twice at an interval of 35 days after planting, then provide fertilizer as recommended based on LRI and till the soil
• For the initial 3-4 months, short-term vegetable crops and pulses can be grown as intercrops', 'For the control of stem borer, it is better to spray 5 ml. Chlorpyrifos 20 EC or 5 ml. Dimethoate 30 EC per liter of water on the stem at a height of 1 foot from the ground or mix 2.5 ml. Chlorpyrifos 20 EC per liter of water and spray it on the stem', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1838, 'BANANA', NULL, N'2-9 week', N'2-9', 'Growth stage', 2, 'BELOW NORMAL', 'YES', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ ನಂತರ 35 ದಿನಗಳ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು
• ಪ್ರಾರಂಭದ 3-4 ತಿಂಗಳು ಅಲ್ಪಾವಧಿ ತರಕಾರಿ ಬೆಳೆಗಳನ್ನು ಮತ್ತು ದ್ವಿದಳಧಾನ್ಯ ಬೆಳೆಗಳನ್ನು ಅಂತರ ಬೆಳೆಗಳನ್ನಾಗಿ ಬೆಳೆಯಬಹುದು', NULL, '• Remove all the weeds coming next to the mother plant
• Intercrop twice at an interval of 35 days after planting, provide fertilizer as recommended based on LRI and till the soil
• For the initial 3-4 months, short-term vegetable crops and pulses can be grown as intercrops', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1792, 'FRENCH BEAN', NULL, N'6-7 weeks', N'6-7', 'Flowering stage', 4, 'BELOW NORMAL', 'YES', 'ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸಿ', NULL, 'If the crop is good at the current stage, focus on managing other crops if they have grown.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1793, 'FRENCH BEAN', NULL, N'6-7 weeks', N'6-7', 'Flowering stage', 4, 'BELOW NORMAL', 'NO', 'ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, 'Irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1794, 'FRENCH BEAN', NULL, N'6-7 weeks', N'6-7', 'Flowering stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
