INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1814, 'SWEET POTATO', 65, N'2-5 weeks', N'2-5', 'Growing stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1815, 'SWEET POTATO', 65, N'2-5 weeks', N'2-5', 'Growing stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If leaf spot disease is found, destroy the dried and fallen leaves. To prevent the spread of the disease, spray with a solution containing 0.2% Mancozeb 75 WP or 3 gm of Thram oxychloride 50 WP', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1816, 'SWEET POTATO', 65, N'6-20 weeks', N'6-20', 'Tuber development stage', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1817, 'SWEET POTATO', 65, N'6-20 weeks', N'6-20', 'Tuber development stage', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯದ ಮೂಲಕ ಕಳೆ ನಿರ್ವಹಣೆ ಮಾಡಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50 ರಷ್ಟು ಸಾರಜನಕವನ್ನು ಮೇಲುಗೊಬ್ಬರವಾಗಿ ಕೊಡುವುದು', NULL, 'Weed management through intercropping and top dressing with 50% of the recommended nitrogen based on LRI', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
