INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1826, 'SWEET POTATO', 65, N'21-22 weeks', N'21-22', 'Harvesting stage', 4, 'ABOVE NORMAL', 'YES', 'ನೀರು ನಿಂತಿದ್ದರೆ ಬಸಿಯುವುದು ಮತ್ತು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Drying and harvesting if water is stagnant', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1827, 'SWEET POTATO', 65, N'21-22 weeks', N'21-22', 'Harvesting stage', 4, 'ABOVE NORMAL', 'NO', 'ನೀರು ನಿಂತಿದ್ದರೆ ಬಸಿಯುವುದು ಮತ್ತು ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Drying and harvesting if water is stagnant', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1828, 'SWEET POTATO', 65, N'>22 weeks', N'>22', 'Post Harvest', 5, 'NIL', 'NIL', '• ಹೊಲದಲ್ಲಿರುವ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ಸಂಪೂರ್ಣವಾಗಿ ತೆಗೆಯುವುದು
• ಬೇಸಿಗೆಯ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಕೀಟಗಳ ಅವಶೇಷಗಳನ್ನು ನಾಶ ಮಾಡುವುದು
• ಅದೇ ಹೊಲದಲ್ಲಿ ನಿರಂತರವಾಗಿ ಸಿಹಿಗೆಣಸು ಬೆಳೆಸುವುದನ್ನು ತಪ್ಪಿಸಿ
• ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಲು ಸಾವಯವ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು', NULL, '• Thoroughly remove crop residues from the field
• Deep summer plowing to destroy insect residues
• Avoid growing sweet potatoes continuously in the same field
• Add organic fertilizers to the soil to improve soil health', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1829, 'BANANA', NULL, N'-2 week', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವಸಿದ್ದತೆ: ಭೂಮಿಯನ್ನು 2-3 ಬಾರಿ ಚೆನ್ನಾಗಿ ಉಳುಮೆ ಮಾಡಿ ಸಿದ್ಧಪಡಿಸಿ ನಂತರ ತಳಿಗಳಿಗನುಗುಣವಾಗಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಅಂತರದಲ್ಲಿ 45x45x45 ಸೆಂ.ಮೀ. ಗಾತ್ರದ ಗುಣಿಗಳನ್ನು ಅಗೆದು ಸಮಪ್ರಮಾಣದಲ್ಲಿ ಬೆರೆಸಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಮೇಲ್ಮಣ್ಣಿನ ಮಿಶ್ರಣವನ್ನು ಹಾಕಿ ತುಂಬುವುದು', NULL, 'Preparation: Prepare the land by ploughing it well 2-3 times and then dig holes of 45x45x45 cm at the recommended spacing according to the varieties and fill them with a mixture of equal amounts of manure and topsoil.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1830, 'BANANA', NULL, N'1 week', N'1', 'Planting', 1, 'NORMAL', 'YES', '• ಅಂಗಾಂಶ ಸಸಿ/ ಕಂದುಗಳನ್ನು ನಾಟಿ ಮಾಡುವುದು, ನಾಟಿ ಮಾಡಿದ ಕೂಡಲೆ ನೀರುಣಿಸುವುದು
• ನಂತರ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರಗಳನ್ನು ಒದಗಿಸುವುದು', 'ಕಂದುಗಳನ್ನು ಶೇ.20 ಬೇವಿನ ಬೀಜ ಅಥವಾ ಶೇ. 0.1 ರ ಕಾರ್ಬೆನ್‌ಡೆಜಿಮ್ 50 WP ಅಥವಾ ಶೇ. 0.1 ರ ಪ್ರೋಪಿಕೋನಜೋಲ್ 25 EC ದ್ರಾವಣದಲ್ಲಿ ಕೆಲ ನಿಮಿಷ ಅದ್ದಿ ನಾಟಿಮಾಡುವುದರಿಂದ ಮುಂಬರುವ ಕೀಟ ಹಾಗೂ ರೋಗದ ಭಾದೆಯಿಂದ ಕಾಪಾಡಬಹುದು', '• Planting of tissue seedlings/roots, watering immediately after planting
• Then providing recommended fertilizers based on LRI', 'Soaking the seedlings in 20% neem seed or 0.1% Carbendazim 50 WP or 0.1% Propiconazole 25 EC solution for a few minutes before planting can protect them from future pest and disease attacks', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1848, 'BANANA', NULL, N'20-32 weeks', N'20-32', 'Flower bud diferentiation', 4, 'NORMAL', 'YES', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• 5 ವಾರಗಳ ಅಂತರದಲ್ಲಿ 2 ಬಾರಿ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು', '•ಪನಾಮ ಸೊರಗು ರೋಗಕ್ಕೆ 100 ಗ್ರಾಂ ಕಾರ್ಬೆನ್‌ಡೆಜಿಮ್ 50 WP ಅಥವಾ ಮೆಥಾಮ್ ಸೋಡಿಯಂ ಅನ್ನು 100 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಗಿಡದ ಸುತ್ತಲು ಭೂಮಿಗೆ ಸುರಿಯುವುದು
•ಫ್ರೆಕಲ್ ಎಲೆಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2.5 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಮತ್ತು 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Remove all the weeds coming next to the mother plant
• Intercrop twice at 5 weeks interval, provide recommended fertilizer based on LRI and till the soil', '•For Panama leaf blight, dissolve 100 grams of Carbendazim 50 WP or Metham Sodium in 100 liters of water and pour it on the soil around the plant. •If freckle leaf spot is found, spray 2.5 grams of Mancozeb 75 WP and 3 grams of Copper Oxychloride 50 WP mixed in each liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
