INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1851, 'BANANA', NULL, N'20-32 weeks', N'20-32', 'Flower bud diferentiation', 4, 'BELOW NORMAL', 'NO', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
