INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1869, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seeded ginger pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot, keeping in mind the rainfall forecast', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1870, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting ginger seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1871, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'NO', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting ginger seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1872, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'YES', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the land and plant the ginger seed pieces (pieces weighing at least 15-25 grams) in the beds at a distance of 1 foot.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1873, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'ABOVE NORMAL', 'NO', 'ಹೆಚ್ಚಾಗಿರುವ ನೀರನ್ನು ಜಮೀನಿನಿಂದ ಬಸಿದುಹೋಗುವಂತೆ ಮಾಡಿ, ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Drain excess water from the land and plant the ginger seed pieces (pieces weighing at least 15-25 grams) in the beds at a distance of 1 foot.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1874, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 1 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಾಸಿಹಲೋಥ್ರಿನ್ 5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', '•If stem and tuber borer is found, spray 0.25 ml. Spinosad 45 SC or 1 ml. Lambdacyhalothrin 5 EC per liter of water or mix 250 kg. Neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 200 SL per liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1880, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', '•ಎಲೆ ತಿನ್ನುವ ಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ ಶೇ. 5 ರ ಬೇವಿನ ಕಷಾಯ ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ. ಲೀ. ಫೋಸಲೋನ್ 50 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆಚುಕ್ಕೆ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗಗಳ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', '•If leaf-eating worms are found, spray with 5% neem infusion or 2 ml. Quinalphos 25 EC or 2 ml. Phosalone 50 EC per liter of water
•If leaf spot and powdery mildew are found, spray with 2 gm Mancozeb 75 WP or 1 gm Carbondiazim 50 WP dissolved in 1 liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1881, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', '•ಎಲೆ ತಿನ್ನುವ ಹುಳು ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ ಶೇ. 5 ರ ಬೇವಿನ ಕಷಾಯ ಅಥವಾ 2 ಮಿ. ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC ಅಥವಾ 2 ಮಿ. ಲೀ. ಫೋಸಲೋನ್ 50 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆಚುಕ್ಕೆ ಹಾಗೂ ಚಿಬ್ಬು ರೋಗಗಳ ಬಾಧೆ ಕಂಡು ಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', '•If leaf-eating worms are found, spray with 5% neem infusion or 2 ml. Quinalphos 25 EC or 2 ml. Phosalone 50 EC per liter of water
•If leaf spot and powdery mildew are found, spray with 2 gm Mancozeb 75 WP or 1 gm Carbondiazim 50 WP dissolved in 1 liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1882, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'BELOW NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', 'Intercropping and providing 50% of the recommended nitrogen based on LRI', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1883, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಪ್ರಸ್ತುತ ಹಂತದಲ್ಲಿ ಬೆಳೆ ಉತ್ತಮವಾಗಿದ್ದರೆ, ಇತರೆ ಬೆಳೆ ಬೆಳೆದಿದ್ದಲ್ಲಿ ಅವುಗಳ ನಿರ್ವಹಣೆಯತ್ತ ಗಮನಹರಿಸಿ', NULL, '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• If the crop is doing well at the current stage, focus on managing other crops if they are growing.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1884, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ರೋಗಗ್ರಸ್ಥ ಗಡ್ಡೆಗಳನ್ನು ತೆಗೆದು ಹಾಕಿ, ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍3 ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್‍ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣವನ್ನು ರೋಗ ಬಂದ ಮಡಿಗೆ ಹಾಗೂ ಸುತ್ತಮುತ್ತಲಿನ ಮಡಿಗಳಿಗೆ ಹಾಕುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If tuber rot is detected, remove the diseased tubers and then apply a solution prepared by mixing 3 grams of copper oxychloride 50 WP per 3 liters of water to the affected tuber and surrounding tubers', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1875, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅಥವಾ 1 ಮಿ.ಲೀ. ಲ್ಯಾಂಬ್ಡಾಸಿಹಲೋಥ್ರಿನ್ 5 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 200 SL ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', '•If stem and tuber borer is found, spray 0.25 ml. Spinosad 45 SC or 1 ml. Lambdacyhalothrin 5 EC per liter of water or mix 250 kg. Neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. Dimethoate 30 EC or 0.5 ml. Imidacloprid 200 SL per liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1876, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'BELOW NORMAL', 'YES', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching the soil around the plant', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1877, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'BELOW NORMAL', 'NO', '• ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ಒದಗಿಸುವುದು
• ಗಿಡದ ಸುತ್ತಲು ಮಣ್ಣನ್ನು ಏರಿಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Intercropping and providing 50% of the recommended nitrogen based on LRI
• Mulching around the plant
• Conservation irrigation using water available from farm wells and other sources', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1878, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ರೋಗಗ್ರಸ್ಥ ಗಡ್ಡೆಗಳನ್ನು ತೆಗೆದು ಹಾಕಿ, ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍3 ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್‍ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣವನ್ನು ರೋಗ ಬಂದ ಮಡಿಗೆ ಹಾಗೂ ಸುತ್ತಮುತ್ತಲಿನ ಮಡಿಗಳಿಗೆ ಹಾಕುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'If tuber rot is detected, remove the diseased tubers and then apply a solution prepared by mixing 3 grams of copper oxychloride 50 WP per 3 liters of water to the affected tuber and surrounding tubers', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1879, 'GINGER', 29, N'2-10', N'2-10', 'Growth stage', 2, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1852, 'BANANA', NULL, N'20-32 weeks', N'20-32', 'Flower bud diferentiation', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಿಗಟೋಕಾ ಎಲೆ ಚುಕ್ಕೆ ರೋಗಕ್ಕೆ 1.0 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 5 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 25 EC + ಶೇ.1 ಪೆಟ್ರೋಲಯಂ ಮಿನರಲ್ ಎಣ್ಣೆ ಅಥವಾ 1 ಗ್ರಾಂ ಥಯೋಫಿನೇಟ್ ಮಿಥೈಲ್ ಶೇ. 70 WP ಅನ್ನು ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ತೀವ್ರತೆ ಹೆಚ್ಚಾಗಿರುವ ಪ್ರದೇಶದಲ್ಲಿ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯುವುದು ಸೂಕ್ತ', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For Sigatoka leaf spot, spray 1.0 ml Propiconazole 5 EC or 0.5 ml Propiconazole 25 EC + 1% petroleum mineral oil or 1 g Thiophinate methyl 70% WP per liter of water. It is advisable to grow resistant varieties in areas where the disease is more severe', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1853, 'BANANA', NULL, N'20-32 weeks', N'20-32', 'Flower bud diferentiation', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1854, 'BANANA', NULL, N'33-37 weeks', N'33-37', 'Shooting stage', 5, 'NORMAL', 'YES', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', '•ತುದಿ ಕೊಳೆ ರೋಗಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಜೊತೆಗೆ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ 0.3 ಗ್ರಾಂ ಅನ್ನು ಬೆರೆಸಿದ ದ್ರಾವಣದಿಂದ ತಿಂಗಳಿಗೊಮ್ಮೆ ಮೂರು ಬಾರಿ ತೋಯಿಸುವುದು
•ಬಂಚಿಟಾಪ್ ನಂಜು ರೋಗಕ್ಕೆ ಹಾಗೂ ರೋಗ ಹರಡುವ ಸಸ್ಯ ಹೇನುಗಳ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 18.5 SL ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing recommended fertilizer based on LRI', '•For tip rot disease, drench thrice a month with a solution of 3 gm of copper oxychloride 50 WP and 0.3 gm of streptocycline per liter of water
•For bunchytop blight and to control disease-spreading aphids, spray 0.25 ml of imidacloprid 18.5 SL or 1.7 ml of dimethoate 30 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1855, 'BANANA', NULL, N'33-37 weeks', N'33-37', 'Shooting stage', 5, 'NORMAL', 'NO', 'ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸುವುದು', '•ತುದಿ ಕೊಳೆ ರೋಗಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಜೊತೆಗೆ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ 0.3 ಗ್ರಾಂ ಅನ್ನು ಬೆರೆಸಿದ ದ್ರಾವಣದಿಂದ ತಿಂಗಳಿಗೊಮ್ಮೆ ಮೂರು ಬಾರಿ ತೋಯಿಸುವುದು
•ಬಂಚಿಟಾಪ್ ನಂಜು ರೋಗಕ್ಕೆ ಹಾಗೂ ರೋಗ ಹರಡುವ ಸಸ್ಯ ಹೇನುಗಳ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೋಪ್ರಿಡ್ 18.5 SL ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', 'Intercropping and providing recommended fertilizer based on LRI', '•For tip rot disease, drench thrice a month with a solution of 3 gm of copper oxychloride 50 WP and 0.3 gm of streptocycline per liter of water
•For bunchytop blight and to control disease-spreading aphids, spray 0.25 ml of imidacloprid 18.5 SL or 1.7 ml of dimethoate 30 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
