INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1858, 'BANANA', NULL, N'33-37 weeks', N'33-37', 'Shooting stage', 5, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1859, 'BANANA', NULL, N'33-37 weeks', N'33-37', 'Shooting stage', 5, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1860, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'NORMAL', 'YES', '• ಗಿಡಗಳು ಬೀಳದಂತೆ ಕೋಲನ್ನು ಕಟ್ಟಿ ಆಸರೆ ಒದಗಿಸುವುದು
• ಗೊನೆಯಲ್ಲಿ ಕೊನೆಯ ಕಾಯಿಗಳು ಕಚ್ಚಿದ ನಂತರ ತುದಿಯಲ್ಲಿರುವ ಗಂಡು ಹೂ ಭಾಗವನ್ನು ಕತ್ತರಿಸುವುದು', 'ಸಸ್ಯ ಜಂತು ರೋಗ ನಿಯಂತ್ರಣಕ್ಕೆ 12.5 ಗ್ರಾಂ ಸೂಡಮಾನಸ್  + 12.5 ಗ್ರಾಂ  ಪಿಸಿಲೂಮೈಸಿಸ್ ಲಿಲಾಸಿನಸ್ ಜೊತೆಗೆ 500 ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿಯನ್ನು ಪ್ರತಿ ಗಿಡದ ಭೂಮಿಗೆ ಸೇರಿಸುವುದು', '• Provide support by tying a stick to prevent the plants from falling. • Cut off the male flower part at the tip after the last fruits have been bitten in the stalk.', 'For plant pest control, add 12.5 gm of Sudamanus + 12.5 gm of Psillomyces lilacinus along with 500 gm of neem powder to the soil of each plant', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1861, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'NORMAL', 'NO', '• ಗಿಡಗಳು ಬೀಳದಂತೆ ಕೋಲನ್ನು ಕಟ್ಟಿ ಆಸರೆ ಒದಗಿಸುವುದು
• ಗೊನೆಯಲ್ಲಿ ಕೊನೆಯ ಕಾಯಿಗಳು ಕಚ್ಚಿದ ನಂತರ ತುದಿಯಲ್ಲಿರುವ ಗಂಡು ಹೂ ಭಾಗವನ್ನು ಕತ್ತರಿಸುವುದು', 'ಸಸ್ಯ ಜಂತು ರೋಗ ನಿಯಂತ್ರಣಕ್ಕೆ 12.5 ಗ್ರಾಂ ಸೂಡಮಾನಸ್  + 12.5 ಗ್ರಾಂ  ಪಿಸಿಲೂಮೈಸಿಸ್ ಲಿಲಾಸಿನಸ್ ಜೊತೆಗೆ 500 ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿಯನ್ನು ಪ್ರತಿ ಗಿಡದ ಭೂಮಿಗೆ ಸೇರಿಸುವುದು', '• Provide support by tying a stick to prevent the plants from falling. • Cut off the male flower part at the tip after the last fruits have been bitten in the stalk.', 'For plant pest control, add 12.5 gm of Sudamanus + 12.5 gm of Psillomyces lilacinus along with 500 gm of neem powder to the soil of each plant', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1862, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'BELOW NORMAL', 'YES', '• ಗಿಡಗಳು ಬೀಳದಂತೆ ಕೋಲನ್ನು ಕಟ್ಟಿ ಆಸರೆ ಒದಗಿಸುವುದು
• ಗೊನೆಯಲ್ಲಿ ಕೊನೆಯ ಕಾಯಿಗಳು ಕಚ್ಚಿದ ನಂತರ ತುದಿಯಲ್ಲಿರುವ ಗಂಡು ಹೂ ಭಾಗವನ್ನು ಕತ್ತರಿಸುವುದು', '•ಪನಾಮ ಸೊರಗು ರೋಗಕ್ಕೆ 100 ಗ್ರಾಂ ಕಾರ್ಬೆನ್‌ಡೆಜಿಮ್ 50 WP ಅಥವಾ ಮೆಥಾಮ್ ಸೋಡಿಯಂ ಅನ್ನು 100 ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಕರಗಿಸಿ ಗಿಡದ ಸುತ್ತಲು ಭೂಮಿಗೆ ಸುರಿಯುವುದು
•ಫ್ರೆಕಲ್ ಎಲೆಚುಕ್ಕೆ ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2.5 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಮತ್ತು 3 ಗ್ರಾಂ ತಾಮ್ರದ ಆಕ್ಸಿಕ್ಲೋರೈಡ್ 50 WP ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Provide support by tying a stick to prevent the plants from falling. • Cut off the male flower part at the tip after the last fruits have been bitten in the stalk.', '•For Panama leaf blight, dissolve 100 grams of Carbendazim 50 WP or Metham Sodium in 100 liters of water and pour it on the soil around the plant. •If freckle leaf spot is found, spray 2.5 grams of Mancozeb 75 WP and 3 grams of Copper Oxychloride 50 WP mixed in each liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1863, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'BELOW NORMAL', 'NO', '• ಗಿಡಗಳು ಬೀಳದಂತೆ ಕೋಲನ್ನು ಕಟ್ಟಿ ಆಸರೆ ಒದಗಿಸುವುದು
• ಗೊನೆಯಲ್ಲಿ ಕೊನೆಯ ಕಾಯಿಗಳು ಕಚ್ಚಿದ ನಂತರ ತುದಿಯಲ್ಲಿರುವ ಗಂಡು ಹೂ ಭಾಗವನ್ನು ಕತ್ತರಿಸುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Provide support by tying a stake to prevent the plants from falling
• Cut off the male flower part at the tip after the last fruits are harvested
• Provide conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1864, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1865, 'BANANA', NULL, N'38-50 weeks', N'38-50', 'Bunch Development Stage', 6, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1866, 'BANANA', NULL, N'>50 weeks', N'>50', 'Post harvest', 7, 'NIL', 'NIL', '• ಕೊಯ್ಲು ಮುಗಿದ ನಂತರ ಬಾಳೆ ಗಿಡಗಳನ್ನು ಕತ್ತರಿಸಿ ತೆಗೆದುಹಾಕಿ, ತೋಟದಲ್ಲಿ ಬಿದ್ದಿರುವ ಗಿಡದ ಅವಶೇಷಗಳನ್ನು ಹೊರಹಾಕುವುದು
• ಕಂದುಗಳು ಹೆಚ್ಚಿದ್ದರೆ ಅವುಗಳನ್ನು ತೆಗೆದು, ಆರೋಗ್ಯಕರವಾದವುಗಳನ್ನು ಮಾತ್ರ ಉಳಿಸಿಕೊಳ್ಳಿ
• ಸಾವಯವ ಗೊಬ್ಬರ / ಕಾಂಪೋಸ್ಟ್ ನ್ನು ಸೇರಿಸಿ ಮಣ್ಣಿನ ಫಲವತ್ತತೆಯನ್ನು ಹೆಚ್ಚಿಸಬಹುದು
• ಪನಾಮಾ ವಿಲ್ಟ್ ಮತ್ತು ಬಂಚಿ ಟಾಪ್ ರೋಗಬಾಧಿತ ಗಿಡಗಳನ್ನು ತಕ್ಷಣ ತೆಗೆದು ನಾಶ ಪಡಿಸುವುದು
• ಮುಂದಿನ ಹಂಗಾಮಿನಲ್ಲಿ ದ್ವಿದಳ ಧಾನ್ಯ ಅಥವಾ ತರಕಾರಿ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• After harvesting, cut and remove the banana plants and remove the remaining plant debris from the garden
• If there are many brown ones, remove them and keep only the healthy ones
• Soil fertility can be increased by adding organic manure/compost
• Immediately remove and destroy the plants affected by Panama wilt and Bunchy top
• It is better to rotate crops with legumes or vegetable crops in the next season', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1867, 'GINGER', 29, N'-2', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವ ಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡುವಾಗ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು. 3 ಅಡಿ ಅಗಲದ, ಅರ್ಧ ಅಡಿ ಎತ್ತರದ ಏರು ಮಡಿಗಳನ್ನು ತಯಾರಿಸಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Pre-preparation: Incorporate the recommended amount of manure into the soil while ploughing the land. Prepare 3 feet wide, half a foot high raised beds and apply the full amount of phosphorus and potash fertilizers recommended based on LRI to the soil.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1868, 'GINGER', 29, N'1', N'1', 'Planting', 1, 'NORMAL', 'YES', '• ಬಿತ್ತನೆಗಿಂತ ಮುಂಚೆ ಬೀಜದ ಗಡ್ಡೆಗಳನ್ನು 2 ಗ್ರಾಂ ಬ್ಲಿಚಿಂಗ್ ಪೌಡರ್, 1 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ ಎಂಝಡ್-72, 1 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ ಮತ್ತು 2 ಮಿ.ಲೀ. ಎಂಡೋಸಲ್ಫಾನ್ ಕೀಟನಾಶಕಗಳನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿಗೆ ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷ ನೆನೆಸಿ ನೆರಳಿನಲ್ಲಿ ಹರಡಿ ನಾಟಿಗೆ ಬಳಸುವುದರಿಂದ ಗೆಡ್ಡೆ ಕೊಳೆ ರೋಗ ಮತ್ತು ಶಲ್ಕ ಕೀಟಗಳ ಬಾಧೆಯಿಂದ ರಕ್ಷಿಸಬಹುದು.  ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 30 ರಿಂದ 40 ದಿನಗಳ ನಂತರವೂ, ಉಳಿದ ಶೇ. 50 ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 60 ರಿಂದ 70 ದಿನಗಳ ನಂತರವೂ ಕೊಡುವುದು
• ಬಿತ್ತನೆಯ ಶುಂಠಿ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, '• Before sowing, the seed tubers can be protected from tuber rot and scale insects by soaking them in a solution of 2 g bleaching powder, 1 g metalaxyl MZ-72, 1 g streptocycline and 2 ml endosulfan insecticide per liter of water for 30 minutes and spreading them in the shade before planting. 50% nitrogen should be given 30 to 40 days after planting and the remaining 50% nitrogen should be given 60 to 70 days after planting. • Sowing ginger pieces (pieces weighing at least 15-25 g) should be planted in the beds at a distance of 1 foot.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1843, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'NORMAL', 'NO', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ 3 ತಿಂಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರಿಹಾಕುವುದು', '•ಸಸ್ಯ ಹೇನು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 0.3 ಮಿ.ಲೀ. ಇಮಿಡಾಕ್ಲೊಪ್ರಿಡ್ 17.8 SL ಅಥವಾ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೇಟ್ 30 EC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು
•ಎಲೆ ಸುರುಳಿ ಹುಳುವಿನ ನಿಯಂತ್ರಣಕ್ಕೆ ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಿಗೆ 2.5 ಮಿ.ಲೀ. ಕ್ಲೋರೋಪೈರಿಫಾಸ್ 20 EC ಅಥವಾ 2.0 ಮಿ.ಲೀ. ಕ್ವಿನಾಲ್‌ಫಾಸ್ 25 EC  ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು', '• Remove all the weeds coming near the mother plant
• Intercrop 3 months after planting, provide recommended fertilizer based on LRI and till the soil', '•If aphids are found, spray 0.3 ml of Imidacloprid 17.8 SL or 1.7 ml of Dimethoate 30 EC per liter of water
•For the control of leaf curl, spray 2.5 ml of Chlorpyrifos 20 EC or 2.0 ml of Quinalphos 25 EC per liter of water', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1844, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'BELOW NORMAL', 'YES', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ 3 ತಿಂಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು', NULL, '• Remove all the weeds coming next to the mother plant
• Intercrop 3 months after planting, provide fertilizer as recommended based on LRI and till the soil', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1845, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'BELOW NORMAL', 'NO', '• ತಾಯಿ ಗಿಡದ ಪಕ್ಕದಲ್ಲಿ ಬರುವ ಎಲ್ಲಾ ಕಂದುಗಳನ್ನು ತೆಗೆಯುವುದು
• ನಾಟಿ ಮಾಡಿದ 3 ತಿಂಗಳ ನಂತರ ಅಂತರ ಬೇಸಾಯ ಮಾಡಿ, LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ರಸಗೊಬ್ಬರವನ್ನು ಒದಗಿಸಿ ಮಣ್ಣು ಏರುಹಾಕುವುದು
• ಕೃಷಿ ಹೊಂಡ, ಇತರ ಮೂಲಗಳಲ್ಲಿ ಲಭ್ಯವಿರುವ ನೀರನ್ನು ಬಳಸಿ ಸಂರಕ್ಷಣಾ ನೀರಾವರಿ ಕೊಡುವುದು', NULL, '• Remove all the weeds coming near the mother plant
• Inter-cultivate 3 months after planting, provide recommended fertilizer based on LRI and till the soil
• Provide conservation irrigation using water available from agricultural wells and other sources', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1846, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', 'ಸಿಗಟೋಕಾ ಎಲೆ ಚುಕ್ಕೆ ರೋಗಕ್ಕೆ 1.0 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 5 EC ಅಥವಾ 0.5 ಮಿ.ಲೀ. ಪ್ರೋಪಿಕೊನಾಜೋಲ್ 25 EC + ಶೇ.1 ಪೆಟ್ರೋಲಯಂ ಮಿನರಲ್ ಎಣ್ಣೆ ಅಥವಾ 1 ಗ್ರಾಂ ಥಯೋಫಿನೇಟ್ ಮಿಥೈಲ್ ಶೇ. 70 WP ಪ್ರತಿ ಲೀಟರ್ ನೀರಿನಲ್ಲಿ ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು. ರೋಗ ತೀವ್ರತೆ ಹೆಚ್ಚಾಗಿರುವ ಪ್ರದೇಶದಲ್ಲಿ ನಿರೋಧಕ ತಳಿಗಳನ್ನು ಬೆಳೆಯುವುದು ಸೂಕ್ತ', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', 'For Sigatoka leaf spot, spray 1.0 ml Propiconazole 5 EC or 0.5 ml Propiconazole 25 EC + 1% petroleum mineral oil or 1 g Thiophinate methyl 70% WP per liter of water. It is advisable to grow resistant varieties in areas where the disease is severe', NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1847, 'BANANA', NULL, N'10-19 weeks', N'10-19', 'Critical Growth stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1912, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 ಇಸಿ. ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Harvesting tubers', '•If stem and tuber borer is found, spray 0.25 ml. of Spinosad 45 SC per liter of water or mix 250 kg of neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. of Dimethoate 30 EC per liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1913, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'NO', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕಾಂಡ ಮತ್ತು ಗಡ್ಡೆ ಕೊರೆಯುವ ಹುಳು ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 0.25 ಮಿ.ಲೀ. ಸ್ಪೈನೊಸಾಡ್ 45 SC ಅನ್ನು ಬೆರೆಸಿ ಸಿಂಪಡಿಸುವುದು ಅಥವಾ ಪ್ರತಿ ಹೆಕ್ಟೇರಿಗೆ 250 ಕಿ.ಗ್ರಾಂ ಬೇವಿನ ಹಿಂಡಿ ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಮಣ್ಣಿನಲ್ಲಿ ಬೆರೆಸುವುದು
•ಥ್ರಿಪ್ಸ್ ನುಸಿ ಕಂಡುಬಂದರೆ ಲೀ. ನೀರಿಗೆ 1.7 ಮಿ.ಲೀ. ಡೈಮಿಥೋಯೆಟ್ 30 ಇಸಿ. ಬೆರೆಸಿ ಸಿಂಪಡಿಸವುದು', 'Harvesting tubers', '•If stem and tuber borer is found, spray 0.25 ml. of Spinosad 45 SC per liter of water or mix 250 kg of neem powder per hectare in the soil at the time of sowing. •If thrips is found, spray 1.7 ml. of Dimethoate 30 EC per liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
