INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1915, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'NO', 'ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಲು ನೀರಾವರಿ ಒದಗಿಸಿ ನಂತರ ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Irrigation to loosen the soil and then harvesting', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1916, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1917, 'TURMERIC', 71, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1918, 'TURMERIC', 71, N'>36', N'>36', 'Post aharvest', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲು ಮುಗಿದ ನಂತರ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ಭೂಮಿಗೆ ಸೇರಿಸುವುದು
• ಭೂಮಿಯನ್ನು ಬೇಸಿಗೆ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಸೂರ್ಯಕಿರಣಕ್ಕೆ ಒಡ್ಡುವುದು, ಇದರಿಂದ ರೋಗ ಅಥವಾ ಕೀಟಗಳ ಅವಶೇಷಗಳು ನಾಶವಾಗುತ್ತದೆ
• ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಬಹುದು
• ಮುಂದಿನ ಹಂಗಾಮಿನಲ್ಲಿ ದ್ವಿದಳ ಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Incorporate crop residues into the soil after harvest
• Deep ploughing of the soil in summer and exposure to sunlight, which destroys any disease or insect residues
• Incorporating organic manure into the soil
• Growing green manure crops can improve soil health
• It is better to rotate crops with legumes in the next season', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1885, 'GINGER', 29, N'11-24', N'11-24', 'Rhizome development stage', 3, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1886, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕೊಂಬು ಮತ್ತು ಬೇರು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದರೆ ಶೇ. 1ರ ಬೋರ್ಡೊ ದ್ರಾವಣ ಅಥವಾ ಶೇ. 0.3 ರ ಮ್ಯಾಂಕೋಜೆಬ್ ದ್ರಾವಣವನ್ನು ಬೇರು ನೆನೆಯುವಂತೆ ಸುರಿಯವುದು
•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Harvesting tubers', '•If stem and root rot disease is found, spray 1% Bordeaux mixture or 0.3% Mancozeb solution as a root drench. •If powdery mildew disease is found, spray 2 grams Mancozeb 75 WP or 1 gram Carbondiazim 50 WP dissolved in every liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1887, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'NORMAL', 'NO', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', '•ಕೊಂಬು ಮತ್ತು ಬೇರು ಕೊಳೆಯುವ ರೋಗ ಕಂಡು ಬಂದರೆ ಶೇ. 1ರ ಬೋರ್ಡೊ ದ್ರಾವಣ ಅಥವಾ ಶೇ. 0.3 ರ ಮ್ಯಾಂಕೋಜೆಬ್ ದ್ರಾವಣವನ್ನು ಬೇರು ನೆನೆಯುವಂತೆ ಸುರಿಯವುದು
•ಚಿಬ್ಬು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಮ್ಯಾಂಕೋಜೆಬ್ 75 WP ಅಥವಾ 1 ಗ್ರಾಂ ಕಾರ್ಬನ್‌ಡೈಜಿಮ್ 50 WP ಅನ್ನು ಕರಗಿಸಿ ಸಿಂಪರಣೆ ಮಾಡುವುದು', 'Harvesting tubers', '•If stem and root rot disease is found, spray 1% Bordeaux mixture or 0.3% Mancozeb solution as a root drench. •If powdery mildew disease is found, spray 2 grams Mancozeb 75 WP or 1 gram Carbondiazim 50 WP dissolved in every liter of water', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1888, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'YES', 'ಗೆಡ್ಡೆಗಳನ್ನು ಕೊಯ್ಲು ಮಾಡುವುದು', 'ದುಂಡಾಣು ಸೊರಗು ರೋಗ ಕಂಡುಬಂದಲ್ಲಿ ಪ್ರತಿ ಲೀಟರ್‍ ನೀರಿಗೆ 2 ಗ್ರಾಂ ಬ್ಲೀಚಿಂಗ್‍ ಪೌಡರ್‍ ಮತ್ತು 1 ಗ್ರಾಂ ಮೆಟಾಲಾಕ್ಸಿಲ್‍ MZ 72 WP ಅನ್ನು ಬೆರೆಸಿ  ತಯಾರಿಸಿದ 3-5 ಲೀಟರ್‍ ದ್ರಾವಣವನ್ನು ರೋಗ ಪೀಡಿತ ಹಾಗೂ ಅದರ ಗಿಡಗಳ ಬುಡಕ್ಕೆ ನೆನೆಯುವಂತೆ ತೊಯಿಸುವುದು', 'Harvesting tubers', 'If roundworm disease is found, 3-5 liters of a solution prepared by mixing 2 grams of bleaching powder and 1 gram of Metalaxyl MZ 72 WP per liter of water and drench the affected plants and their roots', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1889, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'BELOW NORMAL', 'NO', 'ಮಣ್ಣನ್ನು ಸಡಿಲಗೊಳಿಸಲು ನೀರಾವರಿ ಒದಗಿಸಿ ನಂತರ ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'Irrigation to loosen the soil and then harvesting', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1890, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'YES', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', 'ಗಡ್ಡೆ ಕೊಳೆ ರೋಗ ಕಂಡು ಬಂದಲ್ಲಿ ರೋಗಗ್ರಸ್ಥ ಗಡ್ಡೆಗಳನ್ನು ತೆಗೆದು ಹಾಕಿ, ನಂತರ ಪ್ರತಿ ಲೀಟರ್‍3 ನೀರಿಗೆ 3 ಗ್ರಾಂ ಕಾಪರ್‍ ಆಕ್ಸಿಕ್ಲೋರೈಡ್‍ 50 WP ಅನ್ನು ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣವನ್ನು ರೋಗ ಬಂದ ಮಡಿಗೆ ಹಾಗೂ ಸುತ್ತಮುತ್ತಲಿನ ಮಡಿಗಳಿಗೆ ಹಾಕುವುದು', 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', 'If tuber rot is detected, remove the diseased tubers and then apply a solution prepared by mixing 3 grams of copper oxychloride 50 WP per 3 liters of water to the affected tuber and surrounding tubers', 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1891, 'GINGER', 29, N'25-36', N'25-36', 'Maturity stage', 4, 'ABOVE NORMAL', 'NO', 'ಹಿಂದಿನ ದಿನಗಳಲ್ಲಿ ಅಧಿಕ ಮಳೆಯಾಗಿದ್ದರೆ, ಜಮೀನಿನಲ್ಲಿ ನೀರು ನಿಲ್ಲದಂತೆ ಬಸಿದುಹೋಗಲು ಅನುವುಮಾಡಿಕೊಡಿ.ಕೊಯ್ಲು ಮಾಡುವುದು', NULL, 'If there has been heavy rainfall in the past few days, allow the water to drain away so that it does not stagnate in the field. Harvesting', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1892, 'GINGER', 29, N'>36', N'>36', 'Post harvest stage', 5, 'NIL', 'NIL', '• ಕೊಯ್ಲು ಮುಗಿದ ನಂತರ ಬೆಳೆಯುಳಿಕೆಗಳನ್ನು ಭೂಮಿಗೆ ಸೇರಿಸುವುದು
• ಭೂಮಿಯನ್ನು ಬೇಸಿಗೆ ಆಳ ಉಳುಮೆ ಮಾಡಿ ಸೂರ್ಯಕಿರಣಕ್ಕೆ ಒಡ್ಡುವುದು, ಇದರಿಂದ ರೋಗ ಅಥವಾ ಕೀಟಗಳ ಅವಶೇಷಗಳು ನಾಶವಾಗುತ್ತದೆ
• ಸಾವಯವ ಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿಗೆ ಸೇರಿಸುವುದು
• ಹಸಿರೆಲೆ ಗೊಬ್ಬರದ ಬೆಳೆಗಳನ್ನು ಬೆಳೆಸಿ ಮಣ್ಣಿನ ಆರೋಗ್ಯ ಸುಧಾರಿಸಬಹುದು
• ಮುಂದಿನ ಹಂಗಾಮಿನಲ್ಲಿ ದ್ವಿದಳ ಧಾನ್ಯ ಬೆಳೆಗಳೊಂದಿಗೆ ಬೆಳೆ ಪರಿವರ್ತನೆ ಮಾಡುವುದು ಉತ್ತಮ', NULL, '• Incorporate crop residues into the soil after harvest
• Deep ploughing of the soil in summer and exposure to sunlight, which destroys any disease or insect residues
• Incorporating organic manure into the soil
• Growing green manure crops can improve soil health
• It is better to rotate crops with legumes in the next season', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1893, 'TURMERIC', 71, N'-2', N'-2', 'Preparation', 0, 'NIL', 'NIL', 'ಪೂರ್ವ ಸಿದ್ದತೆ:  ಭೂಮಿಯನ್ನು ಉಳುಮೆ ಮಾಡುವಾಗ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಕೊಟ್ಟಿಗೆಗೊಬ್ಬರವನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು. 3 ಅಡಿ ಅಗಲದ, ಅರ್ಧ ಅಡಿ ಎತ್ತರದ ಏರು ಮಡಿಗಳನ್ನು ತಯಾರಿಸಿ LRI ಆಧರಿಸಿ ಶಿಫಾರಸ್ಸು ಮಾಡಿದ ಪೂರ್ತಿ ಪ್ರಮಾಣದ ರಂಜಕ ಮತ್ತು ಪೊಟ್ಯಾಷ್ ಯುಕ್ತ ಗೊಬ್ಬರಗಳನ್ನು ಮಣ್ಣಿನಲ್ಲಿ ಸೇರಿಸುವುದು', NULL, 'Pre-preparation: Incorporate the recommended amount of manure into the soil while ploughing the land. Prepare 3 feet wide, half a foot high raised beds and apply the full amount of phosphorus and potash fertilizers recommended based on LRI to the soil.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1894, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'NORMAL', 'YES', '• ಬಿತ್ತನೆಗಿಂತ ಮುಂಚೆ ಬೀಜದ ಗಡ್ಡೆಗಳನ್ನು 2 ಗ್ರಾಂ ಬ್ಲಿಚಿಂಗ್ ಪೌಡರ್, 1 ಗ್ರಾಂ ಮೆಟಲಾಕ್ಸಿಲ್ ಎಂಝಡ್-72, 1 ಗ್ರಾಂ ಸ್ಟ್ರೆಪ್ಟೋಸೈಕ್ಲಿನ್ ಮತ್ತು 2 ಮಿ.ಲೀ. ಎಂಡೋಸಲ್ಫಾನ್ ಕೀಟನಾಶಕಗಳನ್ನು ಪ್ರತಿ ಲೀ. ನೀರಿಗೆ ಬೆರೆಸಿ ತಯಾರಿಸಿದ ದ್ರಾವಣದಲ್ಲಿ 30 ನಿಮಿಷ ನೆನೆಸಿ ನೆರಳಿನಲ್ಲಿ ಹರಡಿ ನಾಟಿಗೆ ಬಳಸುವುದರಿಂದ ಗೆಡ್ಡೆ ಕೊಳೆ ರೋಗ ಮತ್ತು ಶಲ್ಕ ಕೀಟಗಳ ಬಾಧೆಯಿಂದ ರಕ್ಷಿಸಬಹುದು.  ಶೇ. 50ರ ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 30 ರಿಂದ 40 ದಿನಗಳ ನಂತರವೂ, ಉಳಿದ ಶೇ. 50 ಸಾರಜನಕವನ್ನು ನಾಟಿ ಮಾಡಿದ 60 ರಿಂದ 70 ದಿನಗಳ ನಂತರವೂ ಕೊಡುವುದು
• ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, '• Before sowing, the seed tubers can be protected from tuber rot and scale insects by soaking them in a solution of 2 g bleaching powder, 1 g metalaxyl MZ-72, 1 g streptocycline and 2 ml endosulfan insecticide per liter of water for 30 minutes and spreading them in the shade before planting. 50% nitrogen should be given 30 to 40 days after planting and the remaining 50% nitrogen should be given 60 to 70 days after planting. • Sowing pieces (pieces weighing at least 15-25 g) should be planted in the furrows at a distance of 1 foot.', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1895, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'NORMAL', 'NO', 'ಮಳೆಯ ಮುನ್ಸೂಚನೆಯನ್ನು ಗಮನದಲ್ಲಿಟ್ಟುಕೊಂಡು ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'Planting of seed pieces (pieces weighing at least 15-25 grams) in furrows at a distance of 1 foot, keeping in mind the rainfall forecast', NULL, 'NIL', NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
INSERT INTO "KSNDMC"."HORTI_WEEKS_CROPS_ADVISORY" ("HORTI_WEEK_ADVISORY_ID", "CROP_NAME", "CROP_ID", "CROP_PERIOD_IN_WEEKS", "WEEKS_IN_NUMBER", "GROWTH_STAGE", "GROWTH_STAGE_NUMBER", "PREVIOUS_WEEK_RAINFALL", "NEXT_WEEK_RAINFALL_FORECAST", "AGRICULTURE_MEASURES_KN", "PLANT_PROTECTION_MEARURES_KN", "AGRICULTURE_MEASURES_EN", "PLANT_PROTECTION_MEARURES_EN", "REMARKS", "CROP_MATURITY_IN_DAYS", "REGION_CODE", "CREATED_DATE", "CREATED_BY", "UPDATED_DATE", "UPDATED_BY", "IS_ACTIVE") VALUES (1896, 'TURMERIC', 71, N'1', N'1', 'Planting', 1, 'BELOW NORMAL', 'YES', 'ನೀರಾವರಿ ಸೌಲಭ್ಯವಿದ್ದಲ್ಲಿ ಬಿತ್ತನೆಯ ತುಂಡುಗಳನ್ನು (ಕನಿಷ್ಠ 15-25 ಗ್ರಾಂ ತೂಕವಿರುವ ತುಂಡುಗಳು) ಮಡಿಗಳಲ್ಲಿ 1 ಅಡಿ ಅಂತರದಲ್ಲಿ ನಾಟಿ ಮಾಡುವುದು', NULL, 'If irrigation facilities are available, planting of seed pieces (pieces weighing at least 15-25 grams) in beds at a distance of 1 foot', NULL, NULL, NULL, 'SIK', TO_TIMESTAMP('2026-05-26 15:47:54', 'YYYY-MM-DD HH24:MI:SS'), NULL, NULL, NULL, 'Y');
